(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.2"]={"from":48,"a":[["\u0003ומיגנזו כולי עלמא\u0004 \u0005[ומתחבאים הכל].\u0006 \u0003כי אתי\u0004 \u0003אמר ליה\u0004 \u0005[כאשר בא\u0006 ראש הנהר היה \u0005אומר לו]\u0006 אבי ר' זירא: \u0003ממאן נבעי\u0004 \u0005[\u0006\u0005ממי נגבה],\u0006 שנראה שעיר מעוטת תושבים היא וצריך להטיל עליה רק מיסים מועטים.","\u0003כי ניחא נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 עמד למות\u0005]\u0006 \u0003אמר להו\u0004 \u0005[להם\u0006 לעומדים סביבו\u0005]:\u0006 \u0003שקולו תליסר מעי דציירי\u0004 \u0005[קחו שלש עשרה מעות הצרורות]\u0006 \u0003לי בסדינאי\u0004 \u0005[בסדיני]\u0006 \u0003והדרו ליה לפלניא\u0004 \u0005[והחזירו לו לפלוני],\u0006 \u0003דשקלתינהו מיניה\u0004 \u0005[שלקחתי אותן ממנו]\u0006 \u0003ולא איצטריכו לי\u0004 \u0005[הצטרכתי להן]\u0006 לשלם אותם מיסים עבורו ולכן אפשר עתה להחזיר אותם. ולמדנו מכאן שהיו גובי מיסים יראי שמים, ובוודאי שאין לפסול אותם משום היותם גבאים.","שנינו במשנה ש\u0003אמר\u0004 \u0003ר' שמעון: בתחילה היו קוראין אותן \"אוספי שביעית\"\u0004 ואחר כך משרבו האנסים חזרו לקרותם \"סוחרי שביעית\".","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 שלא ברור מה רצה ר' שמעון ללמדנו בדברים אלה. \u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 \u0003בתחילה היו אומרים: אוספי שביעית,\u0004 שהם אנשים האוספים לעצמם הרבה מפירות השביעית — \u0003כשרין, סוחרין\u0004 בשביעית — \u0003פסולין.\u0004","ואולם \u0003משרבו ממציאי מעות לעניים\u0004 שיאספו בשבילם, \u0003ואזלי\u0004 \u0005[והולכים]\u0006 ה\u0003עניים ואספי להו ומייתו\u0004 \u0005[ואוספים להם ומביאים],\u0006 שאף אוספי השביעית עשו הדבר כעין מקצוע ומסחר, \u0003חזרו לומר: אחד זה ואחד זה פסולין.\u0004","\u0003קשו\u0004 \u0005[התקשו]\u0006 \u0003בה\u0004 בהסברה זו \u0003בני\u0004 החכם \u0003רחבה: האי\u0004 \u0005[זה,\u0006 הביטוי\u0005]\u0006 \u0003\"משרבו האנסים\"\u0004 אינו מדוייק איפוא, כי \u0003\"משרבו התגרין\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005].\u0006","\u0003אלא\u0004 יש לפרש פירוש אחר ולומר כי \u0003בתחילה היו אומרים: אחד זה ואחד זה,\u0004 בין האוספים ובין הסוחרים \u0003—\u0004 \u0003פסולין, משרבו האנסין, ומאי נינהו\u0004 \u0005[ומה הם]\u0006 — \u0003ארנונא,\u0004 שהשלטונות היו מטילים מיסים כבדים על הקרקעות ולא היו מבחינים בין שנת השביעית לשנים אחרות, נעשה הלחץ על שומרי השביעית כבד מנשוא, \u0003כ\u0004דרך שהיה \u0003מכריז\u0004 \u0003ר' ינאי: פוקו\u0004 \u0005[צאו]\u0006 \u0003וזרעו ב\u0004שנת ה\u0003שביעית משום ארנונא\u0004 שעליכם לשלם. \u0003חזרו לומר: אוספין\u0004 לבד \u0003כשרין, סוחרין פסולין.\u0004","כיון שדובר כאן בענין שמירת השביעית מביאים מעשה שהיה: \u0003ר' חייא בר זרנוקי ו\u0004\u0003ר' שמעון בן יהוצדק הוו קאזלי\u0004 \u0005[היו הולכים]\u0006 \u0003לעבר שנה בעסיא,\u0004 שמפני סיבות שונות לא יכלו לעשות את עיבור השנה בארץ ישראל. \u0003פגע בהו\u0004 \u0005[פגש אותם]\u0006 \u0003ריש לקיש איטפיל בהדייהו\u0004 \u0005[נספח אליהם].\u0006 \u0003אמר: איזיל איחזי היכי עבדי עובדא\u0004 \u0005[אלך\u0006 ו\u0005אראה כיצד עושים\u0006 הם \u0005מעשה],\u0006 כלומר, כיצד נעשה ענין זה של עיבור השנה בפועל.","\u0003חזייה לההוא גברא דקא כריב\u0004 \u0005[ראה אדם אחד שחורש]\u0006 ושנת שביעית היתה. \u0003אמר להן: כהן וחורש,\u0004 כלומר, ראו כהן זה שחורש בשנת השביעית! \u0003אמרו לו: יכול לומר אגיסטון\u0004 (שכיר) \u0003אני בתוכו\u0004 וכיון שאני שכירו של גוי ואני עובד בקרקע — מותר.","\u0003תו חזייה לההוא גברא דהוה כסח בכרמי\u0004 \u0005[שוב ראה אדם אחד שהיה זומר בכרמים]\u0006 \u0003אמר להן: כהן וזמר\u0004 את הכרם בשביעית! \u0003אמרו לו:\u0004 \u0003יכול לומר לעקל בית הבד אני צריך,\u0004 שאינו זומר את העצים לצורך עיבודם אלא לעשות כעין סל לאסוף בו את הזיתים שסוחטים בבית הבד, ודבר זה מותר אף בשנת השביעית. \u0003אמר להם: הלב יודע אם לעקל אם לעקלקלות\u0004 (לרמיה).","ושואלים: \u0003הי\u0004 \u0005[איזה\u0006 דבר, איזה מעשה] \u0003אמר להו ברישא\u0004 \u0005[להם תחילה]?\u0006 \u0003אילימא הא קמייתא\u0004 \u0003אמר להו ברישא\u0004 \u0005[אם תאמר\u0006 כי את \u0005זו הראשונה אמר להם בתחילה]\u0006 כסדר הדברים כאן, \u0003הא נמי לימרו\u0004 \u0005[שיאמרו גם כן\u0006 במקרה \u0005זה]\u0006 \u0003אגיסטון אני בתוכו\u0004 והרי תירוץ זה הוא טוב יותר מאשר לומר שהוא נזקק במקרה לזמורות. \u0003אלא הא\u0004 \u0005[זה]\u0006 המעשה בזומר \u0003אמר ליה ברישא\u0004 \u0005[זה\u0006 המעשה בזומר \u0005אמר לו,\u0006 להם \u0005תחילה]\u0006 \u0003והדר\u0004 \u0005[וחזר]\u0006 ו\u0003אמר להו הך\u0004 \u0005[\u0006דבר \u0005זה].\u0006","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003כהן?\u0004 מדוע סבר ריש לקיש שהאיש העושה זאת כהן הוא? ומשיבים: \u0003משום דחשידי\u0004 \u0005[ש\u0006הכהנים \u0005חשודים]\u0006 על ה\u0003שביעית\u0004 וראיה לדבר ממה ששנינו:","\u0003דתנן, סאה תרומה\u0004 המותרת באכילה רק לכהנים \u0003שנפלה למאה סאין של\u0004 פירות \u0003שביעית\u0004 — \u0003תעלה,\u0004 כלומר, הריהי מתבטלת והכל נאכל בשביעית לפני זמן הביעור. ב\u0003פחות מיכן\u0004 — \u0003ירקבו\u0004 כולם, שהרי אסור לישראלים לאכלם משום התרומה המעורבת בהם, האסורה לישראל.","\u0003והוינן\u0004 \u0005[ועסקנו,\u0006 עיינו\u0005]\u0006 \u0003בה,\u0004 בבעיה זו: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003ירקבו\u0004 כל הסאין כולם? \u0003ימכרנו\u0004 הכל \u0003לכהן בדמי תרומה\u0004 שמחירה זול יותר משל חולין שהרי אינה נאכלת אלא לכהנים \u0003חוץ מדמי אותה סאה\u0004 שהיא תרומה בעצמה ויאכל הכהן הכל בקדושת תרומה, ויהיו הכל נהנים!","\u0003ו\u0004בתשובה לכך \u0003אמר רב חייא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: זאת אומרת\u0004 ש\u0003נחשדו כהנים\u0004 על ה\u0003שביעית,\u0004 שלא ינהגו בכל התבואה קדושת שביעית כראוי ויאכלו את הפירות אף לאחר זמן הביעור. שהכהנים סבורים שאינם חייבים לשמור את קדושת השביעית כיון שלדעתם אף פירות שביעית שלהם הם, כפי שהתרומה שלהם, שאף השביעית ממצוות הארץ היא, ומשום חשד זה אמר ריש לקיש שמן הסתם כהן הוא זה.","לענין המעשה כיון שהרבה להם ריש לקיש בהערות, \u0003אמרו: טרודא\u0004 \u0005[טרדן]\u0006 \u0003הוא דין\u0004 \u0005[זה]\u0006 ורצו לסלקו מעליהם. \u0003כי מטו להתם, סליקו לאיגרא, שלפוה לדרגא מתותיה\u0004 \u0005[כאשר הגיעו לשם, עלו לגג,\u0006 ו\u0005נטלו את הסולם מתחתיו]\u0006 שישאר זמן בעליית הגג ולא יוכל להמשיך ללוותם.","לאחר זמן \u0003אתא לקמיה\u0004 \u0005[בא\u0006 ריש לקיש \u0005לפני]\u0006 \u0003ר' יוחנן, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בני אדם החשודין על השביעית\u0004 האם \u0003כשרין\u0004 הם \u0003לעבר שנה?\u0004 ששני החכמים שנשלחו לעיבור השנה נראים כמזלזלים בקדושת השביעית.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 בתשובה לדברי עצמו: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003לי,\u0004 כלומר, אפשר לסמוך עליהם \u0003מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 לענין אותם \u0003שלשה רועי בקר\u0004 שאירע שהתאמתו דבריהם ועיברו את השנה, שיש לומר גם אז כי \u0003רבנן אחושבנייהו סמוך\u0004 \u0005[חכמים על חשבונם\u0006 הם \u0005סומכים]\u0006 ולא על שלושה רועי הבקר הללו.","\u0003והדר\u0004 \u0005[וחזר]\u0006 ריש לקיש ו\u0003אמר:\u0004 \u0003לא דמי\u0004 \u0005[אין\u0006 הדבר \u0005דומה],\u0006 שכן \u0003התם הדור אימנו רבנן ועברוה לההוא שתא\u0004 \u0005[שם חזרו\u0006 ו\u0005נמנו חכמים ועיברו אותה שנה]\u0006 ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 במקרה זה, הלא \u0003קשר רשעים הוא,\u0004 שאין אלה ראויים לכך, \u0003וקשר רשעים אינו מן המנין\u0004 שאי אפשר למנותם, ואי אפשר לסמוך עליהם. \u0003אמר\u0004 \u0003ר' יוחנן: דא עקא\u0004 \u0005[זו צרה]\u0006 זהו באמת קושי.","\u0003כי אתו לקמיה\u0004 \u0005[כאשר באו\u0006 ר' חייא בר זרנוקי ור' שמעון בן יהוצדק \u0005לפני]\u0006 \u0003ר' יוחנן\u0004 ושמעו מה שאמר עליהם ריש לקיש לר' יוחנן, \u0003אמרו ליה\u0004 \u0005[לו]\u0006 בהתמרמרות: \u0003קרי לן\u0004 \u0005[קרא\u0006 ריש לקיש \u0005לנו]\u0006 \u0003\"רועי בקר\" ולא אמר ליה מר\u0004 \u0005[לו אדוני]\u0006 \u0003ולא מידי\u0004 \u0005[כלום]?\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 בדרך דחייה: \u0003ואי קרי לכו\u0004 \u0005[ואם היה קורא לכם]\u0006 \u0003\"רועי צאן\"\u0004 שהם פסולים לעדות ולדין, \u0003מאי אמינא ליה\u0004 \u0005[\u0006\u0005מה הייתי אומר לו]?\u0006 שהרי הוא צודק בדבריו.","אגב הזכרת הענין שקשר רשעים אינו מן המנין מבררים: \u0003מאי\u0004 \u0005[מהו]\u0006 ענין \u0003קשר רשעים?\u0004 מסופר מעין זה כי \u0003שבנא\u0004 שהיה סוכן ושר אצל חזקיה המלך היה תקיף וחשוב מאד \u0003הוה דריש בתליסר רבוותא\u0004 \u0005[היה דורש בשלש עשרה רבבות],\u0006 שהיה לו קהל גדול כל כך שהיה שומע דברי תורתו ונשמע לדבריו ואילו \u0003חזקיה\u0004 המלך עצמו \u0003הוה דריש בחד סר רבוותא\u0004 \u0005[היה דורש באחת עשרה רבבות]\u0006","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003סנחריב וצר עלה\u0004 \u0005[עליה]\u0006 על \u0003ירושלים,\u0004 \u0003כתב שבנא פתקא\u0004 \u0005[פתק],\u0006 \u0003שדא בגירא\u0004 \u0005[\u0006ו\u0005זרק אותו\u0006 מעבר לחומה \u0005בחץ].\u0006 ובאותו פתק כתב: \u0003שבנא וסיעתו השלימו\u0004 עם סנחריב ומוכנים להכנע, \u0003חזקיה וסיעתו לא השלימו.\u0004 והיכן נרמז הדבר — \u0003שנאמר:\u0004 \u0003\"כי הנה הרשעים ידרכון קשת כוננו חצם על יתר\"\u0004 (תהלים יא, ב).","\u0003הוה קא מסתפי\u0004 \u0005[היה מתיירא]\u0006 \u0003חזקיה,\u0004 \u0003אמר דילמא\u0004 \u0005[שמא]\u0006 \u0003חס ושלום נטיה דעתיה דקודשא בריך הוא בתר רובא\u0004 \u0005[נוטה דעתו של הקדוש ברוך הוא אחר הרוב],\u0006 ו\u0003כיון דרובא מימסרי אינהו נמי מימסרי\u0004 \u0005[שרובם\u0006 רוצים \u0005להימסר\u0006 בידי האשורים הרי \u0005אלה\u0006 שאינם חפצים בכך \u0005גם כן ימסרו].\u0006 \u0003בא\u0004 ישעיה ה\u0003נביא ואמר לו: \"לא תאמרון קשר לכל אשר יאמר העם הזה קשר\"\u0004 (ישעיה ח, יב), \u0003כלומר,\u0004 קשר זה \u0003קשר רשעים הוא, וקשר רשעים אינו מן המנין\u0004 ואין אתה צריך להתחשב בכך שמניינם מרובה.","\u0003הלך\u0004 לו שבנא \u0003לחצב לו קבר בקברי בית דוד,\u0004 שסבר שיתנו בידו את המלוכה, \u0003בא\u0004 ישעיה ה\u0003נביא ואמר לו: \"מה לך פה ומי לך פה כי חצבת לך פה קבר\u0004 חוצבי מרום קברו חוקקי בסלע משכן לו. \u0003הנה ה' מטלטלך טלטלה גבר\u0004 ועוטך עטה",", ודרך אגב העיר \u0003רב\u0004 על המילים הללו שמכאן למדנו כי \u0003טלטולא דגברא קשי מדאיתתא\u0004 \u0005[טלטול של גבר קשה משל אשה],\u0006 שהרי לטלטול גדול הוא קורא \"טלטלת גבר\". \u0005(ישעיה כב, טז –יז)\u0006.","על הנאמר \u0003\"ועטך עטה\" אמר\u0004 \u0003ר' יוסי בר' חנינא: מלמד שפרחה בו צרעת\u0004 בשבנא; \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ועטך עטה\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 במצורע: \u0003\"\u0004והצרוע אשר בו הנגע בגדיו יהיו פרומים וראשו יהיה פרוע \u0003ועל שפם יעטה\"\u0004 (ויקרא יג, מה).","עוד נאמר בשבנא: \u0003\"צנוף יצנפך צנפה כדור אל ארץ רחבת ידים\u0004 שמה תמות ושמה מרכבות כבודך קלון בית אדוניך\u0003\"\u0004 (ישעיה כב, יח) \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הוא\u0004, שבנא, \u0003ביקש קלון בית אדוניו, לפיכך נהפך כבודו\u0004 שלו \u0003לקלון.\u0004 וכך אירע לו: \u0003כי הוה נפיק איהו\u0004 \u0005[כאשר היה יוצא הוא\u0006 מן השער\u0005]\u0006 להימסר בידי האשורים \u0003אתא\u0004 \u0005[בא]\u0006 המלאך \u0003גבריאל אחדיה לדשא באפי משרייתיה\u0004 \u0005[ואחז את השער בפני מחנהו]\u0006 ולא יכלו לצאת אחריו ויצא רק הוא לבדו."],["\u0003אמרו ליה\u0004 \u0005[לו]\u0006 האשורים: \u0003משירייתך היכא\u0004 \u0005[מחנך היכן הוא]?\u0006 \u0003אמר: הדרו\u0004 \u0005[חזרו]\u0006 \u0003בי\u0004 ולא קיימו מה שהבטיחוני. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אם כן אחוכי קא מחייכת בן\u0004 \u0005[לצחק אתה מצחק בנו]\u0006 שהולכת אותנו שולל בטענה שמאחריך עומד מחנה גדול של תומכים?! \u0003נקבוהו בעקביו ותלאוהו בזנבי סוסיהם, והיו מגררין אותו על הקוצים ועל הברקנין.\u0004","\u0003אמר ר' אלעזר: שבנא בעל הנאה היה,\u0004 כלומר, נואף היה. ומהיכן אתה למד זאת? — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"לך בא אל הסכן הזה\u0004 אל שבנא אשר על הבית\u0003\"\u0004 (ישעיה כב, טו), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 באבישג השונמית: \u0003\"ותהי לו סכנת\u0004 ושכבה בחיקך וחם לאדוני המלך\u0003\"\u0004 (מלכים א' א, ב), שמפני כן קראו הנביא \"סוכן\" לרמז שהיה מחמם עצמו בעבירה.","\u0003ואומר: \"כי השתות יהרסון צדיק מה פעל\"\u0004 (תהלים יא, ג). \u0003רב יהודה ורב עינא\u0004 פירשו מקרא זה, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אילו חזקיה וסיעתו נהרסים, צדיק מה פעל? וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אילו בית המקדש יהרס, צדיק מה פעל? ועולא אמר: אילו מחשבותיו של אותו רשע,\u0004 סנחריב, \u0003אינן נהרסות, צדיק מה פעל?\u0004","ומבררים את השיטות: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שהכוונה היא \u0003אילו מחשבותיו של אותו רשע\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"כי השתות יהרסון\"\u0004 כלומר, מחשבות רשעים.","\u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 כי הכוונה היא ל\u0003בית המקדש, נמי\u0004 \u0005[גם כן]\u0006 יש לזה בסיס, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אבן היתה שם\u0004 בבית המקדש \u0003מימות נביאים הראשונים, ו\"שתייה\" היתה נקראת,\u0004 ולכן נאמר \"השתות יהרסון\" — הוא הריסת אבן השתיה.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי הכוונה ל\u0003חזקיה וסיעתו, היכא אשכחן צדיקי דאיקרו\u0004 \u0005[היכן מצאנו שהצדיקים נקראו]\u0006 \u0003\"שתות\"?\u0004","ומשיבים, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004מקים מעפר דל מאשפות ירים אביון להושיב עם נדיבים וכסא כבוד ינחילם \u0003כי לה' מצקי ארץ וישת עליהם תבל\"\u0004 (שמואל א' ב, ח). \u0003ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור מכאן]:\u0006 \u0003\"הפלא עצה הגדיל תושיה\"\u0004 (ישעיה כח, כט).","בקשר למקרא זה \u0003אמר ר' חנן: למה נקרא שמה\u0004 של התורה \u0003\"תושיה\"\u0004 — \u0003מפני שהיא מתשת כחו של אדם\u0004 העוסק בה. \u0003דבר אחר: \"תושיה\"\u0004 יש להבין כעין נוטריקון: \u0003שניתנה בחשאי מפני השטן,\u0004 שלא יקטרג ויאמר שאין ישראל ראויים לה. \u0003דבר אחר: \"תושיה\"\u0004 נוטריקון \"תוהו־שתיה\", כלומר, \u0003דברים\u0004 הנראים לכאורה \u0003של תוהו\u0004 תלושים וזרים ובכל זאת \u0003העולם משותת\u0004 (מיוצב) \u0003עליהם.\u0004","\u0003אמר עולא: מחשבה\u0004 ודאגת לב \u0003מועלת,\u0004 כלומר, גורמת ומשפיעה להפריע \u0003אפילו לדברי תורה, שנאמר: \"מפר מחשבות ערומים ולא תעשינה ידיהם תשיה\"\u0004 (איוב ה, יב).","\u0003אמר רבה: אם עסוקין\u0004 ללמוד \u0003לשמה\u0004 — \u0003אינה מועלת\u0004 (משפיעה), \u0003שנאמר: \"רבות מחשבות בלב איש ועצת ה' היא תקום\"\u0004 (משלי יט, כא), כלומר, \u0003עצה שיש בה דבר ה' היא תקום לעולם\u0004 ואינה ניזוקה.","שנינו במשנה ש\u0003אמר ר' יהודה: אימתי\u0004 פסולים אנשים אלה כגון המשחקים בקוביה ומלווים בריבית — בזמן שאין להם מלאכה אלא היא. \u0003אמר\u0004 \u0003ר' אבהו אמר ר' אלעזר: הלכה כ\u0004שיטת \u0003ר' יהודה.\u0004","\u0003ואמר ר' אבהו אמר ר' אלעזר: כולן,\u0004 כל פסולים אלה שמדברי חכמים, \u0003צריכין הכרזה בבית דין\u0004 שיכריזו שאדם פלוני נמצא עוסק בדברים אלה ונפסל בבית הדין.","ולענין זה בדינו של \u0003רועה פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה רב אחא ורבינא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: בעי\u0004 \u0005[צריך]\u0006 \u0003הכרזה\u0004 עליו שהוא רועה ולכך הוא פסול, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003הכרזה,\u0004 שמאליו הוא נפסל.","ומעירים, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003הכרזה\u0004 — \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר רב יהודה אמר רב\u0004 ש\u0003סתם רועה פסול,\u0004 ולפיכך אינו צריך הכרזה מיוחדת, \u0003אלא למאן דאמר בעי\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר\u0006 ש\u0005צריך]\u0006 \u0003הכרזה\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"סתם רועה פסול\"?\u0004","ומשיבים: \u0003דבסתמא מכרזינן עליה\u0004 \u0005[שבסתם מכריזים עליו]\u0006 שהוא פסול אם מוצאים שעוסק בקביעות באומנות זו, ואין צריך שיוכיחו שהוא רועה את צאנו בשדות אחרים.","מסופר: \u0003ההיא מתנה דהוו חתימי עלה תרין\u0004 \u0005[אותו\u0006 שטר \u0005מתנה שהיו חתומים עליו שני\u0006 אנשים\u0005]\u0006 שהיו פסולים בתורת \u0003גזלנין.\u0004 \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רב פפא בר שמואל לאכשורה\u0004 \u0005[להכשיר אותה]\u0006 ולא לפסול את השטר בשל העדים. וטעמו — \u0003דהא\u0004 \u0005[שהרי]\u0006 עדיין \u0003לא אכרזינן עלייהו\u0004 \u0005[הכרזנו עליהם]\u0006 שהם פסולים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: נהי דבעינן\u0004 \u0005[אם אמנם צריכים אנו]\u0006 \u0003הכרזה בגזלן\u0004 הרי זה רק בגזלן \u0003דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 אבל \u0003בגזלן דאורייתא\u0004 \u0005[שמדברי תורה]\u0006 \u0003מי בעינן\u0004 \u0005[האם צריכים אנו]\u0006 \u0003הכרזה?\u0004 ומאליו הוא נפסל.","ומוסיפים פסולים נוספים וה\u0003סימן: דבר ועריות גנב.\u0004","\u0003אמר רב נחמן אוכלי דבר אחר,\u0004 אנשים הנהנים מצדקה שנותנים הגויים שיש בכך משום חילול ה' — \u0003פסולין לעדות,\u0004 שהם נחשבים כרשעים משום שהם מראים שבשל ממון מוכנים הם אף לכך.","ומעירים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים שהם נוטלים \u0003בפרהסיא,\u0004 \u0003אבל\u0004 אם נוטלים \u0003בצינעה\u0004 — \u0003לא. ובפרהסיא נמי לא אמרן\u0004 \u0005[גם כן אין אנו אומרים]\u0006 \u0003אלא\u0004 באופן ש\u0003אפשר ליה לאיתזוני\u0004 \u0005[לו להיזון]\u0006 \u0003בצינעה, וקא מבזי נפשיה\u0004 \u0005[והוא מבזה\u0006 את \u0005עצמו]\u0006 \u0003בפרהסיא,\u0004 \u0003אבל\u0004 אם \u0003לא אפשר ליה\u0004 \u0005[לו]\u0006 להיזון בדרך אחרת — \u0003חיותיה הוא\u0004 \u0005[חיותו היא]\u0006 ואינו צריך למסור את נפשו על כך.","\u0003אמר רב נחמן: החשוד על העריות\u0004 שיש שמועה רעה עליו שהוא חוטא בעריות, בכל זאת \u0003כשר לעדות. אמר רב ששת, עני מרי\u0004 \u0005[ענה אדוני]:\u0006 אותו אדם מלקים אותו \u0003ארבעין בכתפיה\u0004 \u0005[\u0006\u0005ארבעים\u0006 מלקות \u0005בכתפיו]\u0006 משום חשד זה \u0003ו\u0004בכל זאת אומר אתה שהוא \u0003כשר?\u0004 שלפי ההלכה מלקים אדם גם על שמועה רעה שיוצאת עליו אף שאין לכך הוכחה גמורה.","ומעירים: \u0003אמר רבא: ומודה רב נחמן לענין עדות אשה שהוא פסול,\u0004 שהרי הכל יודעים שהוא חשוד לענין זה. \u0003אמר רבינא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 שהוא פסול לעדות אשה \u0003אלא\u0004 כשהעדות באה \u0003לאפוקה\u0004 \u0005[להוציאה\u0006 מבעלה\u0005],\u0006 שאז חושדים בו שמא רוצה הוא בה לעצמו, \u0003אבל\u0004 כשעדותו היא \u0003לעיולה\u0004 \u0005[להכניסה]\u0006 לבעלה, שעדותו מכשירה אותה לנישואין — \u0003לית לן בה\u0004 \u0005[אין לנו בו\u0006 חשש\u0005].\u0006","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 וכי מדוע ייחשד בענין זה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הא עדיפא ליה\u0004 \u0005[זו עדיפה לו]\u0006 כשהיא נשואה דווקא, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"מים גנובים ימתקו\u0004 ולחם סתרים ינעם\u0003\"\u0004 (משלי ט, יז), שנעים לו האיסור יותר מן ההיתר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דכמה דקיימא הכי שכיחא ליה\u0004 \u0005[שכמו שהיא\u0006 כך, שהיא פנויה, \u0005מצויה לו\u0006 יותר\u0005]\u0006 ועדיף לו שתישאר פנויה.","\u0003ואמר רב נחמן: גנב ניסן וגנב תשרי,\u0004 שגונב בתקופות אלה שהתבואה והפירות מצויים לרוב — \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו קרוי\u0005]\u0006 \u0003גנב\u0004 ואינו נפסל בכך.","ומסבירים: \u0003הני מילי באריסא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005באריס]\u0006 ולא בכל אדם, \u0003ו\u0004שגנב רק \u0003דבר מועט,\u0004 ושגנב \u0003דבר שנגמרה מלאכתו,\u0004 שבמקרה כגון זה עשוי שיגנוב אדם בלי לחשוב שהוא עובר עבירה.","מסופר: \u0003איכריה\u0004 \u0005[איכריו,\u0006 אריסיו\u0005]\u0006 של \u0003רב זביד חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003גנב קבא דשערי, ופסליה\u0004 \u0005[קב שעורים, ופסלו],\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003גנב קיבורא דאהיני ופסליה\u0004 \u0005[אשכול תמרים, ופסלו],\u0006 שדברים אלה כבר אינם נקראים דבר מועט.","מסופר: \u0003הנהו קבוראי דקבור נפשא\u0004 \u0005[אותם קברנים שקברו אדם]\u0006 \u0003ביום טוב ראשון של עצרת\u0004 (שבועות), וחיללו בכך את החג, \u0003שמתינהו\u0004 \u0005[החרימם]\u0006 \u0003רב פפא ופסלינהו\u0004 \u0005[ופסלם]\u0006 \u0003לעדות, ואכשרינהו\u0004 \u0005[והכשירם]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא: והא\u0004 \u0005[והרי]\u0006 \u0003רשעים נינהו\u0004 \u0005[הם]\u0006 שעברו על דברי תורה! ענה לו: הרי הם לא חשבו כן, אלא \u0003סברי\u0004 \u0005[סבורים היו]\u0006 כי \u0003מצוה קא עבדי\u0004 \u0005[הם עושים]\u0006 שהרי קוברים הם את המת.","ושואלים: כיצד יכול לחשוב כן \u0003והא קא משמתינא להו\u0004 \u0005[והרי מחרימים אותם]\u0006 בשל כך והם יודעים זאת וחוטאים! ומשיבים: \u0003סברי\u0004 \u0005[סבורים\u0006 הם\u0005]:\u0006 \u0003כפרה קא עבדי לן רבנן\u0004 \u0005[עושים לנו חכמים],\u0006 שיכופר לנו עוון חילול החג, כיון שעשינו בזה מעשה מצוה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו,"],["\u0003עד זומם\u0004 שהעיד בדין ולאחר זמן באו עדים אחרים והוזם על ידם, ואז ברור שאותה עדות שהעיד עדות שקר היא, ובטלה, וממילא נתגלה שהוא רשע שהרי העיד עדות שקר והוא פסול לעדות, ואולם נחלקו ממתי הוא נפסל, ש\u0003אביי אמר: למפרע הוא נפסל,\u0004 שלא רק משעה שהוזם הוא פסול, אלא אף משעת עדותו הראשונה שהרי בה חטא ומאז הוא פסול, \u0003ורבא אמר: מיכן\u0004 (מכאן) \u0003ולהבא,\u0004 משעה שהוזם, \u0003הוא נפסל.\u0004","ומבארים את השיטות: \u0003אביי אמר\u0004 ש\u0003למפרע הוא נפסל,\u0004 טעמו — \u0003מעידנא דאסהיד\u0004 \u0005[מן הזמן שהעיד]\u0006 הלא \u0003רשע הוא, והתורה אמרה \"אל תשת ידך עם רשע\u0004 להיות עד חמס\u0003\"\u0004 (שמות כג, א), וכוונת הדברים: \u0003אל תשת רשע עד,\u0004 ואדם שהעיד שקר רשע הוא מאותה שעה, וכל עדויות שהעיד מאז פסולות.","ו\u0003רבא\u0004 ש\u0003אמר\u0004 ש\u0003מיכן ולהבא הוא נפסל,\u0004 טעמו — שכן כל עיקר הדין של \u0003עד זומם\u0004 \u0003חידוש הוא\u0004 שחידשה התורה בדין זה, שמקבלים עדותם של המזימים, כי \u0003מאי חזית דסמכת אהני\u0004 \u0005[מה ראית שסמכת על אלה],\u0006 על העדים השניים המזימים? \u0003סמוך אהני\u0004 \u0005[על אלה\u0006 הראשונים\u0005]!\u0006 ולכן אין לומר שעל פי דברי המזימים הוכח בוודאות כי העדים הראשונים חטאו ושיקרו, אלא זו גזירת הכתוב שמקבלים את עדות המזימים, וכיון שחידוש הוא, \u0003אין לך בו אלא משעת חידושו ואילך,\u0004 שרק משעה שנפסל על ידי המזימים הוא פסול.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שמעיקר הדין \u0003רבא נמי\u0004 \u0005[גם כן]\u0006 \u0003כאביי סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003ומאי טעם קאמר\u0004 \u0005[ומה טעם אמר]\u0006 \u0003מכאן ולהבא\u0004 הוא נפסל? — \u0003משום פסידא\u0004 \u0005[ההפסד]\u0006 של ה\u0003לקוחות\u0004 שחתם אותו עד על שטרותיהם במשך הזמן, שהרי נתברר שעדות זו פסולה וכל השטרות בטלים.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל\u0006 למעשה \u0005ביניהם\u0006\u0005]\u0006 בין שני ההסברים הללו של רבא, אם מטעם זה אם מטעם זה הוא פוסק? ומשיבים: \u0003איכא בינייהו דאסהידו בי תרי בחד\u0004 \u0005[יש ביניהם\u0006 הבדל כגון \u0005שהעידו שנים ב\u0006עד \u0005אחד]\u0006 והזימוהו. שכאן אין חידוש שהרי הם שנים המעידים באחד, אבל השיקול של הפסד הלקוחות קיים גם כאן. \u0003אי נמי דפסלינהו בגזלנותא\u0004 \u0005[או גם כן\u0006 כגון \u0005שפסלו אותם,\u0006 את העדים \u0005בגזלנות],\u0006 שהעידו עליהם שהם רשעים משום שחטאו בגזל, שהפסד לקוחות יש כאן, אבל חידוש אין כאן.","\u0003ואמר ר' ירמיה מדיפתי: עבד\u0004 \u0005[עשה]\u0006 \u0003רב פפי עובדא כוותיה\u0004 \u0005[מעשה כשיטתו]\u0006 של \u0003רבא\u0004 ולא פסלו אלא מן הזמן שהעידו עליו. \u0003מר בר רב אשי אמר: הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003אביי\u0004 שלמפרע הוא נפסל.","ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003אביי ביע\"ל קג\"ם,\u0004 שהן שש הלכות, שזה סימנן, שבהן הלכה כאביי נגד רבא. בעוד שבכל שאר מחלוקותיהם שבתלמוד פוסקים כרבא נגד אביי.","ועוד מחלוקת של אביי ורבא הקשורה אף היא בפסולי עדות. \u0003מומר אוכל נבילות לתיאבון,\u0004 כלומר, משום שהוא מתאוה לבשר זה או משום שהוא זול או שקל להשיגו — \u0003דברי הכל פסול\u0004 לעדות, שהרי רואים שמפני תאבונו ותאוותו עובר הוא על דברי תורה, והוא חשוד גם לעבור ולהעיד שקר אם תהא לו טובת הנאה בדבר.","אך השאלה היא ביחס לזה שאוכל נבלות \u0003להכעיס,\u0004 מתוך כפירה, \u0003אביי אמר: פסול\u0004 לעדות, ואילו \u0003רבא אמר: כשר.\u0004 ומסבירים את השיטות.","\u0003אביי אמר: פסול\u0004 — \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003רשע,\u0004 \u0003ורחמנא אמר\u0004 \u0005[והתורה אמרה]\u0006 \u0003\"אל תשת רשע עד\", ו\u0004אילו \u0003רבא אמר: כשר\u0004 — משום שלענין פסול עדות דווקא \u0003רשע\u0004 של \u0003חמס\u0004 \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 שמדברי הכתוב למדים שהעד לא יהיה רשע אלא בדבר שיש בו חמס (כגון גזילה וגניבה וכיוצא באלה).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: את הכתוב \"אל תשת ידך עם רשע להיות עד חמס\" (שמות כג, א) מפרשים: \u0003\"אל תשת רשע עד\"\u0004 או \u0003\"אל תשת חמס עד\".\u0004 והכוונה, \u0003אלו גזלנין ומועלין בשבועות\u0004 הפסולים לעדות. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נבין כי \"מועלין בשבועות\" כולל \u0003אחד\u0004 הנשבעים \u0003שבועת שוא,\u0004 שנשבעים שבועות שונות לגבי עצמם ואינם מקיימים, ואין בכך צד ממון כלל, \u0003ואחד\u0004 הנשבעים \u0003שבועת ממון?\u0004 משמע שאף מומר להכעיס פסול!","ודוחים: \u0003לא, אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר במועלים ב\u0003שבועת ממון, ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"שבועות\"\u0004 בלשון רבים? — \u0003שבועות דעלמא\u0004 \u0005[בכלל]\u0006 ולא נרמז בכך ריבוי מיני שבועות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד ממה ששנינו בברייתא: \u0003\"אל תשת רשע עד\", \"אל תשת חמס עד\"\u0004 — \u0003אלו גזלנין ומלוי רביות.\u0004 ולא מנה כאן עבריינים אחרים אלא רק בעלי חטא שיש בו חמס, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003אביי,\u0004 ואומרים אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005].\u0006","ומציעים: \u0003נימא כתנאי\u0004 \u0005[האם נאמר\u0006 שמחלוקת \u0005תנאים\u0006 בדבר\u0005],\u0006 ששנינו: \u0003עד זומם פסול\u0004 להעיד \u0003לכל התורה כולה,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר: במה דברים אמורים?\u0004 — \u0003שהוזם בדיני נפשות\u0004 שאז נפסל הוא לכל עדות שבעולם, שאם שיקר בדבר הנוגע בנפשות ודאי הוא מזלזל בדברים אחרים. \u0003אבל\u0004 אם \u0003הוזם בדיני ממונות\u0004 — \u0003כשר לדיני נפשות,\u0004 שאין לנו הוכחה שהוא מזלזל עד כדי כך.","\u0003נימא\u0004 \u0005[האם נאמר]\u0006 כי \u0003אביי\u0004 סובר \u0003כ\u0004שיטת \u0003ר' מאיר, ורבא\u0004 סבור \u0003כ\u0004שיטת \u0003ר' יוסי?\u0004 ומבארים: \u0003אביי\u0004 סבור \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר: אמרינן\u0004 \u0005[אומרים אנו]\u0006 שהוא שקרן אפילו \u0003מקולא לחומרא,\u0004 שכיון שהוכח שמעיד שקר — בכל מקרה משקר. \u0003ורבא\u0004 ש\u0003אמר כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: מחומרא לקולא\u0004 — \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 שהוא משקר, אבל \u0003מקולא לחומרא\u0004 — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006 את הצירוף הזה.","ודוחים: \u0003לא, אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יוסי כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שהחשוד לשקר בדבר קל אינו חשוד על החמור, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' מאיר.\u0004","\u0003אביי\u0004 סבור \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 כפי הנראה ממשמעות דבריו, \u0003ורבא\u0004 אומר: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם]\u0006 \u0003אלא גבי עד זומם\u0004 בענין של \u0003ממון,\u0004 שעד זומם המוציא בעדות שקר ממון מבעליו הוא גם \u0003רע לשמים\u0004 שהיא חוטא בעדות שקר לה' \u0003ו\u0004גם \u0003רע לבריות\u0004 שמפסיד ממון חבירו, ולכן אפשר לומר שעד כזה חשוד כבר לכל. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 במומר להכעיס שהוא \u0003רע לשמים\u0004 ואין הוכחה שהוא \u0003רע לבריות\u0004 — \u0003לא,\u0004 אין לפסלו.","ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003אביי.\u0004 ומקשים: \u0003והא איתותב\u0004 \u0005[והרי כבר הושבו,\u0006 נדחו דבריו\u0005]\u0006 על ידי הקושיה שהקשינו! ומשיבים: המשנה \u0003ההיא\u0004 שממנה הקשינו עליו כשיטת \u0003ר' יוסי היא,\u0004 והוא אינו סבור כמוהו.","ומקשים עוד: \u0003ותיהוי נמי\u0004 \u0005[ותהא גם כן],\u0006 נניח שתהא אותה משנה כ\u0003ר' יוסי,\u0004 ואולם גם אז הלא לפי כללי הפסיקה במחלוקת בכל ענין שנחלקו בו \u0003ר' מאיר ור' יוסי\u0004 — \u0003הלכה כר' יוסי!\u0004","ומסבירים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003סתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא כ\u0004דעת \u0003ר' מאיר\u0004 שיש סתם משנה בלא ציון שם אומר שיטה זו, והלכה כסתם משנה בכל מקום. ושואלים: \u0003והיכא\u0004 \u0005[והיכן]\u0006 \u0003סתם לן\u0004 \u0005[לנו]?\u0006 מה היא משנה זו?","ומספרים כי דבר זה נתברר ממעשה שהיה, \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ששמו \u0003בר חמא קטל נפשא\u0004 \u0005[\u0006ש\u0005הרג נפש\u0006 אדם\u0005],\u0006 \u0003אמר ליה ריש גלותא\u0004 \u0005[לו ראש הגולה]\u0006 \u0003לרב אבא בר יעקב: פוק\u0004 \u0005[צא]\u0006 ו\u0003עיין בה\u0004 בשאלה זו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ודאי קטל\u0004 \u0005[הרג]\u0006 — \u0003ליכהיוהו לעיניה\u0004 \u0005[שינקרו את עיניו].\u0006 \u0003אתו תרי סהדי אסהידו ביה\u0004 \u0005[באו שני עדים\u0006 ו\u0005העידו בו]\u0006 ש\u0003ודאי קטל\u0004 \u0005[הרג].\u0006 \u0003אזל איהו אייתי תרי סהדי\u0004 \u0005[הלך הוא,\u0006 הנאשם, ו\u0005הביא שני עדים\u0006 אחרים\u0005],\u0006 \u0003אסהידו ביה בחד מהנך\u0004 \u0005[העידו בו באחד מאותם\u0006 עדים\u0005],\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: קמאי דידי\u0004 \u0005[לפני],\u0006 כלומר, אני ראיתי ש\u0003גנב קבא דחושלא\u0004 \u0005[קב שעורים],\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: קמאי דידי\u0004 \u0005[לפני]\u0006 \u0003גנב\u0004"],["\u0003קתא דבורטיא\u0004 \u0005[קת של רומח].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אבא בר יעקב לבר חמא: \u0003מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 בהבאת עדים אלה, שאתה סבור \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 שמי שהוכח שהוא רשע בדיני ממונות פסול הוא גם בדיני נפשות, ואולם הלא כשנחלקו \u0003ר' מאיר ור' יוסי\u0004 — \u0003הלכה כר' יוסי, ור' יוסי האמר\u0004 \u0005[הרי אמר]\u0006 שאם \u0003הוזם\u0004 העד ונמצא ששיקר \u0003בדיני ממונות\u0004 — \u0003כשר לדיני נפשות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 באותו מעמד \u0003רב פפי: הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005היכן]\u0006 ש\u0003לא סתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא\u0004 ולא שנה \u0003כ\u0004שיטת \u0003ר' מאיר, הכא\u0004 \u0005[כאן]\u0006 \u0003סתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא\u0004 \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 ולכן הלכה כמותו.","ושואלים: \u0003ממאי\u0004 \u0005[ממה],\u0006 מהו המקור לקביעה זו? \u0003אילימא מהא דתנן\u0004 \u0005[אם תאמר מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הראוי לדון דיני נפשות\u0004 — \u0003ראוי לדון דיני ממונות.\u0004 ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 משנה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכשיטת \u0003ר' יוסי היא, הא איכא\u0004 \u0005[הרי יש]\u0006 דבר שאינו מתיישב, זה ש\u0003עד זומם\u0004 בענין \u0003ממון כשר לדיני נפשות\u0004 לדעת ר' יוסי, \u0003ופסול לדיני ממונות! אלא לאו\u0004 \u0005[האם לא]\u0006 כשיטת \u0003ר' מאיר היא,\u0004 הרי סתם משנה כר' מאיר.","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוכיח אתה דבר זה? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003בפסולי יוחסין קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 דן\u0005]\u0006 ולא בפסולים מחמת רשע אלא פסולים מחמת פגם ביחוסם.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כן]\u0006 שבכך מדובר, אם כן \u0003סיפא דקתני\u0004 \u0005[סופה\u0006 של אותה משנה \u0005ששנינו\u0006 בה\u0005]\u0006 ש\u0003יש ראוי לדון דיני ממונות ואין ראוי לדון דיני נפשות, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו ראוי?\u0004 אם תאמר שמדובר באדם \u0003דאיתזם\u0004 \u0005[שהוזם]\u0006 \u0003בדיני נפשות,\u0004 ואולם כיצד תאמר שהוא \u0003ראוי לדון דיני ממונות?! והא\u0004 \u0005[והרי]\u0006 \u0003דברי הכל פסול הוא. אלא\u0004 ודאי \u0003בפסול יוחסין קאי\u0004 \u0005[עומד,\u0006 דן\u0005],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בהתחלה \u0003בפסול יוחסין קאי\u0004 \u0005[עומד\u0006 ודן\u0005]\u0006 ולא בפסול אחר.","\u0003אלא\u0004 עלינו למצוא מקור אחר: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003קא סתם לן\u0004 \u0005[הריהו סותם לנו]\u0006 ה\u0003תנא\u0004 כשיטת ר' מאיר. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אלו הן הפסולים\u0004 — \u0003המשחק בקוביא, ומלוי ברבית, ומפריחי יונים, וסוחרי שביעית\u0004 שעוברים עבירות בדיני ממונות, \u0003והעבדים\u0004 הכנענים. \u0003זה הכלל: כל עדות שאין האשה כשירה לה,\u0004 שרשאית להעיד רק על מותו של אדם וכיוצא בזה, \u0003אף הן אין כשרים לה\u0004 שאין מקבלים עדותם בתורת עדים כלל.","ונברר \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 משנה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כשיטת \u0003ר' יוסי\u0004 — \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 דין \u0003עדות בדיני נפשות, שאין האשה כשרה לה והן\u0004 המורשעים משום עבירות שבממון \u0003כשרין לה. אלא לאו\u0004 \u0005[האם לא]\u0006 כשיטת \u0003ר' מאיר היא,\u0004 משמע שסתם משנה כר' מאיר והלכה כמותו.","בהתאם למסקנה זו נמצא שאחד העדים שהעידו על בר חמא שהרג נפש פסול לעדות, ויצא בר חמא זכאי מבית הדין, \u0003קם\u0004 \u0005[עמד]\u0006 \u0003בר חמא\u0004 הנאשם \u0003נשקיה אכרעיה\u0004 \u0005[נשק\u0006 את רב פפי \u0005על רגליו],\u0006 \u0003וקבליה לכרגיה דכולי שניה\u0004 \u0005[וקיבל\u0006 על עצמו לשלם עבורו \u0005את המס בכל שנותיו].\u0006","\u0003ואלו הן הקרובין\u0004 הפסולים לעדות ולדון: \u0003אחיו, ואחי אביו, ואחי אמו, ובעל אחותו, ובעל אחות אביו, ובעל אחות אמו, ובעל אמו, וחמיו, וגיסו\u0004 (בעל אחות אשתו). \u0003הן\u0004 עצמם ואף \u0003בניהן וחתניהן\u0004 נחשבים כקרובים. \u0003ו\u0004כן \u0003חורגו\u0004 (בנו החורג, בן אשתו) \u0003לבדו,\u0004 אבל לא בנו וחתניו.","\u0003אמר ר' יוסי\u0004 הלכה \u0003זו\u0004 ששנינו היא \u0003משנת ר' עקיבא, אבל משנה ראשונה\u0004 וקדומה לא כך שנתה, אלא: \u0003דודו, ובן דודו, וכל הראוי ליורשו.\u0004 שבמשנה ראשונה נפסלו רק קרובי האב שהם הראוים לרשת אותו, למעט את קרוביו מצד אמו שאינם יורשים אותו ואף אינם פסולים להעידו ולדונו. ועוד אמרו שהקרוב שאמרו שהוא פסול להעידו ולדונו הוא דווקא \u0003כל הקרוב לו באותה שעה\u0004 שבה דנים.","ואולם אם \u0003היה\u0004 פעם \u0003קרוב\u0004 משפחה \u0003ונתרחק,\u0004 וכגון שנשא אותו אדם את אחותו ומתה או שנתגרשה — \u0003הרי זה כשר. ר' יהודה אומר: אפילו מתה בתו ויש לו בנים ממנה, הרי זה\u0004 נחשב \u0003קרוב\u0004 עדיין משום הבנים שעל ידם יש קשר קירבה.","ועוד פסולים להעיד: \u0003האוהב והשונא. אוהב\u0004 — \u0003זה שושבינו\u0004 שהוא הידיד הקרוב הדואג לכל צרכי חתונתו. \u0003שונא\u0004 הוא \u0003כל\u0004 אדם \u0003שלא דבר עמו שלשה ימים\u0004 מתוך \u0003איבה. אמרו לו: לא נחשדו ישראל על כך\u0004 להעיד עדות שקר מפני אהבה ושנאה.","שואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלו]\u0006 שקרובים פסולים לעדות? ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר: \u0003\"לא יומתו אבות על בנים\u0004 ובנים לא יומתו על אבות איש בחטאו יומתו\u0003\"\u0004 (דברים כד, טז) \u0003מה תלמוד לומר\u0004 \"לא יומתו אבות על בנים\"? \u0003אם ללמד שלא יומתו אבות בעו‍ן בנים\u0004 שחטאו \u0003ובנים\u0004 לא יומתו \u0003בעו‍ן אבות\u0004 — \u0003הרי כבר נאמר \"איש בחטאו יומתו\"\u0004 (דברים כד, טז), ואין צורך בפירוט יתר.","\u0003אלא\u0004 יש להבין שהכוונה היא \u0003\"לא יומתו אבות על בנים\"\u0004 — \u0003בעדות בנים, \"ובנים לא יומתו על אבות\"\u0004 — \u0003בעדות אבות.\u0004","כיון שהוזכר מקרא זה שואלים לגופו: \u0003ו\u0004האם \u0003בנים בעו‍ן אבות לא\u0004 מתים? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"פקד עו‍ן אבות על בנים\u0004 ועל בני בנים על שלשים ועל רבעים","\u0003\"\u0004(שמות לד, ז)! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003כשאוחזין\u0004 הבנים \u0003מעשה אבותיהן בידיהן,\u0004 אבל אם אין הם נוהגים כאבותיהם — אין פוקדים עליהם עוונות אבותיהם.","\u0003כדתניא\u0004 \u0005[כפי\u0006 \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"ואף בעו‍נת אבתם אתם ימקו\"\u0004 (ויקרא כו, לט) כוונת הדברים: \u0003כשאוחזין מעשה אבותיהם בידיהם. אתה אומר\u0004 שמדובר כאן \u0003כשאוחזין\u0004 עוונות אבות, \u0003או אינו אלא\u0004 גם \u0003כשאין אוחזין?\u0004 — \u0003כשהוא אומר \"איש בחטאו יומתו\"\u0004 הרי זו הוכחה שאין אדם מת שלא בעוונו, ו\u0003הרי\u0004 אם כן שודאי שיש לפרש שהכוונה היא \u0003כשאוחזין מעשה אבותיהן בידיהן.\u0004","ועוד מקשים: \u0003ולא?\u0004 וכי אין מענישים בנים בעוון אבותם? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וכשלו איש באחיו\"\u0004 (ויקרא כו, לז), ונתפרש: \u0003איש בעו‍ן אחיו, מלמד\u0004 כתוב זה \u0003שכולן ערבים זה בזה,\u0004 הרי שאף אלה שאינם קרובים נענשים זה בעוון זה!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר באנשים הנענשים לא משום קירבת המשפחה אלא \u0003שהיה בידם\u0004 כח \u0003למחות\u0004 על עבירות שנעשו \u0003ולא מיחו,\u0004 ועל כן הם נענשים — על שלא מיחו בקרובים והניחו להם לחטוא."],["מלשון הכתוב \"לא יומתו אבות על בנים\" (דברים כד, טז) מובן שאבות אינם יכולים להעיד על בנים, לא בניהם שלהם ולא בניהם של הקרובים (שאילו היתה הכוונה רק לאב המעיד על בנו היה צריך לומר בלשון יחיד: \"לא יומת אב על בנו\", ולשון הריבוי \"אבות\" ו\"בנים\", משמעה איפוא — אבות הקרובים זה לזה אינם מעידים על הבנים של קרוביהם). \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא הוכחה בענין איסור עדות של \u0003אבות לבנים ובנים לאבות,\u0004","\u0003וכל שכן אבות להדדי\u0004 \u0005[זה לזה],\u0006 כגון שני אחים שוודאי אינם יכולים להעיד זה על זה שהרי הם קרובים זה לזה יותר מאשר לבניהם.","ואולם \u0003בנים לבנים\u0004 שלא יוכלו בני קרובים להעיד זה על זה \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006","ומסבירים: \u0003אם כן\u0004 שיהיו בנים רשאים להעיד על בנים \u0003ליכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"לא יומתו אבות על בן\", מאי\u0004 \u0005[מה]\u0006 לשון הריבוי \u0003\"בנים\"?\u0004 — ש\u0003אפילו בנים להדדי\u0004 \u0005[זה לזה]\u0006 לא יעידו.","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ש\u0003בנים\u0004 אינם יכולים להעיד \u0003להדדי\u0004 \u0005[זה על זה],\u0006 ואולם \u0003בנים\u0004 קרובים שאינם יכולים להצטרף לעדות אחת להעיד \u0003לעלמא מנלן\u0004 \u0005[לעולם,\u0006 לאחרים, \u0005מנין לנו]?\u0006","\u0003אמר רמי בר חמא: סברא הוא\u0004 אף שאין להוכיחה מן המקראות. ומקור הסברה — \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בתוספתא\u0005]:\u0006 \u0003אין העדים נעשין זוממין עד שיזומו שניהן\u0004 יחד. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003בנים לעלמא\u0004 \u0005[לאחרים]\u0006 \u0003כשרין\u0004 להעיד, \u0003נמצא\u0004 ש\u0003עד זומם נהרג בעדות אחיו,\u0004 שהרי אינו נהרג אלא אם כן הוזם גם השני, ונמצא שאותה עדות שהעיד גם אחיו היא שגרמה לו למות, והרי דבר זה הוא כבנים שהעידו זה על זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשה אחין ו\u0004עוד \u0003אחד\u0004 שאינו קרוב \u0003מצטרף עמהן,\u0004 כגון שכל אחד מן האחים והעד הנוסף מעידים על חזקה, אם על כל שנה משלוש השנים מעיד אח אחר ומצטרף עם העד הנוסף \u0003הרי אלו שלש עדיות\u0004 ואין אומרים שיש כאן פסול משום עדות קרובים, \u0003והן\u0004 נחשבים \u0003עדות אחת ל\u0004ענין \u0003הזמה,\u0004 שאין זו הזמה עד שיזומו כולם.","\u0003נמצא\u0004 אם כן ש\u0003עד זומם משלם ממון בעדות אחיו,\u0004 ואין אנו סבורים שיש בכך משום פגם.","\u0003אלא\u0004 ודאי עלינו להסביר כי \u0003הזמה מעלמא קאתי\u0004 \u0005[מן העולם,\u0006 מבחוץ, \u0005היא באה],\u0006 שעיקר ההזמה באה מכח עדותם של העדים המזימים ולא מן העדות עצמה ולכן איננו אומרים שאח אחד גורם לאחר לשלם, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003הזמה מעלמא קאתי\u0004 \u0005[מן העולם,\u0006 מן החוץ, \u0005היא באה]\u0006 ואין רואים את האחים כמעידים זה על זה.","\u0003אלא\u0004 עלינו לדחות ראיה זו ולומר טעם אחר, \u0003אם כן ליכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"ובן על אבות\", אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003\"הם על אבות\" מאי\u0004 \u0005[מה]\u0006 משמע \u0003\"ובנים\"\u0004 שהוא יתור לשון, הרי זה בא ללמד \u0003אפילו בנים לעלמא\u0004 \u0005[לעולם,\u0006 לאחרים\u0005].\u0006","ועוד מבררים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 מקור לאסור את \u0003קרובי האב,\u0004 ואולם \u0003קרובי האם מנלן\u0004 \u0005[מנין לנו]\u0006 שאף הם פסולים להעיד? \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אבות\" \"אבות\" תרי זימני\u0004 \u0005[שתי פעמים]\u0006 כשאין צורך בחזרה ויכול היה לומר \"עליהם\", ו\u0003אם אינו ענין\u0004 ללמד \u0003לקרובי האב\u0004 שכבר למדנו דינם, \u0003תניהו ענין לקרובי האם.\u0004","ועוד שואלים: מן הכתוב הזה \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 שאין קרוב יכול להעיד על קרוביו \u0003לחובה,\u0004 שהרי נאמר \"יומתו\", ואולם כאשר הם מעידים \u0003לזכות מנא לן\u0004 \u0005[מנין לנו]\u0006 שאין עדותם מתקבלת?","ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"יומתו\" \"יומתו\" תרי זימני\u0004 \u0005[שתי פעמים],\u0006 \u0003אם אינו ענין לחובה\u0004 שכבר למדנו — \u0003תנהו ענין לזכות.\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 מקור למשנתנו \u0003בדיני נפשות\u0004 שהרי בלשון מיתה נאמרה, \u0003בדיני ממונות מנלן\u0004 \u0005[מנין לנו]\u0006 שהקרובים פסולים להעיד?","ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"משפט אחד יהיה לכם\"\u0004 (ויקרא כד, כב) ומכאן למדים: \u0003משפט השוה לכם,\u0004 שמעיקר הדין גם דיני ממונות וגם דיני נפשות נדונים על פי אותם דינים.","מעתה מבררים דיני קירבה וענייניה. \u0003אמר רב: אחי אבא לא יעיד לי, הוא ובנו וחתנו\u0004 כאמור במשנה. \u0003אף אני לא אעיד לו, אני ובני וחתני.\u0004","ותוהים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 לא יוכל למשל הבן להעיד לאחי אבי אביו? \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 קרוב אליו בדרגת \u0003שלישי בראשון,\u0004 שהרי הבן שלישי הוא לסב שמכחו באה הקירבה, \u0003ואנן\u0004 \u0005[ואנחנו]\u0006 קירבת \u0003שני בשני תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003שני בראשון תנן\u0004 \u0005[שנינו],\u0006 אבל \u0003שלישי בראשון לא תנן\u0004 \u0005[שנינו]!\u0006","ומשיבים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"חתנו\" דקתני במתניתין\u0004 \u0005[ששנינו במשנתנו]?\u0006 — הכוונה היא: \u0003חתן בנו,\u0004 שיש להבין כך את האמור במשנה: הן (הקרובים) ובניהם (של קרובים) וחתניהם (של הבנים) והרי זה שלישי בראשון.","ומקשים: אם כן \u0003וליתני\u0004 \u0005[וישנה]\u0006 \u0003\"בן בנו\"\u0004 ללמדנו דין שלישי בראשון שהוא פשוט יותר!","ומשיבים: \u0003מילתא אגב אורחיה קא משמע לן\u0004 \u0005[דבר בדרך אגב השמיע לנו]\u0006 בדרך ביטוי זו שה\u0003בעל כאשתו\u0004 ואין אנו רואים בכך התרחקות דרגה נוספת בקירבה.","ומקשים: \u0003ואלא הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003ר' חייא: שמונה אבות,\u0004 כלומר, קרובים עיקריים ששנינו במשנה (אחיו ואחי אביו וכו') \u0003שהן עשרים וארבעה\u0004 אם מצרפים לכל אחד את בנו וחתנו. ואולם אם נחשוב גם את בן בנו \u0003הני תלתין ותרתין הוי\u0004 \u0005[אלה שלושים ושנים הם]\u0006 שנמצאו מצרפים לכל אב עוד שלושה נוספים!","\u0003אלא\u0004 נדחה הסבר זה, ו\u0003לעולם\u0004 נפרש ש\"חתנו\" שבמשנה הכוונה היא \u0003חתנו\u0004 שלו \u0003ממש, ואמאי קרי ליה\u0004 \u0005[ומדוע קרא לו]\u0006 רב \u0003\"חתן בנו\"\u0004 ולמד ממנו לענין שלישי בראשון? — \u0003כיון דמעלמא קאתי\u0004 \u0005[שמן העולם,\u0006 החוץ, \u0005הוא בא]\u0006 ואיננו קרוב בעצמו אלא מכח קרבת אשתו, הרי \u0003כדור אחר דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 והרי זה רחוק בדרגה אחת של קירבה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מתברר לפי זה שהקשר בין חתן אחי אביו ובינו \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003שלישי בשני, ו\u0004יודעים אנו כי \u0003רב אכשר\u0004 \u0005[הכשיר]\u0006 לעדות \u0003שלישי בשני!\u0004","אלא יש לומר שאין הדבר כדעת משנתנו \u0003אלא רב\u0004 ש\u0003אמר\u0004 דבריו — \u0003כ\u0004שיטת \u0003ר' אלעזר\u0004 אמר. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' אלעזר אומר: כשם שאחי אבא לא יעיד לי, הוא ובנו וחתנו, כך בן אחי אבא לא יעיד לי, הוא ובנו וחתנו,\u0004 הרי שר' אלעזר פוסל אף בקירבה של בני בנים.","ומקשים: \u0003ואכתי הוה ליה\u0004 \u0005[ועדיין הרי הוא]\u0006 \u0003שלישי בשני, ורב אכשר\u0004 \u0005[הכשיר]\u0006 \u0003שלישי בשני!\u0004","ומשיבים: \u0003רב סבר ליה כוותיה בחדא\u0004 \u0005[סבור כשיטתו ב\u0006דבר \u0005אחד]\u0006 שזו קרויה קירבה, \u0003ופליג עליה בחדא\u0004 \u0005[וחלק עליו ב\u0006דבר \u0005אחד]\u0006 בענין הכשר כללי של שלישי בשני.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב?\u0004 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא יומתו אבות על בנים ובנים\",\u0004 ומכאן הוא למד \u0003לרבות דור אחר\u0004 של בני בנים (\"בנים ובנים\") שאף הוא נכנס בגדר קירבה.","\u0003ור' אלעזר\u0004 דעתו היא ש\u0003\"על בנים\"\u0004 ש\u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 הרי זה בא ללמד ש\u0003פסולי\u0004 \u0005[הפסולים]\u0006 שיש כלפי ה\u0003אבות,\u0004 \u0003שדי\u0004 \u0005[השלך]\u0006 גם כלפי ה\u0003בנים,\u0004 שכל הפסול להעיד לאב פסול גם להעיד לבנו.","\u0003אמר רב נחמן: אחי חמותי לא יעיד לי,\u0004 אף \u0003בן אחי חמותי לא יעיד לי, בן אחות חמותי לא יעיד לי. ו\u0004כן \u0003תנא תונא\u0004 \u0005[\u0006שנה \u0005התנא שלנו]\u0006 במשנתנו בלשון אחרת, שאמר: \u0003בעל אחותו, ובעל אחות אביו, ובעל אחות אמו, הן ובניהן וחתניהן\u0004 שהיא אותה קירבה כאשר מונים אותה מצד אחר.","\u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו למדים בבית\u0006 מדרשו\u0005]\u0006 של \u0003עולא איבעי לן\u0004 \u0005[נשאלה לנו]\u0006 שאלה זו: \u0003אחי חמיו מהו\u0004 להעיד עליו? \u0003בן אחי חמיו מהו? בן אחות חמיו מהו?\u0004","\u0003אמר לן\u0004 \u0005[לנו],\u0006 כבר \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 את התשובה לשאלתכם זו במשנתנו: \u0003אחיו, ואחי אביו, ואחי אמו, הן ובניהן וחתניהן\u0004 והיא היא קירבה זו.","מסופר: \u0003רב איקלע למזבן\u0004 \u0005[הזדמן ל\u0006מקום \u0005לקנות]\u0006"],["\u0003גוילי\u0004 \u0005[גוילים]\u0006 של עורות. \u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 שאלה זו: \u0003מהו שיעיד אדם באשת חורגו\u0004 (בנו החורג)?","\u0003בסורא אמרי\u0004 \u0005[אמרו]\u0006 שפתר בדרך זו: \u0003בעל כאשתו,\u0004 וכיון שהוא בעל אמו של אותו בן הרי הוא כאביו, ואשת חורגו היא איפוא ככלתו.","\u0003בפומבדיתא אמרי\u0004 \u0005[אמרו]\u0006 בלשון אחרת: \u0003אשה כבעלה,\u0004 ואשת בנו החורג דינה כבנו החורג עצמו. ש\u0003אמר רב הונא אמר רב, מניין שהאשה כבעלה? דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ערות אחי אביך לא תגלה אל אשתו לא תקרב דדתך הוא\"\u0004 (ויקרא יח, יד), \u0003והלא אשת דודו הוא\u0004 ואינה דודתו (אחות אביו)! \u0003מכלל\u0004 הדברים אתה למד כי \u0003אשה\u0004 נידונה \u0003כבעלה.\u0004","שנינו במשנה כי בין הפסולים נמצאים \u0003בעל אמו הוא ובנו וחתנו.\u0004 ותוהים: \u0003בנו\u0004 של בעל אמו \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003אחיו\u0004 והרי כבר נאמר שאחיו פסול!","\u0003אמר ר' ירמיה: לא נצרכה אלא לאחי האח\u0004 כלומר, מדובר בבן בעל אמו מאם אחרת, שאין ביניהם קשר קירבת בשר כלל ובכל זאת נחשב הוא כקרוב.","מסופר: \u0003רב חסדא אכשר\u0004 \u0005[הכשיר]\u0006 עדות \u0003באחי האח. אמרו ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא שמיע לך הא\u0004 \u0005[שמעת\u0006 הלכה \u0005זו]\u0006 שאמר \u0003ר' ירמיה\u0004 שאחי האח פסול? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא שמיע לי\u0004 \u0005[שמעתי זאת],\u0006 \u0003כלומר,\u0004 נתכוון לומר \u0003לא סבירא לי\u0004 \u0005[אין אני סבור כן],\u0006 שלאמיתו של דבר שמע את ההלכה, אלא שלא קיבל דרך פירוש זו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 חוזרת הקושיה ששאלנו מתחילה, הרי בן בעל אמו הנזכר שם \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003אחיו!\u0004 ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003אחיו\u0004 סתם שהוא \u0003מן האב, וקתני\u0004 \u0005[ושנה]\u0006 גם כן \u0003אחיו מן האם.\u0004","\u0003אמר רב חסדא: אבי חתן ואבי כלה\u0004 הקרובים זה לזה על ידי נישואי ילדיהם \u0003מעידין זה על זה, ולא דמו להדדי\u0004 \u0005[ואינם נחשבים זה לזה]\u0006 \u0003אלא כי אכלא לדנא\u0004 \u0005[כמגופה שעל גבי חבית]\u0006 שאינה חלק ממנה אלא סמוכה לה בלבד.","\u0003אמר רבה בר בר חנה: מעיד אדם לאשתו ארוסה\u0004 לפי שקודם הנישואין אינו נחשב עדיין לקרוב לה. \u0003אמר רבינא: לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא\u0004 כשמעיד \u0003לאפוקי מינה\u0004 \u0005[להוציא ממנה\u0006 ממון\u0005],\u0006 שאז מקבלים עדותו משום שאינו קרוב. \u0003אבל\u0004 בעדות שיש בה \u0003לעיולי\u0004 \u0005[להכניס]\u0006 \u0003לה\u0004 ממון — \u0003לא מהימן\u0004 \u0005[אינו נאמן],\u0006 שהרי סופו לשאתה והוא יהנה מן הממון, ונמצא שהוא נוגע בדבר.","את השיטה הזו דוחים: \u0003ולא היא, לא שנא לאפוקי ולא שנא לעיולי\u0004 \u0005[אינו שונה להוציא ואינו שונה להכניס]\u0006 — \u0003לא מהימן\u0004 \u0005[אינו נאמן],\u0006 כי","\u0003מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה סבור להתיר עדות בארוס? — משום מה ש\u0003אמר ר' חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: אשתו ארוסה\u0004 (שעדיין לא נשאה) \u0003לא אונן\u0004 (מתאבל עליה) כשמתה \u0003ולא מטמא לה\u0004 לטפל בקבורתה אם הוא כהן, \u0003וכן היא לא אוננת ולא מטמאה לו.\u0004 אם \u0003מתה\u0004 — \u0003אינו יורשה,\u0004 אם \u0003מת הוא\u0004 — הרי היא \u0003גובה כתובתה\u0004 אם כתב לה מן האירוסין, שהוא כשאר שטר התחייבות שנותן, ואין ביניהם קשר אחר.","ואולם מכאן אין ראיה, שכן \u0003התם\u0004 \u0005[שם],\u0006 לענין טומאה וכדומה, בשאלה אם היא \u0003\"שארו\" תלה רחמנא\u0004 \u0005[תלתה התורה]\u0006 את הדין, ו\u0003אכתי לאו\u0004 \u0005[ועדיין אינה]\u0006 \u0003שארו היא,\u0004 שכל עוד לא נישאו אינה קרויה \"שאר בשרו\". אבל \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי עדות \u0003משום איקרובי דעתא\u0004 \u0005[קירוב הדעת]\u0006 \u0003הוא\u0004 שנפסל, \u0003והא איקרבא דעתיה לגבה\u0004 \u0005[והרי התקרבה דעתו אליה]\u0006 משום שהם מאורסים.","שנינו במשנה שבנו \u0003חורגו\u0004 הוא \u0003לבדו\u0004 שפסול להעיד לו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003חורגו לבדו. ר' יוסי אומר: גיסו. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003גיסו לבדו\u0004 ולא קרוביו, \u0003ר' יהודה אומר: חורגו.\u0004","ומבררים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 בברייתות אלה וכיצד יש להבין את המחלוקת? \u0003אילימא הכי קאמר\u0004 \u0005[אם תאמר\u0006 ש\u0005כך אמר]:\u0006 \u0003חורגו לבדו, והוא הדין לגיסו\u0004 שהוא לבדו פסול ולא בנו וחתנו. ובברייתא האחרת \u0003אתא\u0004 \u0005[בא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]\u0006 כי \u0003גיסו לבדו, והוא הדין לחורגו.\u0004 \u0003אלא\u0004 אם כן \u0003מתניתין דקתני\u0004 \u0005[משנתנו ששנינו]\u0006 \u0003גיסו הוא ובנו וחתנו, מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 כשיטת \u0003ר' יהודה ולא\u0004 כשיטת \u0003ר' יוסי,\u0004 שהרי כפי שהסברנו שניהם מסכימים שגם החורג וגם הגיס רק הם לבדם פסולים!","\u0003ואלא\u0004 יש לדחות ולפרש כי \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006 במשנה\u0005]:\u0006 \u0003חורגו לבדו, אבל גיסו\u0004 — \u0003הוא ובנו וחתנו\u0004 אסורים. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]\u0006 כי אין הדבר כן אלא רק \u0003גיסו לבדו, אבל חורגו\u0004 — \u0003הוא ובנו וחתנו\u0004 אסורים.","ולשיטה זו משנתנו היא כדעת ר' יהודה. ושואלים: \u0003ואלא הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003ר' חייא\u0004 שלהלכה יש לגבי קירבה \u0003שמונה אבות\u0004 מיני קירבה, \u0003שהן עשרים וארבעה\u0004 (בכל אחד גם בנו וחתנו), \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003לא כ\u0004שיטת \u0003ר' יוסי ולא כ\u0004שיטת \u0003ר' יהודה.\u0004","\u0003אלא\u0004 עלינו לדחות מה שאמרנו ולומר כי \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין ברייתות אלה: \u0003חורגו לבדו, אבל גיסו\u0004 — \u0003הוא ובנו וחתנו, ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]\u0006 שאף \u0003גיסו לבדו, וכל שכן חורגו.\u0004 ולפי זה \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 כשיטת \u0003ר' יהודה,\u0004 וה\u0003ברייתא\u0004 ששנה ר' חייא כשיטת \u0003ר' יוסי\u0004 היא.","\u0003אמר רב יהודה אמר שמואל: הלכה כ\u0004שיטת \u0003ר' יוסי.\u0004 ואחר שפסק שמואל הלכה כן, חשבו שהיא מכוונת לפסוק כדברי ר' יוסי במשנה, שתהא הלכה כמשנה ראשונה שרק קרובים הראויים ליורשו פסולים.","מסופר: \u0003ההיא מתנתא דהוי חתימי עלה תרי גיסי\u0004 \u0005[\u0006שטר \u0005מתנה אחד שהיו חתומים עליו שני גיסים].\u0006 \u0003סבר רב יוסף לאכשורה\u0004 \u0005[להכשירה]\u0006 על סמך מה ש\u0003אמר רב יהודה אמר שמואל\u0004 ש\u0003הלכה כ\u0004שיטת \u0003ר' יוסי,\u0004 שהרי הגיס אינו יורש את גיסו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 מסיק אתה שהכוונה לדברי \u0003ר' יוסי דמתניתין\u0004 \u0005[של משנתנו],\u0006 \u0003דמכשר\u0004 \u0005[שהוא מכשיר]\u0006 \u0003בגיסו? דילמא\u0004 \u0005[שמא]\u0006 נתכוון לשיטת \u0003ר' יוסי\u0004 של ה\u0003ברייתא, דפסיל\u0004 \u0005[שפוסל]\u0006 \u0003בגיסו\u0004 (אף כי מתיר את חתן גיסו)?","ודחה רב יוסף ואמר: \u0003לא סלקא\u0004 \u0005[אין זה\u0006 יכול \u0005לעלות]\u0006 על \u0003דעתך.\u0004 ש\u0003אמר שמואל: כגון אנא\u0004 \u0005[אני]\u0006 \u0003ופנחס\u0004 אחי פסולים להעיד, והאם אין כוונתו לומר שהם פסולים \u0003דהוינן אחי וגיסי\u0004 \u0005[שאנו אחים וגיסים],\u0006 שנשאו שני האחים הללו שתי אחיות, \u0003אבל גיסי דעלמא\u0004 \u0005[גיסים בכלל]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר]\u0006 ומותרים להעיד זה לזה.","והקשה אביי: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003כגון אנא\u0004 \u0005[אני]\u0006 \u0003ופנחס, משום\u0004 שהוא \u0003גיסו קאמר\u0004 \u0005[אמר]\u0006 ולא נתכוון לומר שהם פסולים בתורת אחים.","כיון שערער אביי את הוכחתו זו של רב יוסף \u0003אמר\u0004 רב יוסף \u0003ליה\u0004 \u0005[לו]\u0006 למחזיק בשטר: אם כן שהעדים החתומים על השטר פסולים הם \u0003זיל קניה\u0004 \u0005[לך קנה אותה],\u0006 את המתנה, על ידי \u0003עדי מסירה\u0004 שראו כשנמסר בידך שטר זה, ונסמוך על שיטת \u0003ר' אלעזר,\u0004 שאומר שהעדים העיקריים בשטר אינם העדים החתומים בו גופו אלא העדים שראו שמסרו אותו ועדים שבשטר רק לתיקון ולחיזוק נעשו, ואינם עיקר תוקף השטר.","הקשה לו אביי: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא: מודה ר' אלעזר ב\u0004שטר ה\u0003מזויף מתוכו\u0004 כגון שחתמו בו עדים פסולים \u0003שהוא פסול\u0004 גם כשיש עדי מסירה, כי אז פוגמים אותם עדים את עצם מהימנותו של השטר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף למקבל המתנה: \u0003זיל\u0004 \u0005[לך],\u0006 \u0003לא שבקי\u0004 \u0005[הניחו]\u0006 \u0003לי דאותביניה\u0004 \u0005[שאתן אותה],\u0006 את המתנה, \u0003לך.\u0004","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 שאפילו אם מתה בתו ויש לבעלה בנים ממנה הרי הבעל נחשב, בשל הבנים, כקרוב לו לענין עדות. \u0003אמר ר' תנחום אמר ר' טבלא אמר ר' ברונא אמר רב: הלכה כ\u0004שיטת \u0003ר' יהודה.\u0004 ואילו \u0003רבא אמר\u0004 בשם \u0003רב נחמן: אין הלכה כ\u0004שיטת \u0003ר' יהודה. וכן אמר רבה בר בר חנה\u0004 בשם \u0003ר' יוחנן: אין הלכה כ\u0004שיטת \u0003ר' יהודה.\u0004","\u0003איכא דמתני לה\u0004 \u0003להא\u0004 \u0005[יש ששונים אותה,\u0006 את השמועה \u0005הזו]\u0006 שאמר \u0003רבה בר בר חנה, אהא\u0004 \u0005[על\u0006 דבר \u0005זה]\u0006 ששנינו: \u0003את זו דרש ר' יוסי הגלילי,\u0004 נאמר: \u0003\"ובאת אל הכהנים הלוים ואל השפט אשר יהיה בימים ההם\"\u0004 (דברים יז, ט), \u0003וכי תעלה על דעתך שאדם הולך אצל שופט שלא היה בימיו?\u0004 ואם כן מה עניינו של \"אשר יהיה בימים ההם\"? \u0003אלא\u0004 הכוונה: \u0003זה שהיה קרוב\u0004 על ידי נישואין \u0003ונתרחק,\u0004 שעכשיו בימים ההם שהוא בא אליו יכול הוא להיות נידון בפניו, ולא קודם לכן.","ועל כך \u0003אמר רבה בר בר חנה אמר ר' יוחנן: הלכה כ\u0004שיטת \u0003ר' יוסי הגלילי.\u0004 כלומר, אותו תוכן הלכתי (שקרוב שנתרחק כשר) נאמר בשעתו בהקשר אחר.","מסופר: \u0003בני חמוה\u0004 \u0005[בני חמיו]\u0006 של \u0003מר עוקבא\u0004"],["\u0003קרובים ונתרחקו הוו\u0004 \u0005[היו],\u0006 שמתה אשת מר עוקבא שהיתה אחותם. \u0003אתו לקמיה לדינא\u0004 \u0005[באו לפניו לדין],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 מר עוקבא: \u0003פסילנא לכו לדינא\u0004 \u0005[פסול אני לכם לדין].\u0006","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה פוסל עצמך — שאתה פוסק \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 שכיון שיש בנים הרי עדיין אנו קרובים? \u0003אנן מייתינן איגרתא ממערבא\u0004 \u0005[אנו מביאים מכתב מארץ ישראל]\u0006 ש\u0003אין הלכה כ\u0004שיטת \u0003ר' יהודה.\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אטו בקבא דקירא אידבקנא בכו\u0004 \u0005[וכי בקב שעוה דבוק אני בכם],\u0006 ברור לי שאין אנו עוד קרובים ולא משום קירבה אני פוסל את עצמי, \u0003דלא קאמינא פסילנא לכו לדינא\u0004 \u0005[שאין אני אומר\u0006 ש\u0005אני פסול לכם לדין]\u0006 \u0003אלא משום דלא צייתיתו דינא\u0004 \u0005[שאין אתם מצייתים לדין]\u0006 ואין אני רוצה להכנס לדיון כשאני סבור שלא תקבלוהו עליכם","במשנה הובאה דעת ר' יהודה שהאוהב והשונא פסולים להעיד ואמרו ש\u0003אוהב\u0004 — \u0003זה שושבינו.\u0004","ומבררים: \u0003וכמה\u0004 זמן הוא קרוי \"שושבינו\" ויהא פסול לו? \u0003אמר\u0004 \u0003ר' אבא אמר\u0004 \u0003ר' ירמיה אמר רב: כל שבעת ימי המשתה\u0004 הרי הוא נקרא \"שושבינו\" וקרוב הוא אליו. \u0003ורבנן משמיה\u0004 \u0005[וחכמים משמו]\u0006 של \u0003רבא אמרי\u0004 \u0005[אמרו]:\u0006 \u0003אפילו מיום ראשון\u0004 שלמחרת החתונה \u0003ואילך\u0004 אינו עוד כקרוב אלא ביום החתונה עצמו.","עוד שנינו במשנה ש\u0003השונא\u0004 הוא \u0003כל שלא דבר\u0004 עמו שלשה ימים מתוך איבה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 את הנאמר \"והוא לא אויב לו ולא מבקש רעתו\" (במדבר לה, כג), דרשו: \u0003\"והוא לא אויב לו\"\u0004 — \u0003יעידנו. \"ולא מבקש רעתו\"\u0004 — \u0003ידיננו.\u0004","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ראיה ש\u0003שונא\u0004 פסול לעדות, ואולם \u0003אוהב מנלן\u0004 \u0005[מנין לנו]\u0006 שהוא פסול לעדות?","ומשיבים: \u0003קרי ביה הכי\u0004 \u0005[קרא בו\u0006 באותו כתוב \u0005כך],\u0006 בשינוי: \u0003והוא לא אויב לו ולא אוהב לו\u0004 — \u0003יעידנו, ולא מבקש רעתו ולא טובתו\u0004 — \u0003ידיננו.\u0004","ותוהים: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"אוהב\" כתיב\u0004 \u0005[כתוב]\u0006 באותו פסוק, וכיצד אנו מוסיפים מילים בכתוב? \u0003אלא\u0004 זאת \u0003סברא הוא\u0004 לומר כן, כי \u0003אויב מאי טעמא\u0004 \u0005[מה טעם]\u0006 פסול לעדות? — \u0003משום דמרחקא דעתיה\u0004 \u0005[שרחוקה דעתו]\u0006 מאותו אדם והוא יכול לבוא להעיד שקר לרעתו. \u0003אוהב נמי מקרבא דעתיה\u0004 \u0005[גם כן קרובה דעתו]\u0006 ויעיד לטובתו שלא כאמת.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם מסכימים לר' יהודה, \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"לא אויב לו ולא מבקש רעתו\" מאי דרשי ביה\u0004 \u0005[מה דורשים\u0006 הם \u0005בו]?\u0006","ומשיבים: \u0003חד\u0004 \u0005[\u0006חלק \u0005אחד\u0006 של הכתוב\u0005]\u0006 \u0003ל\u0004ענין \u0003דיין,\u0004 שאף הם מודים שהאוהב או שונא אינו רשאי להיות דיין כיון שדעתו נוטה מראש כנגד אחד הצדדים.","\u0003אידך\u0004 \u0005[\u0006החלק \u0005האחר]\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יוסי בר' יהודה: \"והוא לא אויב לו ולא מבקש רעתו\", מכאן לשני תלמידי חכמים ששונאין זה את זה, שאין יושבין בדין כאחד,\u0004 שמתוך שנאתם יבואו לסתור זה דבריו של זה שלא בצדק.","\u0003כיצד בודקים את העדים? היו מכניסין אותן לחדר\u0004 בית הדין \u0003ומאיימין עליהן\u0004 שידברו רק אמת. \u0003ומוציאין את כל האדם לחוץ\u0004 שלא יספרו לעדים האחרים את השאלות והתשובות, \u0003ומשיירין\u0004 רק \u0003את הגדול שבהן\u0004 (בין העדים),","\u0003ואומרים לו: אמור היאך\u0004 בדיוק \u0003אתה יודע שזה חייב לזה\u0004 שעל כך אתה מעיד. \u0003אם אמר: הוא,\u0004 הלווה, \u0003אמר לי\u0004 על עצמו \u0003שאני חייב לו,\u0004 לתובע, או שאמר: \u0003איש פלוני אמר לי שהוא חייב לו,\u0004 לתובע — \u0003לא אמר כלום\u0004 ומיד פוסלים את עדותו, שהרי העדות צריכה להיות על עובדה ולא על ספור מעשה. \u0003עד שיאמר: בפנינו הודה לו,\u0004 לתובע, \u0003שהוא חייב לו מאתים זוז,\u0004 שכיון שהודה בפני עדים הרי זה חייב עצמו בסכום שהזכיר.","\u0003ואחר כך מכניסין את\u0004 העד \u0003השני, ובודקין אותו\u0004 באותה דרך. \u0003אם נמצאו דבריהן מכוונין,\u0004 שהם מעידים על אותו דבר — \u0003נושאין ונותנין\u0004 הדיינים \u0003בדבר.\u0004","אם נחלקו דעות הדיינים, \u0003שנים אומרים: זכאי, ואחד אומר: חייב\u0004 — הרי הוא \u0003זכאי. שנים אומרים: חייב, ואחד אומר: זכאי\u0004 — הרי הוא \u0003חייב. אחד אומר חייב ואחד אומר זכאי\u0004 או \u0003אפילו שנים\u0004 מן הדיינים \u0003מזכין או\u0004 \u0003שנים מחייבין, ואחד\u0004 מן הדיינים \u0003אומר: איני יודע\u0004 ואיני יכול להחליט — \u0003יוסיפו הדיינין\u0004 עוד דיינים ואז יחליטו בדין לפי רוב דעות, שהאומר \"איני יודע\" — כאילו אינו נמצא שם.","\u0003גמרו את הדבר\u0004 והגיעו למסקנה, \u0003היו מכניסין אותן,\u0004 את בעלי הדין. \u0003הגדול שבדיינין אומר: איש פלוני אתה זכאי, איש פלוני אתה חייב.\u0004","\u0003ומניין לכשיצא\u0004 הדיין \u0003לא יאמר \"אני\u0004 הייתי \u0003מזכה\u0004 בדין \u0003וחביריי מחייבים, אבל מה אעשה שחביריי רבו עלי\"\u0004 ומשום כך יצא פסק הדין לחובה, \u0003על זה נאמר: \"לא תלך רכיל בעמיך\"\u0004 (ויקרא יט, טז), \u0003ואומר:\u0004 \u0003\"הולך רכיל מגלה סוד\u0004 ונאמן רוח מכסה דבר\u0003\"\u0004 (משלי יא, יג).","שנינו במשנה שהיו מאיימים על העדים, ושואלים: \u0003היכי אמרינן להו\u0004 \u0005[כיצד אנו אומרים להם],\u0006 מה הם דברי איום אלה? \u0003אמר רב יהודה: הכי אמרינן להו\u0004 \u0005[כך אנו אומרים להם],\u0006 נאמר: \u0003\"נשיאים ורוח וגשם אין איש מתהלל\u0004 \u0003במתת שקר\"\u0004 (משלי כה, יד), כלומר, לא יהיה גשם ולא תהיה ברכה במעשיכם אם תשקרו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: יכלי למימר\u0004 \u0005[יכולים\u0006 אותם אנשים \u0005לומר]\u0006 בלבם שאין להם לחשוש מפני כן על פי הפתגם העממי: \u0003\"שב שני הוה כפנא, ואבבא אומנא\u0004 \u0005[שבע שנים היה רעב, ועל פתחו של האומן]\u0006 \u0003לא חליף\u0004 \u0005[עבר]\u0006","\u0003\",\u0004 ובעלי מלאכה אינם צריכים לחשוש מפני חוסר גשם ולכן לא ישימו לב לאיום זה. \u0003אלא אמר רבא: אמרינן להו\u0004 \u0005[אומרים אנו להם]\u0006 פסוק זה: \u0003\"מפיץ וחרב וחץ שנון איש ענה ברעהו עד שקר\"\u0004 (משלי כה, יח), שעד שקר ימות בלא זמנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי:\u0004 אף כאן \u0003יכלי למימר\u0004 \u0005[יכולים לומר]\u0006 ולחזק עצמם בפתגם העממי: \u0003\"שב שני הוה מותנא, ואיניש\u0004 \u0005[שבע שנים היה דבר, ואדם]\u0006 \u0003בלא שניה\u0004 \u0005[שנותיו]\u0006 \u0003לא שכיב\u0004 \u0005[מת],\u0006 וכל אדם מת בזמן הראוי לו, ולפיכך אף לאיום זה אין הם חוששים.","\u0003אלא אמר רב אשי, אמר לי נתן בר מר זוטרא: אמרינן להו\u0004 \u0005[אומרים אנו להם]\u0006 \u0003\"סהדי שקרי אאוגרייהו זילי\"\u0004 \u0005[\"עדי שקר\u0006 אף \u0005על שוכריהם הם בזויים\"],\u0006 וכל שכן על אחרים. \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שאמרה איזבל כשצוותה לשכור עדים שיעידו כנגד נבות: \u0003\"והושיבו שנים אנשים בני בליעל נגדו ויעדהו לאמר ברכת אלהים ומלך\"\u0004 (מלכים א' כא, י), שאפילו היא שאמרה לשכרם קראה להם \"אנשי בליעל\".","שנינו במשנה ש\u0003אם אמר\u0004 העד ש\u0003הוא,\u0004 הנתבע, \u0003אמר לי\u0004 כי הוא \u0003חייב\u0004 — אין זה מספיק \u0003עד שיאמרו בפנינו הודה לו\u0004 לתובע \u0003שהוא חייב לו מאתים זוז.\u0004","ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 מה שנאמר במשנה \u0003לרב יהודה.\u0004 ש\u0003אמר רב יהודה אמר רב: צריך שיאמר\u0004 לעדים הרואים את מעשה ההלוואה או ההודאה וכיוצא בה \u0003\"אתם עדיי\",\u0004 ואם לא עשה כן אינה עדות.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן,\u0004 אם אמר אדם לחבירו: \u0003\"מנה לי בידך\u0004 שאתה חייב לי \u0003\",\u0004 ו\u0003אמר לו\u0004 חבירו: \u0003\"הן,\u0004 כך הוא \u0003\".\u0004 \u0003למחר אמר לו: \"תנהו לי\",\u0004 אם \u0003אמר\u0004 לו הנתבע: \u0003\"משטה אני בך\",\u0004 כלומר, לא התכוונתי ברצינות בשעה שאמרתי שאני חייב לך — הרי זה \u0003פטור.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 אם אמר לחבירו: \u0003\"מנה לי בידך\",\u0004 ו\u0003אמר לו\u0004 החבר: \u0003\"הן\". למחר אמר לו\u0004 התובע: \u0003\"תנהו לי\". אמר לו\u0004 הנתבע: \u0003\"משטה אני בך\"\u0004 — \u0003פטור.\u0004","\u0003ולא עוד אלא אפילו הכמין\u0004 (הסתיר) \u0003לו עדים אחורי גדר\u0004 שלא יראם הנתבע, \u0003ואמר לו \"מנה לי בידך\", אמר לו\u0004 אותו אדם: \u0003\"הן\",\u0004 ואמר לו התובע: \u0003\"רצונך שתודה בפני פלוני ופלוני\u0004 העדים שאתה חייב לי \u0003\"?\u0004 \u0003אמר לו:\u0004 \"לא, כי \u0003מתיירא אני שמא תכפיני לדין\u0004 ותוציא ממני בעל כרחי כשתרצה ולכן לא אודה לפניהם, אבל לך אומר אני שאני חייב\". \u0003למחר אמר לו: \"תניהו לי\u0004 את המנה שהודית בו \u0003\".\u0004 \u0003אמר לו\u0004 הנתבע: \u0003\"משטה אני בך\"\u0004 — \u0003פטור,\u0004 שיכול לומר שבהודאה זו לא נתכוון אלא לפייס דעתו לפי שעה, אבל לא נתכון להודות לו באמת, שהרי לא ידע שיש עדים במקום.","\u0003ואין טוענין למסית.\u0004","על פסקה זו תוהים: \u0003מסית מאן דכר שמיה\u0004 \u0005[מי הזכיר\u0006 את \u0005שמו],\u0006 כלומר, מדוע מזכירים כאשר לא דובר בו כלל קודם לכן? ומסבירים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003אם לא טען\u0004 טענה זו שהיה משטה — \u0003אין טוענין לו\u0004 בבית הדין, שאומרים: אם כך הודה — מן הסתם לכך נתכוון. \u0003ובדיני נפשות, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא טען\u0004 כל טענה שהיה יכול לטעון לזכותו \u0003טוענין לו\u0004 הדיינים. אבל \u0003אין טוענין למסית\u0004 לעבודה זרה, שאם הוא עצמו אינו טוען לזכותו אין בית הדין מצווה לטעון ולהשתדל לזכותו.","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003מסית\u0004 שאין מהפכים בזכותו? \u0003אמר ר' חמא בר חנינא: מפירקיה\u0004 \u0005[מדרשתו]\u0006 של \u0003ר' חייא בר אבא שמיע לי\u0004 \u0005[שמעתי]\u0006 דבר זה: \u0003שאני\u0004 \u0005[שונה]\u0006 ה\u0003מסית, דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 \u0003\"\u0004ו\u0003לא תחמל ולא תכסה עליו\"\u0004 (דברים יג, ט), שבדין מיוחד זה אין בית הדין מצווה לדאוג להצלתו.","ו\u0003אמר ר' שמואל בר נחמן אמר ר' יונתן: מניין שאין טוענין למסית?\u0004 — \u0003מנחש הקדמוני\u0004 שפיתה את חוה שהוא היה המסית הראשון. ש\u0003אמר ר' שמלאי: הרבה טענות היה לו לנחש לטעון\u0004 לזכות עצמו \u0003ולא טען, ומפני מה לא טען לו הקדוש ברוך הוא\u0004 כדי לזכותו? — \u0003לפי שלא טען הוא.\u0004","ושואלים: \u0003מאי הוה ליה למימר\u0004 \u0005[מה היה לו לומר]?\u0006 ומשיבים: היה לו לומר שאין האשמה תלויה בו, שכן כלל הוא: \u0003דברי הרב ודברי תלמיד\u0004 — \u0003דברי מי שומעין?\u0004 — הלא \u0003דברי הרב שומעין,\u0004 ומאחר ואמר ה' לא לאכול מפרי העץ, לא היו אדם וחוה צריכים לשמוע בקול הנחש ולאכלו.","\u0003אמר חזקיה\u0004 בקשר לאותו ענין: \u0003מניין שכל המוסיף גורע\u0004 — \u0003שנאמר\u0004 שאמרה חוה: \u0003\"אמר אלהים לא תאכלו ממנו ולא תגעו בו\"\u0004 (בראשית ג, ג), והלא ה' לא אמר אלא איסור אכילה (\"ומעץ הדעת טוב ורע לא תאכל ממנו\". בראשית ב, יז) ולא איסור נגיעה, וכיון שהוסיפה חוה שיש איסור נגיעה בעץ, והראה לה הנחש שאין מתים בנגיעה, נכשלה אף באכילה.","\u0003רב משרשיא אמר: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה שהמוסיף גורע, כגון במילים \u0003\"אמתים וחצי ארכו\"\u0004 (שמות כה, י), שבלי הא' בראש המלה היינו קוראים מ(א)תיים וחצי, וההוספה באה לגרוע את המספר ולומר שאינו אלא אמתים וחצי.","\u0003רב אשי אמר:\u0004 כגון הכתוב \u0003\"עשתי עשרה יריעת\"\u0004 (שמות כו, ז), שעל ידי הוספת הע' נעשה מ\"שתי עשרה\" רק עשתי עשרה (אחת עשרה), שהוספת האות הקטינה את המספר.","\u0003אמר אביי:\u0004 לענין מי שכפר בתביעה שהודה בה בפני עדים מוסתרים \u0003לא שנו אלא\u0004 ש\u0003אמר \"משטה אני בך\"\u0004 שאז אין מועילה ההודאה, \u0003אבל\u0004 אם \u0003אמר\u0004"],["\u0003\"לא היו דברים מעולם\",\u0004 כלומר, מעולם לא הודיתי בכך — \u0003הוחזק כפרן,\u0004 שהרי שמעו העדים שהודה ושוב אינו נאמן בשבועה, שהרי עדים מעידים בו ששיקר.","כנגד דעה זו \u0003אמר רב פפא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא בר אדא: הכי אמרינן משמיה\u0004 \u0005[כך אומרים אנו משמו]\u0006 של \u0003רבא:\u0004 אף כאן אין נקרא שקרן כי \u0003כל מילי דכדי\u0004 \u0005[דברים של ריק]\u0006 \u0003לא דכירי אינשי\u0004 \u0005[זוכרים אנשים],\u0006 וכיון שהודאה זו לא ברצינות נאמרה, שמא שכח אותו אדם מה שהיה, ואף כאשר כפר בכך אין זו הוכחה שהוא משקר ביודעין.","מסופר: \u0003ההוא דאכמין ליה\u0004 \u0005[\u0006אדם \u0005אחד שהטמין לו]\u0006 \u0003עדים לחבריה בכילתיה\u0004 \u0005[לחבירו בתוך הכילה\u0006 שעל המיטה\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לחבר: \u0003\"מנה לי בידך\".\u0004 \u0003אמר ליה: \"הן\".\u0004 \u0003אמר\u0004 אותו אדם: \u0003\"עירי ושכבי ליהוו עלך סהדי\"\u0004 \u0005[הערים והישנים יהיו עליך עדים],\u0006 ורצה להכשילו שיסכים לעדות זו, מתוך שסבר שיחשוב אותו אדם שכולם ישנים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו האיש: \u0003\"לא\". אמר רב כהנא\u0004 כשבא הדבר לדין: \u0003הא אמר ליה\u0004 \u0005[הרי אמר לו]\u0006 \u0003\"לא\",\u0004 ואם כן אין זו הודאה של ממש.","וכיוצא בו מסופר, \u0003ההוא דאכמין\u0004 \u0005[\u0006אדם \u0005אחד שהטמין לו]\u0006 לחבירו \u0003עדים בקיברא לחבריה\u0004 \u0005[\u0006\u0005ב\u0006תוך \u0005קבר לחבירו],\u0006 ובתוך בית הקברות \u0003אמר ליה\u0004 \u0005[לו]\u0006 לחבר: \u0003\"מנה לי בידך\", אמר ליה\u0004 \u0005[לו]\u0006 החבר: \u0003\"הן\",\u0004 אמר לו: \u0003\"חיי ומיתי ליהוו עלך סהדי\"\u0004 \u0005[החיים והמתים יהיו עליך עדים]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הנתבע: \u0003\"לא\". אמר ר' שמעון:\u0004 אף כאן אין זו הודאה, שכן \u0003הא אמר ליה\u0004 \u0005[הרי אמר לו]\u0006 \u0003\"לא\".\u0004","\u0003אמר רבינא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב פפא: שמע מינה מהא\u0004 \u0005[למד מזה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב יהודה אמר רב: צריך שיאמר \"אתם עדיי\", לא שנא כי\u0004 \u0005[אינו שונה אם]\u0006 \u0003אמר\u0004 זאת ה\u0003לוה\u0004 \"אתם עדי\", \u0003ולא שנא כי\u0004 \u0005[ואינו שונה אם]\u0006 \u0003אמר מלוה ושתיק\u0004 \u0005[ושותק]\u0006 ה\u0003לוה,\u0004 כי במקרים שאמרנו שאין מקבלים הודאה זו, \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 ש\u0003אמר\u0004 ה\u0003לוה\u0004 \u0005\"\u0006\u0003לא\",\u0004 שאינו רוצה בעדים, \u0003אבל אי שתיק\u0004 \u0005[אם היה שותק]\u0006 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 היתה זו נחשבת להודאה.","מסופר: \u0003ההוא דהוה קרו ליה \"קב רשו\"\u0004 \u0005[\u0006אדם \u0005אחד שהיו קורין לו \"קב חובות\"],\u0006 כלומר, איש שהכל נושים בו. \u0003אמר\u0004 פעם אחת בפני הבריות: \u0003מאן מסיק\u0004 \u0005[מי\u0006 בעצם \u0005נושה]\u0006 \u0003בי\u0004 \u0003אלא פלוני ופלוני\u0004 בלבד. כלומר, אינני חייב הרבה כל כך כפי שסבורים. \u0003אתו\u0004 \u0005[באו]\u0006 אותם אנשים שהודה שהוא חייב להם \u0003תבעוהו לדינא קמיה\u0004 \u0005[ותבעוהו לדין לפני]\u0006 \u0003רב נחמן\u0004 שיחזיר מה שהוא חייב להם, ואותו אדם טען שהיה משטה.","\u0003אמר רב נחמן: אדם עשוי שלא להשביע את עצמו,\u0004 כלומר, יתכן שאדם אומר ברבים שהוא חייב כסף כדי שלא יחשב לעשיר (\"שבע\") ועל כן כל זמן שלא הודה הודאה מוגדרת שהוא חייב סך ידוע לאדם מסוים אין בכך כלום.","כיוצא בו מסופר: \u0003ההוא דהוו קרו ליה \"עכברא דשכיב אדינרי\"\u0004 \u0005[\u0006אדם \u0005אחד שהיו קוראים לו \"עכבר השוכב על הדינרים\"],\u0006 שהוא קמצן שאיננו נהנה מממונו כעכבר ששוכב ושומר על דינרי זהב, \u0003כי קא שכיב\u0004 \u0005[כאשר נטה למות]\u0006 \u0003אמר: \"פלניא ופלניא מסקו\u0004 \u0005[פלוני ופלוני נושים]\u0006 \u0003בי זוזי\u0004 \u0005[זוזים,\u0006 כסף\u0005]\u0006 \u0003\".\u0004 \u0003בתר דשכיב אתו תבעינהו\u0004 \u0005[לאחר שמת באו\u0006 ו\u0005תבעו אותם],\u0006 את ה\u0003יורשין,\u0004","\u0003אתו לקמיה\u0004 \u0005[באו\u0006 לדין \u0005לפני]\u0006 \u0003ר' ישמעאל בר' יוסי, אמר להו\u0004 \u0005[להם]\u0006 במקרה זה: \u0003כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 ש\u0003אדם עשוי שלא להשביע את עצמו\u0004 ולהוציא על עצמו שם שהוא עני — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003מחיים,\u0004 בעודו חי, \u0003אבל לאחר מיתה\u0004 — \u0003לא\u0004 יעשה זאת, ומן הסתם אמת אמר.","\u0003פרעו\u0004 היורשים \u0003פלגא\u0004 \u0005[חצי]\u0006 סכום התביעה. \u0003תבעינהו לדינא לאידך פלגא\u0004 \u0005[תבעו\u0006 הנושים אותם לדין \u0005על החצי האחר].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו\u0006 לדין \u0005לפני]\u0006 \u0003ר' חייא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003כשם שאדם עשוי שלא להשביע את עצמו כך אדם עשוי שלא להשביע את בניו,\u0004 שיתכן שמתחילה לא נתכוון אלא להעמיד פנים שגם בניו אינם עשירים. ואם כן אין מקום לתביעה. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 אם כן \u0003ניזיל וניהדר\u0004 \u0005[נלך ונחזיר\u0006 את הדין\u0005]\u0006 ונקבל את הסכום ששילמנו לתובעים! \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003כבר הורה זקן\u0004 (חכם) בדין זה ודינו קיים ואין בכוחי לבטל פסק דין קודם.","מי ש\u0003הודה בפני שנים\u0004 שהוא חייב, \u0003וקנו מידו,\u0004 שעשו גם קבלת קנין לאמת ולקיים את ההודאה — \u0003כותבין,\u0004 יכולים העדים לכתוב את הדברים כשטר ולחתום עליו, ולתת יתר חיזוק לדבר. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שלא עשו קנין אלא הודאה בלבד — \u0003אין כותבין.\u0004 שבמקרה כזה אנו אומרים שרצה להשאיר את הדבר בגדר של הלוואה בעל פה, ולא כהלוואה בכתב.","הודה \u0003בפני שלשה ולא קנו מידו,\u0004 בכך נחלקו, \u0003רב אמי אמר: כותבין,\u0004 שכיון שהודה בפני שלושה שהם כבית דין, ובית דין רשאי לכתוב מעשה בית דין. \u0003ורב אסי אמר: אין כותבין,\u0004 שלא נתכוון אלא לעדות בלבד. מסופר: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 שהודה אחד בפני שלושה \u0003וחש לה\u0004 \u0005[וחשש]\u0006 \u0003רב להא\u0004 \u0005[ל\u0006דבר \u0005זה]\u0006 של \u0003רב אסי\u0004 והורה שלא לכתוב, שמא לא נתכוון לעשות אותם כבית דין.","\u0003אמר רב אדא בר אהבה: הא אודיתא, זימנין כתבינן וזימנין לא כתבינן\u0004 \u0005[הודאה זו, פעמים כותבים אנו\u0006 מה שהודה \u0005ופעמים אין אנו כותבים].\u0006 כיצד? — אם \u0003כניפי ויתבי\u0004 \u0005[היו\u0006 שלושה \u0005נאספים ויושבים]\u0006 והודה בפניהם — \u0003לא כתבינן\u0004 \u0005[אין אנו כותבים]\u0006 בשטר, שאנו אומרים שלא נתכוון לעשותם בית דין. אבל אם \u0003כנפינהו איהו\u0004 \u0005[אספם הוא]\u0006 — \u0003כתבינן\u0004 \u0005[כותבים אנו],\u0006 שרואים שהקפיד להביא שלושה ולא שנים בלבד, משמע שנתכוון לעשותם כבית דין.","\u0003רבא אמר: אפילו\u0004 אם \u0003כנפינהו איהו\u0004 \u0005[אספם הוא]\u0006 — \u0003לא כתבינן\u0004 \u0005[אין אנו כותבים]\u0006 שטר, \u0003עד דאמר להו\u0004 \u0005[שיאמר להם]:\u0006 \u0003\"הוו\u0004 \u0005[היו]\u0006 \u0003עלי דייני\u0004 \u0005[דיינים]\u0006","\u0003\".\u0004 \u0003מר בר רב אשי אמר: אפילו אמר \"הוו\u0004 \u0005[היו]\u0006 \u0003עלי דייני\u0004 \u0005[דיינים]\u0006 \u0003\"\u0004— \u0003לא כתבינן\u0004 \u0005[אין אנו כותבים]\u0006 שטר, \u0003עד דקבעי דוכתא ושלחי ומזמני ליה לבי דינא\u0004 \u0005[שיקבעו מקום\u0006 לדין \u0005וישלחו\u0006 שליחים \u0005ויזמינו אותו לבית דין],\u0006 אבל אם לא נעשה ככל דרכי בית דין, איננו אומרים שהתכוון שיהיו לו לענין זה כבית דין.","ועוד בהלכה זו: \u0003הודה במטלטלי\u0004 (מטלטלין) שהוא חייב לו, \u0003וקנו מידו\u0004 — הרי \u0003כותבין, ואם לאו\u0004 \u0005[לא]\u0006 עשו קנין — \u0003אין כותבין.\u0004 הודה \u0003במקרקעי ולא קנו מידו, מאי\u0004 \u0005[מה\u0006 הדין\u0005],\u0006 האם נאמר כי כיון שהקרקע נתנה תמיד לגביה הרי זה כקנין, או לא? \u0003אמימר אמר: אין כותבין. מר זוטרא אמר: כותבין. והלכתא\u0004 \u0005[והלכה]\u0006 היא ש\u0003כותבין.\u0004","\u0003רבינא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום \u0003דמהריא,\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב דימי בר רב הונא מדמהריא לרבינא:\u0004 אם היתה זו הודאה ב\u0003מטלטלי ואיתנהו בעינייהו\u0004 \u0005[מטלטלים ו\u0006הם נמצאים \u0005בעינם]\u0006 באותו מקום, \u0003מאי\u0004 \u0005[מהו]\u0006 הדין, האם במקרה זה, שאין צורך מיוחד במסירה יחשבו כקרקעות, ויכתבו, או לא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כמקרקעי דמו\u0004 \u0005[כקרקעות\u0006 הם \u0005נחשבים].\u0006 \u0003רב אשי אמר: כיון דמחסרי גוביינא\u0004 \u0005[ש\u0006הם \u0005מחוסרים\u0006 עדיין \u0005גביה]\u0006 — \u0003לא\u0004 כותבים, אלא אם כן ביקש שיכתבו.","מסופר: \u0003ההיא אודיתא\u0004 \u0005[שטר הודאה אחד]\u0006 ש\u0003לא הוה כתוב בה\u0004 \u0005[היה כתוב בו]\u0006 \u0003\"אמר לנא\u0004 \u0005[לנו]\u0006 המודה \u0003כתבו וחתמו והבו ליה\u0004 \u0005[ותנו לו]\u0006 \u0003\"\u0004\u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 המקרה שבו אפשר להחיל את דברי \u0003ריש לקיש.\u0004","ש\u0003אמר ריש לקיש: חזקה אין העדים חותמין על השטר אלא אם כן נעשה גדול,\u0004 כלומר, ודאי בדקו העדים וראו שהיה המוכר מבוגר ורשאי למכור, אף שלא נאמר בשטר במפורש שבדקו דבר זה. ומכאן נלמד הלכה כללית שאין העדים חותמים על השטר ואין הסופרים כותבים אותו אלא אם כן ידעו שהכל היה כסדרו, ולכן גם אם חסר פרט מסויים אין להוכיח מכאן, ובוודאי היה הכל כראוי.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 שהקשה: \u0003מי איכא מידי דאנן לא ידעינן\u0004 \u0005[האם יש דבר שאנו\u0006 החכמים \u0005איננו יודעים],\u0006 שיש חכמים שאינם יודעים הלכה זו שאין כותבים בלא שיבקש מי שהודה, \u0003וספרי דבי דינא ידעי\u0004 \u0005[ו\u0006אילו \u0005סופרי בית הדין יודעים]\u0006 ואפשר לסמוך עליהם אולי בדקו את הדבר?!","\u0003שאילינהו לספרי\u0004 \u0005[שאלו את סופרי\u0006 בית הדין\u0005]\u0006 של \u0003אביי\u0004 — \u0003וידעי\u0004 \u0005[וידעו],\u0006 \u0003לספרי\u0004 \u0005[את סופרי\u0006 בית הדין\u0005]\u0006 של \u0003רבא\u0004 — \u0003וידעי\u0004 \u0005[וידעו],\u0006 משמע שסופרי בית הדין כיון שזאת אומנותם יודעים את הדינים השייכים לכך.","מסופר: \u0003ההיא אודיתא דהוה כתב ביה \"דוכרן פיתגמי\"\u0004 \u0005[שטר הודאה אחד שהיה כתוב בו זכרון דברים]\u0006 נעשה בפנינו,"],["\u0003וכל לישני דבי דינא\u0004 \u0005[וכל הלשונות\u0006 במעשה \u0005בבית דין]\u0006 וחתמו עליו שנים בלבד, אבל \u0003לא הוה כתב בה\u0004 \u0005[היה כתוב בו]\u0006 כראוי \u0003\"במותב תלתא הוינא וחד ליתוהי\"\u0004 \u0005[במושב שלושה ישבנו ואחד\u0006 מאתנו \u0005איננו],\u0006 כגון שמת או נסתלק מטעם אחר. והיה איפוא מקום לחשוב שמא שנים בלבד, שהוזמנו בתורת עדים, כתבו את ההודאה שלא כדין.","\u0003סבר רבינא למימר\u0004 \u0005[לומר]\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 אותו דבר שאמר \u0003ריש לקיש\u0004 שאין עדים חותמים על שטר אלא אם כן נעשה כדינו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נתן בר אמי: הכי אמרינן משמיה\u0004 \u0005[כך אומרים אנו משמו]\u0006 של \u0003רבא:\u0004 ב\u0003כל\u0004 מקרה \u0003כי האי גוונא\u0004 \u0005[כעין זה]\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לבית דין טועין\u0004 שסברו ששנים כשרים לדון.","\u0003אמר רב נחמן בר יצחק: אי כתב בה \"בי דינא\" תו לא צריך\u0004 \u0005[אם היה כתוב בו\u0006 \"\u0005אנו\u0006 חברי \u0005בית הדין\u0006 ישבנו\", \u0005שוב אינו צריך]\u0006 שיהיה כתוב שאחד מהם איננו, שבית הדין מן הסתם של שלושה הוא.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003בית דין\u0004 זה \u0003חצוף הוא,\u0004 ועל סמך דברי שמואל, ש\u0003אמר שמואל: שנים שדנו\u0004 — \u0003דיניהם דין, אלא שנקראו \"בית דין חצוף\".\u0004 ומסבירים: כגון \u0003דכתב ביה \"בי דינא דרבנא אשי\"\u0004 \u0005[שהיה כתוב בו \"בית דין של רבינו אשי\"],\u0006 שאינם סתם הדיוטות העשויים לנהוג שלא כהלכה.","ומקשים: \u0003ודילמא רבנן דבי\u0004 \u0005[ושמא חכמים שבבית]\u0006 \u0003רב אשי כשמואל סבירא להו\u0004 \u0005[סבורים הם]\u0006 ועשו בית דין בשנים! ומשיבים: \u0003דכתיב\u0004 \u0005[שכתוב]\u0006 \u0003בו \"ואמרנא ליה לרבנא אשי ואמר לן רבנא אשי\"\u0004 \u0005[\"ואמרנו לו לרבנו אשי ואמר לנו רבינו אשי\"],\u0006 שרב אשי ודאי לא היה משתתף בבית דין שאינו ראוי.","בהמשך לבעיה מה היא הודאה של אמת ומתי אין מקבלים הודאה ועדות, מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003אמר להן\u0004 אדם \u0003אחד\u0004 לבנים: \u0003אני ראיתי אביכם שהטמין מעות בשידה\u0004 (כעין קופסה) \u0003תיבה\u0004 או ב\u0003מגדל\u0004 (ארון), \u0003ואמר: \"\u0004מעות אלה \u0003של פלוני הן\",\u0004 או שאמר \u0003\"\u0004מעות אלה \u0003של מעשר שני הן\",\u0004 ואכן נמצאו המעות במקום שאמר. אם סיפר העד בתיבה שידה ומגדל שהיו \u0003בבית\u0004 — \u0003לא אמר כלום\u0004 ואין מקבלים עדותו בדבר ייעוד המעות, שמאחר שאין הוא יכול לקחת לעצמו את הכסף אם ירצה, אין עדותו של עד אחד מחייבת את הבנים. אבל אם אמר על דבר ש\u0003בשדה\u0004 — \u0003דבריו קיימין.\u0004","\u0003כללו של דבר: כל שבידו\u0004 של העד \u0003ליטלן\u0004 (את המעות) — \u0003דבריו קיימין,\u0004 שהרי אם רצה לשקר ולרמות יכול היה לקחת את הכסף בעצמו, ואם \u0003אין בידו ליטלן\u0004 — \u0003לא אמר כלום.\u0004","וכיוצא בזה \u0003הרי שראו\u0004 הבנים עצמם \u0003את אביהן שהטמין מעות בשידה תיבה ומגדל, ואמר:\u0004 \u0003\"\u0004מעות אלה \u0003של פלוני הן,\u0004 או שאמר \u0003\"\u0004מעות אלה \u0003של מעשר שני הן\", אם כמוסר,\u0004 שאומר דברים אלה בסגנון ובאופן שאדם מוסר לבניו דבר להודיעם — \u0003דבריו קיימין, אם כמערים,\u0004 שנראה להם שהוא רוצה להערים כדי שלא יקחו את הממון ואומר להם שהממון אינו שלו — \u0003לא אמר כלום,\u0004 ואינם צריכים לחשוש להשתמש בכסף.","ועוד, \u0003הרי שהיה\u0004 אדם \u0003מצטער על מעות שהניח לו אביו\u0004 בירושה ולא מצאן \u0003ובא בעל החלום\u0004 (ראה בחלומו) \u0003ואמר לו:\u0004 סכום של \u0003כך וכך הן\u0004 המעות, \u0003במקום פלוני הן,\u0004 אולם מעות אלה \u0003של מעשר שני הן,\u0004 ומצא סכום זה במקום שחלם עליו — \u0003זה היה מעשה\u0004 שבא לפני חכמים, \u0003ואמרו: דברי חלומות לא מעלין ולא מורידין\u0004 ואין לסמוך על החלום ולומר שהממון אינו שייך לבן, לפי שחלום אינו מעלה ואינו מוריד בענייינים הנוגעים הלכה למעשה, ואין ללמוד ממנו.","במשנה שנינו שאם \u0003שנים אומרים זכאי\u0004 ואחד אומר חייב — יוצא זכאי. ושואלים: כאשר כותבים בשטר, \u0003מיכתב היכי כתבי\u0004 \u0005[כיצד כותבים]\u0006 כשיש מחלוקת בין הדיינים?","\u0003ר' יוחנן אמר:\u0004 כותבים \u0003\"זכאי\"\u0004 ואין מפרטים שנחלקו בכך. \u0003ריש לקיש אמר:\u0004 מפרטים \u0003\"פלוני ופלוני מזכין, ופלוני ופלוני מחייבין\",\u0004 שבמקרה כזה צריך להודיע. \u0003ר' אלעזר אמר:\u0004 אין מפרטים שמות אבל משנים את הנוסח וכותבים: \u0003\"מדבריהן נזדכה פלוני\"\u0004 ומשמע מכאן שלא כל הדיינים הסכימו לזכותו, אלא הסכמת הרוב היא.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל הלכה למעשה \u0005ביניהם]\u0006 חוץ מדרך הכתיבה לבדה? ומשיבים: \u0003איכא בינייהו לשלומי איהו מנתא בהדייהו\u0004 \u0005[יש ביניהם\u0006 הבדל הלכה למעשה \u0005ל\u0006ענין \u0005שישלם הוא\u0006 שחלק על חבריו את \u0005חלקו יחד אתם]\u0006 אם מתברר שטעו בדין. \u0003דלמאן דאמר\u0004 \u0005[של\u0006 שיטת \u0005מי שאומר]\u0006 שכותבים סתם \u0003\"זכאי\"\u0004 — הרי גם הוא \u0003משלם. ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 שכותבים \u0003\"פלוני ופלוני מזכין ופלוני ופלוני מחייבין\"\u0004 — \u0003לא משלם.\u0004","ותוהים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 שכותבים בשטר \u0003\"זכאי\"\u0004 מדוע \u0003משלם?! לימא להו\u0004 \u0005[שיאמר להם]:\u0006 \u0003אי לדידי צייתיתון אתון נמי\u0004 \u0005[אם לי הייתם שומעים, אתם גם כן]\u0006 \u0003לא שלמיתון\u0004 \u0005[הייתם משלמים],\u0006 ואם כן משום מה חייב אני לשלם על טעות שלכם?","\u0003אלא\u0004 הוא בוודאי אינו משלם, ו\u0003איכא בינייהו לשלומי אינהו מנתא דידיה\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה \u0005ל\u0006ענין \u0005שישלמו הם\u0006 את \u0005חלקו שלו]\u0006 כאשר טעו. \u0003למאן דאמר\u0004 \u0005[\u0006לדעת \u0005מי שאומר]\u0006 שכותבים סתם \u0003\"זכאי\"\u0004 — \u0003משלמי\u0004 \u0005[משלמים]\u0006 הם הכל, שהרי לא פירשו שהיתה מחלוקת בדבר. \u0003למאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 שכותבים \u0003\"פלוני ופלוני מזכין ופלוני ופלוני מחייבין\"\u0004 — הם \u0003לא משלמי\u0004 \u0005[משלמים]\u0006 את חלקו של האחר, וגם הוא לא ישלם.","ומקשים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 שיכתוב \u0003\"זכאי\"\u0004 מדוע \u0003משלמי\u0004 \u0005[משלמים\u0006 הם הכל\u0005]?\u0006 \u0003ולימרו ליה\u0004 \u0005[ושיאמרו לו]:\u0006 \u0003אי לאו את בהדן\u0004 \u0005[אילו לא\u0006 היית \u0005אתה איתנו]\u0006 \u0003לא הוה סליק דינא מידי\u0004 \u0005[היה עולה הדין כלל],\u0006 שאין דנים בשנים אלא ודאי שותף אתה איתנו באחריות. ואם כן אין לפטרו מכל וכל בטענה זו.","\u0003אלא\u0004 עלינו לחזור בנו מן ההסברים הקודמים ולומר רק כי \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 רק לגבי עצם הכתיבה, אם יש לחשוש \u0003משום\u0004 איסור של \u0003\"לא תלך רכיל בעמיך\"\u0004 (ויקרא יט, טז). \u0003ר' יוחנן אמר:\u0004 כותבין \u0003\"זכאי\" משום \"לא תלך רכיל\"\u0004 מפני חשש רכילות, ו","\u0003ריש לקיש אמר\u0004 כותבים \u0003\"פלוני ופלוני מזכין ופלוני ופלוני מחייבין\" משום דמיחזי כשיקרא\u0004 \u0005[שנראה כשקר]\u0006 אם לא יפרטו, שהרי לא כולם אמרו זכאי.","\u0003ור' אלעזר אית ליה דמר, ואית ליה דמר\u0004 \u0005[יש לו,\u0006 מקבל את טענתו \u0005של חכם זה, ויש לו,\u0006 מקבל גם את טענתו \u0005של חכם זה].\u0006 \u0003הלכך כתבי הכי\u0004 \u0005[לכן כותבים כך]:\u0006 \u0003\"מדבריהם נזדכה פלוני\"\u0004 ואין מפרטים, אבל מתוך שינוי הנוסח יודעים שלא כולם הסכימו לכך, ואין הולכים רכיל ואף אין אומרים דבר הנראה כשקר.","שנינו במשנה כי כאשר \u0003גמרו\u0004 הדיינים \u0003את הדבר היו מכניסין\u0004 אותם לבית הדין. ושואלים: \u0003למאן\u0004 \u0005[את מי]\u0006 מכניסים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 את \u0003בעלי הדינין,\u0004 והלא \u0003התם קיימי\u0004 \u0005[שם\u0006 הם \u0005עומדים]\u0006 כל הזמן, ולא יצאו כלל! \u0003אלא\u0004 מכניסים את ה\u0003עדים.\u0004","ואם כן \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 שיטת משנתנו? — ש\u0003לא כ\u0004שיטת \u0003ר' נתן. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לעולם אין עדותן\u0004 של עדים \u0003מצטרפת עד שיראו שניהן כאחד\u0004 אותו פרט עצמו. \u0003ר' יהושע בן קרחה אומר: אפילו\u0004 ראו \u0003בזה אחר זה\u0004 מעידים.","\u0003ו\u0004עוד: \u0003אין עדותן\u0004 של עדים \u0003מתקיימת בבית דין עד שיעידו שניהן כאחד.\u0004 ואילו \u0003ר' נתן אומר:\u0004 לאו דווקא, אלא \u0003שומעין דבריו של זה היום, וכשיבא חבירו למחר שומעין את דבריו.\u0004 ואילו ממשנתנו משמע שיש לגמור את הדין כששני העדים מצויים יחד דווקא!","ודוחים: \u0003לא,\u0004 אין הכרח לפרש כך, ו\u0003לעולם\u0004 תפרש שמכניסין את \u0003בעלי\u0004 ה\u0003דינין, ו\u0004דבר זה כשיטת \u0003ר' נחמיה היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נחמיה אומר: כך היה מנהגן של נקיי הדעת שבירושלים:\u0004 בשעה שהיו דנים, היו \u0003מכניסין\u0004 את \u0003בעלי\u0004 ה\u0003דינין ושומעין\u0004 את \u0003דבריהן\u0004 וטענותיהן, \u0003ומכניסין את העדים ושומעין\u0004 את \u0003דבריהם\u0004 בפני בעלי הדינים, \u0003ו\u0004אחר כך \u0003מוציאין אותן\u0004 כולם \u0003לחוץ ונושאין ונותנין בדבר.\u0004 לכש \u0003גמרו את הדבר מכניסין אותן,\u0004 את בעלי הדין לשמוע את גזר דינם.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003גמרו את הדבר מכניסין את העדים!\u0004 ומשיבים: הברייתא \u0003ההיא\u0004 ודאי שהיא ש\u0003לא כ\u0004דעת \u0003ר' נתן.\u0004","ודנים \u0003גופא\u0004 \u0005[לגופה\u0006 של אותה הלכה\u0005]\u0006 שהבאנו קודם. שנינו בה: \u0003לעולם אין עדותן\u0004 של עדים \u0003מצטרפת עד שיראו שניהם כאחד. ר' יהושע בן קרחה אומר: אפילו\u0004 ראו \u0003בזה אחר זה.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומסבירים: \u0003איבעית אימא קרא, ואיבעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 שנחלקו בפירוש \u0005הכתוב, ואם תרצה אמור\u0006 שנחלקו ב\u0005סברה].\u0006 כיצד?","\u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 ש\u0005סברה\u0006 היא\u0005],\u0006 שכן על ה\u0003מנה\u0004 של חוב \u0003דקא מסהיד האי\u0004 \u0005[שמעיד זה]\u0006 \u0003לא קא מסהיד האי\u0004 \u0005[מעיד זה],\u0006 \u0003ו\u0004על \u0003מנה דקא מסהיד האי\u0004 \u0005[שמעיד זה]\u0006 \u0003לא קמסהיד האי\u0004 \u0005[מעיד זה],\u0006 ויש כאן עד אחד לכל מאורע ומאורע, ואין די בעדות עד אחד. \u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' יהושע בן קרחה, סבור: על \u0003מנה בעלמא תרוייהו קמסהדי\u0004 \u0005[סתם שניהם מעידים],\u0006 וכיון ששניהם מעידים על מנה, מכל מקום מנה אחד חייב לו.","\u0003ואיבעית אימא קרא\u0004 \u0005[ואם תרצה אמור\u0006 הדבר תלוי בפירוש \u0005הכתוב],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והוא עד או ראה או ידע\u0004 אם לא יגיד ונשא עוונו\u0003\"\u0004 (ויקרא ה, א),","\u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \"לא יקום עד אחד באיש לכל עוון ולכל חטאת בכל חטא אשר יחטא על פי שני עדים או על פי שלושה עדים יקום דבר\" (דברים יט, טו), \u0003ממשמע שנאמר \"לא יקום עד\"\u0004 בלשון יחיד \u0003איני יודע שהוא אחד?\u0004 ו\u0003מה\u0004 אם כן \u0003תלמוד לומר\u0004 בכל זאת \u0003\"\u0004עד \u0003אחד\"\u0004 —","\u0003זה בנה אב,\u0004 כלומר, בסיס לכלל גדול: \u0003כל מקום שנאמר\u0004 בתורה \u0003\"עד\"\u0004 — \u0003הרי כאן שנים,\u0004 שהם עדות שלמה, \u0003עד שיפרט לך הכתוב\u0004 במפורש \u0003\"\u0004עד \u0003אחד\".\u0004","\u0003ואפקיה רחמנא\u0004 \u0005[והוציאה,\u0006 ביטאה \u0005אותו]\u0006 התורה \u0003בלשון חד\u0004 \u0005[אחד],\u0006 כלומר, \"עד\" ולא \"עדים\", \u0003למימר\u0004 \u0005[לומר\u0006 לנו\u0005]\u0006 רמז בכך: \u0003עד דחזו תרוייהו כחד\u0004 \u0005[שיראו שניהם כאחד]\u0006 כאיש אחד. \u0003ואידך\u0004 \u0005[והאחר\u0006\u0005]\u0006 ר' יהושע בן קרחה סומך על מה שנאמר \u0003\"והוא עד או ראה או ידע\",\u0004 שלשונות ריבוי אלה באים לרבות \u0003מכל מקום,\u0004 שהמעיד על מה שראה וידע הרי זו עדות.","עוד שנינו שם ש\u0003אין עדותן מתקיימת בבית דין עד שיעידו שניהן כאחד. ר' נתן אומר: שומעין דבריו של זה היום וכשיבא חבירו למחר שומעין דבריו,\u0004 שאפשר לשמוע את עדותם גם שלא בבת אחת. ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]\u0006 ומסבירים, \u0003איבעית אימא סברא, איבעית אימא קרא\u0004 \u0005[אם תרצה אמור\u0006 שב\u0005סברה\u0006 נחלקו, \u0005ואם תרצה אמור\u0006 בפירוש \u0005מקרא].\u0006","\u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא \u0005סבור]:\u0006 \u0003עד אחד,\u0004 הראשון, \u0003כי אתי\u0004 \u0005[כאשר בא]\u0006 להעיד — \u0003ל\u0004חייב \u0003שבועה\u0004 את הנתבע \u0003אתי\u0004 \u0005[הוא בא]\u0006 שסבור שהוא עד יחיד, ועד יחיד מחייב שהנתבע ישבע שאינו אשם, \u0003לממונא לא אתי\u0004 \u0005[ל\u0006הוציא \u0005ממון\u0006 ממש \u0005לא בא]\u0006 שלא נתכוון להצטרף לעדות גמורה, ולכן אין לראות עדותם כיחידה אחת אלא כשמעידים שניהם כאחד.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' נתן אומר: \u0003אטו כי אתו בהדי הדדי, בחד פומא קא מסהדי\u0004 \u0005[וכי כאשר הם באים יחד, בפה אחד הם מעידים],\u0006 והלא גם אז מעידים הם זה אחר זה. \u0003אלא מצרפינן להו\u0004 \u0005[מצרפים אותם]\u0006 לעדות אחת, \u0003הכא נמי ליצרפינהו\u0004 \u0005[כאן גם כן\u0006 שיש הפרש זמן גדול יותר \u0005שיצרפנו אותם]\u0006 אף שאינם מעידים כאחת.","\u0003ואיבעית אימא קרא\u0004 \u0005[ואם תרצה אמור\u0006 שנחלקו ב\u0005כתוב]\u0006 שנאמר \u0003\"אם לוא יגיד ונשא עו‍נו\"\u0004"],["\u0003ודכולי עלמא\u0004 \u0005[והכל]\u0006 גם תנא קמא וגם ר' נתן סבורים \u0003כרבנן דפליגי עליה\u0004 \u0005[כחכמים שחלוקים עליו]\u0006 על \u0003ר' יהושע בן קרחה\u0004 וסבורים הם שהכרחי שהעדים יראו כאחד. \u0003והכא באקושי\u0004 \u0005[וכאן בהקשת,\u0006 בהשוואת\u0005]\u0006 \u0003הגדה\u0004 (עדות) \u0003לראיה\u0004 עצמה \u0003קא מיפלגי\u0004 \u0005[נחלקו].\u0006 \u0003מר\u0004 \u0003סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא \u0005סבור]\u0006 ש\u0003מקשינן\u0004 \u0005[מקישים\u0006 משווים \u0005אנו]\u0006 \u0003הגדה לראיה\u0004 וכשם שחייבים לראות כאחד — כך חייבים להעיד כאחד, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' נתן \u0005סבור]:\u0006 \u0003לא מקשינן\u0004 \u0005[אין אנו מקישים,\u0006 משווים\u0005].\u0006","מסופר ש\u0003ר' שמעון בן אליקים הוה משתקיד עליה\u0004 \u0005[היה שוקד\u0006 ודואג עליו\u0005]\u0006 על \u0003ר' יוסי בר' חנינא למסמכיה\u0004 \u0005[לסמוך אותו],\u0006 \u0003ולא קא מיסתייע מילתא\u0004 \u0005[היה מסתייע,\u0006 מזדמן \u0005לו]\u0006 הדבר. \u0003יומא חד הוה יתיב קמיה\u0004 \u0005[יום אחד היה יושב\u0006 ר' שמעון בן אליקים \u0005לפני]\u0006 \u0003ר' יוחנן,\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר'\u0004 יוחנן לתלמידיו היושבים לפניו: \u0003מי איכא דידע\u0004 \u0005[האם יש\u0006 מי \u0005שיודע]\u0006 אם \u0003הלכה כ\u0004שיטת \u0003ר' יהושע בן קרחה, או לא? אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון בן אליקים: דין ידע\u0004 \u0005[זה,\u0006 ר' יוסי בר חנינא הוא \u0005יודע],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לימא איזו\u0004 \u0005[שיאמר אם כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ליסמכיה מר ברישא\u0004 \u0005[שיסמכו אדוני תחילה],\u0006 שכיון שהכל זקוקים לחכמתו ראוי הוא לסמיכה. \u0003סמכיה\u0004 \u0005[סמכו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בני, אמור לי כיצד שמעת? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כך שמעתי, שמודה ר' יהושע בן קרחה לר' נתן\u0004 שאין צורך שיבואו שניהם ויעידו כאחד.","\u0003אמר\u0004 ר' יוחנן באכזבה: וכי \u0003לזה הוצרכתי?! השתא\u0004 \u0005[עכשיו],\u0006 \u0003ומה\u0004 בענין \u0003עיקר\u0004 העדות שהיא \u0003ראיה בהדי הדדי\u0004 \u0005[ביחד],\u0006 \u0003אמר ר' יהושע בן קרחה\u0004 כי \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שתהא כאחד, \u0003הגדה,\u0004 אמירת עדות \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאין צורך שיעידו ביחד? דבר זה היה מובן, ולא הוצרכתי לעדותך.","והוסיף ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 אף על פי כן \u0003הואיל ועלית\u0004 והוסמכת \u0003לא תרד,\u0004 אף שבטעות היה הדבר. \u0003אמר ר' זירא, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003גברא רבה\u0004 \u0005[אדם גדול],\u0006 \u0003כיון דסמיך\u0004 \u0005[שנסמך]\u0006 — \u0003סמיך\u0004 \u0005[נסמך].\u0006 שאם נסמך אדם הראוי לסמיכה, גם אם נעשה הדבר משיקול מוטעה — סמיכה זו קיימת, ואין מבטלים אותה.","ולענין ההלכה בענין זה \u0003אמר ר' חייא בר אבין אמר רב: הלכה כ\u0004שיטת \u0003ר' יהושע בן קרחה, בין בקרקעות בין במטלטלין,\u0004 שאין צורך שיראו כאחד.","ו\u0003עולא אמר: הלכה כ\u0004שיטת \u0003ר' יהושע בן קרחה\u0004 לגבי \u0003קרקעות\u0004 שהם יציבים ועומדים ובוודאי העדות היא באותה קרקע עצמה, \u0003אבל לא במטלטלין\u0004 שמא לא על אותו מאורע הם מעידים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אם אומר אתה \u0003הלכה\u0004 בענין זה \u0003מכלל\u0004 הדבר אתה למד \u0003דפליגי\u0004 \u0005[שנחלקו]\u0006 בנושא זה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא אמר רב הונא אמר רב:\u0004 \u0003מודים חכמים לר' יהושע בן קרחה בעדות קרקע.\u0004","\u0003ותני\u0004 \u0005[ושנה]\u0006 \u0003רב אידי בר אבין ב\u0004פרקי \u0003נזיקין\u0004 שהיו שונים \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של החכם \u0003קרנא:\u0004 \u0003מודים חכמים לר' יהושע בן קרחה בעדות בכור, ובעדות קרקע, ובעדות חזקה,\u0004 שכיון שברור שמעידים על אותו דבר אין צורך שיראו העדים בבת אחת \u0003וכן\u0004 לגבי סימנים (שתי שערות באיזור הערוה שהן סימן בגרות) \u0003שבבן ושבבת,\u0004 ומשמע אם כן שלא נחלקו!","ודוחים: זו אינה קושיה, \u0003גברא אגברא קא רמית\u0004 \u0005[מאדם על אדם אתה משליך,\u0006 מראה סתירה\u0005]?!\u0006 שאין להקשות על עולא משיטת אמורא אחר. \u0003מר\u0004 \u0003סבר\u0004 \u0005[חכם זה,\u0006 עולא \u0005סבור\u0006\u0005]\u0006 כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 חכמים אף בכך, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב ורב אידי \u0005סבור\u0006 \u0005ים]\u0006 כי \u0003לא פליגי\u0004 \u0005[נחלקו].\u0006","דרך אגב מבררים \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וכן שבבן ושבבת\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003אחד\u0004 מן העדים \u0003אומר\u0004 שראה שערה \u0003אחת בגבה, ואחד אומר\u0004 שראה שערה \u0003אחת בכריסה,\u0004 ואולם \u0003האי\u0004 \u0005[זה]\u0006 \u0003חצי דבר וחצי עדות הוא,\u0004 כלומר, לא רק שהעדות חצויה אלא גם נושא העדות (דבר) אינו שלם, שהרי כל אחד מהם מעיד רק שראה שערה אחת ונמצא שכל אחד מהם לא העיד על דבר שלם, וכיצד איפוא נצרף עדותם ליחידה אחת?","\u0003אלא\u0004 יש לומר בכגון זה: ש\u0003אחד אומר\u0004 ראיתי \u0003שתים בגבה, ואחד אומר\u0004 ראיתי \u0003שתים בכריסה,\u0004 וכיון ששניהם מעידים שבוגרת היא אין אנו צריכים שיראו שניהם כאחד.","\u0003אמר רב יוסף: אנא אמינא משמיה\u0004 \u0005[אני אמרתי משמו]\u0006 של \u0003עולא:\u0004 \u0003הלכה כ\u0004שיטת \u0003ר' יהושע בן קרחה\u0004 בכל, \u0003בין בקרקעות בין במטלטלין, ורבנן דאתו\u0004 \u0005[וחכמים שבאו]\u0006 \u0003ממחוזא אמרי\u0004 \u0005[אמרו]\u0006 ש\u0003אמר ר' זירא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 \u0003בקרקעות\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל לא במטלטלין.\u0004","ומסבירים: \u0003רב לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב: הודאה אחר הודאה,\u0004 שהעיד אחד ואמר \"בפני הודה לו הלווה למלוה\", והעיד אחר ואמר אף הוא \"בפני הודה לו\". וכן \u0003הודאה אחר הלואה,\u0004 שהעיד אחד ואמר \"בפני הודה לו הנתבע שחייב לו\", ואחד העיד על זמן קודם לכך: \"בפני הלווה לו\" — הרי אלו \u0003מצטרפי\u0004 \u0005[מצטרפים]\u0006 לעדות אחת.","ואולם \u0003הלואה אחר הלואה,\u0004 שזה מעיד שבפניו הלווה לו מנה, וזה מעיד שבפניו הלווה לו מנה, או \u0003הלואה אחר הודאה,\u0004 שאחד מעיד שהלווה לו, ואולם התאריך בו היתה ההלוואה לפי דבריו היה אחר הזמן שעליו העיד אחר שבו הודה הנתבע שלווה מהתובע — \u0003לא מצטרפי\u0004 \u0005[אינם\u0006","\u0005מצטרפים],\u0006 שכן יתכן והם מעידים על שני מאורעות שונים. \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003רב נחמן בר יצחק\u0004 את \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003הלואה אחר הלואה דלא\u0004 \u0005[שאין]\u0006 אתה מקבל את העדות? — שיש לחשוש שעל ה\u0003מנה דקא חזי האי\u0004 \u0005[שראה זה,\u0006 העד השני\u0005]\u0006 \u0003לא קא חזי האי\u0004 \u0005[לא ראה זה,\u0006 הראשון\u0005],\u0006 ואם כן אף \u0003הודאה אחר הודאה נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש שמא על ה\u0003מנה דקא\u0004 \u0005[שהוא]\u0006 \u0003מודה קמי האי\u0004 \u0005[לפני זה]\u0006 הוא \u0003לא מודי קמי האי\u0004 \u0005[מודה לפני זה],\u0006 ושמא הודה על שתי הלוואות שונות ואין כאן איפוא מקום לצרף?","השיב לו: \u0003דאמר ליה להאי בתרא\u0004 \u0005[שאמר לו לזה\u0006 העד \u0005האחרון]\u0006 \u0003:\u0004 \u0003בהאי\u0004 \u0005[באותו]\u0006 ה\u0003מנה דאודיי ליה קמך\u0004 \u0005[שאני מודה לו לפניך],\u0006 \u0003אודיי ליה נמי קמי\u0004 \u0005[הודיתי לו גם כן בפני]\u0006 \u0003פלוני\u0004 העד הראשון.","ושאל: \u0003אכתי, בתרא ידע, קמא לא ידע\u0004 \u0005[עדיין,\u0006 העד \u0005האחרון יודע\u0006 שעל אותו דבר הוא מעיד, אבל העד \u0005הראשון אינו יודע],\u0006 ואם כן העיד הראשון רק על חצי דבר!","אמר לו: יש לפרש \u0003דהדר אזיל אמר ליה לקמא\u0004 \u0005[שחוזר ואומר ל\u0006עד \u0005הראשון]:\u0006 \u0003האי\u0004 \u0005[אותו]\u0006 \u0003מנה דאודיי ליה קמך\u0004 \u0005[שהודיתי\u0006 בו \u0005לו לפניך],\u0006 \u0003אודיי ליה נמי קמי\u0004 \u0005[הודיתי בו גם כן בפני]\u0006 \u0003פלוני,\u0004 ואם כן שני העדים בטוחים שהודה על אותו דבר עצמו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003תנוח דעתך שהתנחת\u0004 (הנחת) \u0003את דעתי\u0004 והסברת לי דבר שנתקשיתי בו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003מאי ניחותא\u0004 \u0005[מה הנוחות\u0006 בדבר\u0005]?\u0006 — ש\u0003רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב ששת, שדא בה נרגא\u0004 \u0005[היה מטיל בו גרזן],\u0006 כלומר, מוצא פירכה במה שאמרתי, כי באופן שאני מסביר \u0003לאו היינו\u0004 \u0005[האם לא זוהי\u0006 בדיוק\u0005]\u0006 \u0003הודאה אחר הלואה,\u0004 שבמקרה זה אין כל חידוש בדבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בר יצחק: \u0003היינו דשמיע לי עלייכו דרמיתו דיקלי וזקפיתו להו\u0004 \u0005[זהו ששמעתי עליכם\u0006 חכמי מחוזא, \u0005שאתם מפילים דקלים ומקימים אותם],\u0006 שאתם בונים וסותרים, שאחרי שכבר מצאו אצלכם הסבר יפה כל כך, אתם באים ומקלקלים אותו בעצמכם.","\u0003נהרדעי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרדעא אומרים]:\u0006 \u0003בין\u0004 שהיתה זו \u0003הודאה אחר הודאה, בין הודאה אחר הלואה, בין הלואה אחר הלואה, בין הלואה אחר הודאה\u0004 — \u0003מצטרפות, כמאן\u0004 \u0005[\u0006כשיטת \u0005מי]\u0006 בדיוק? — \u0003כ\u0004שיטת \u0003ר' יהושע בן קרחה,\u0004 שכיון שהם מעידים על מנה סתם הרי זו נחשבת כעדות אחת.","\u0003אמר רב יהודה: עדות המכחשת זו את זו,\u0004 כששני העדים מספרים דברים סותרים \u0003בבדיקות\u0004 כלומר, בפרטים בענין המעשה \u0003כשרה בדיני ממונות,\u0004 אף שסתירה כגון זו פוסלת את העדות בדיני נפשות.","\u0003אמר רבא: מסתברא מילתיה\u0004 \u0005[מסתבר הדבר]\u0006 שאמר \u0003רב יהודה\u0004 אם עד \u0003אחד אומר:\u0004 הכסף היה \u0003בארנקי שחורה, ואחד אומר: בארנקי לבנה. אבל\u0004 אם \u0003אחד אומר: מנה שחור\u0004 (כהה) הלווה לו, \u0003ואחד אומר מנה לבן\u0004 הלווה לו — \u0003אין מצטרפין,\u0004 משום שבמקרה זה הסתירה היא בגוף העדות. שאף אם אמנם לא הקפידו כשאינם זוכרים פרטים צדדיים, ואולם בדברים שהם עיקר העדות אם סתרו זה את זה — מן הסתם משקרים הם.","ותוהים: וכי כשסותרים בפרטים צדדיים כגון \u0003ארנקי שחורה בדיני נפשות לא\u0004 נקבל עדותם?! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא, אחד\u0004 העדים \u0003אומר: בסייף הרגו, ואחד אומר: בארירן\u0004 (מין חרב) \u0003הרגו\u0004 — \u0003אין זה נכון,\u0004 שהרי בית דין צריך לברר אם \"אמת נכון הדבר\" והעדות בטלה. ואולם אם \u0003אחד אומר: כליו\u0004 (בגדיו) של זה היו \u0003שחורים, ואחד אומר: כליו לבנים\u0004 — \u0003הרי זה נכון,\u0004 משום שאין זו סתירה בגוף העדות אלא בפרטים טפלים!"],["ומשיבים: \u0003גברא אגברא קא רמית\u0004 \u0005[\u0006מ\u0005אדם לאדם אתה משליך,\u0006 מראה סתירה\u0005]?\u0006 שרב חסדא סבור שאין זו הכחשה, ורב יהודה סבור שיש בכך הכחשה, ואין דבריו של אחד מחייבים את חבירו.","\u0003נהרדעי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרדעא אומרים]:\u0006 \u0003אפילו אחד אומר: מנה שחור, ואחד אומר: מנה לבן\u0004 — הרי הם \u0003מצטרפים.\u0004","\u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא דעה זו — \u0003כ\u0004שיטת \u0003ר' יהושע בן קרחה.\u0004 ותוהים: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[לו,\u0006 אותו \u0005]\u0006 את \u0003ר' יהושע בן קרחה\u0004 שאומר ששתי העדויות מצטרפות \u0003היכא דלא מכחשו אהדדי\u0004 \u0005[במקום שאינן מכחישות זו את זו],\u0006 אבל \u0003היכא דמכחשי אהדדי מי\u0004 \u0005[במקום ש\u0006הן \u0005מכחישות זו את זו האם]\u0006 \u0003אמר?\u0004","\u0003אלא הוא\u0004 כלומר, חכמי נהרדעא, ש\u0003אמר כי האי תנא\u0004 \u0005[כתנא זה].\u0006 \u0003דתניא\u0004 \u0005[שכן שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: לא נחלקו בית שמאי ובית הלל על שתי כיתי עדים שאחת אומרת: מאתים\u0004 דינרים הלווה לו, \u0003ואחת אומרת: מנה\u0004 \u0005[מאה דינר]\u0006 הלווה לו, שאין זו סתירה גמורה בין הדברים, לפי \u0003שיש בכלל מאתים מנה\u0004 ומקבלים את העדות לגבי מנה.","אלא \u0003על מה נחלקו?\u0004 — \u0003על כת אחת\u0004 (זוג אחד של עדים) שעד אחד אומר: מאתיים, ועד שני אומר: מנה. \u0003שבית שמאי אומרים: נחלקה עדותן,\u0004 שאינם מעידים על אותו דבר וממילא נפסלה כל העדות, \u0003ובית הלל אומרים: יש בכלל מאתים מנה.\u0004 משמע שלדעת בית הלל לפי מסורתו של ר' שמעון בן אלעזר אף שברור שאינם מעידים בדיוק על אותו דבר, כיון שנמצא שמחייבים שניהם את הנתבע בסכום מסוים יש לקבל את העדות. ודעה זו היא המקור לדעת חכמי נהרדעא.","מסופר, במקרה כגון זה שעד \u0003אחד אומר \"חבית של יין\u0004 נתן לו \u0003\",\u0004 \u0003ואחד אומר: \"חבית של שמן\u0004 נתן לו \u0003\",\u0004 \u0003הוה עובדא\u0004\u0005[היה מעשה],\u0006 \u0003ואתי לקמיה\u0004 \u0005[ובא\u0006 לדין \u0005לפני]\u0006 \u0003ר' אמי.\u0004 \u0003חייביה\u0004 \u0005[חייבו]\u0006 \u0003ר' אמי לשלומי ליה חביתא דחמרא מיגו חביתא דמשחא\u0004 \u0005[לשלם\u0006 לתובע \u0005חבית יין מתוך\u0006 מחירה \u0005של חבית שמן],\u0006 שחבית יין זולה יותר, ועל כל פנים בדמי חבית יין הסכימו שניהם.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אמר זאת? ומתרצים: \u0003כ\u0004שיטת \u0003ר' שמעון בן אלעזר.\u0004 ויש לתמוה: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר\u0004 \u0003ר' שמעון בן אלעזר היכא\u0004 \u0005[במקום]\u0006 ש\u0003יש בכלל מאתים מנה,\u0004 ואולם במקרה \u0003כי האי גוונא\u0004 \u0005[כגון זה]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 שהרי המעיד על המנה שמא ראה מחצית דבר והשני ראה את כולו, אבל כאן ברור שאין העדויות נוגעות כלל באותו נושא!","ומתרצים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003ל\u0004מקרה של \u0003דמי\u0004 \u0005[דמים],\u0006 כלומר, אחד אומר: דמי חבית יין, והשני אומר: דמי חבית שמן, שהוא ממש כעין מאתים ומנה.","ועוד מסופר, במקרה כגון זה שעד \u0003אחד אומר: בדיוטא\u0004 (קומה) \u0003העליונה\u0004 היה הדבר, \u0003ואחד אומר: בדיוטא התחתונה, אמר ר' חנינא: מעשה\u0004 כגון זה \u0003בא לפני רבי וצירף עדותן\u0004 כשיטת ר' יהושע בן קרחה, שכיון ששניהם מודים בעיקר הענין אין לדקדק בפרטים.","שנינו במשנה ש\u0003מנין\u0004 \u0003לכשיצא\u0004 הדיין מבית הדין לאחר שנפסק הדין, לא יגלה מה היו דעות הדיינים וכו'. \u0003תנו רבנן: מניין לכשיצא לא יאמר\u0004 אחד הדיינים: \u0003הריני מזכה וחבירי מחייבין, אבל מה אעשה שחבירי רבו עלי?\u0004 — \u0003תלמוד לומר: \"לא תלך רכיל בעמיך\"\u0004 (ויקרא יט, טז), \u0003ואומר \"הולך רכיל מגלה סוד\u0004 ונאמן רוח מכסה דבר\u0003\"\u0004 (משלי יא, יג).","ועל גודל ההקפדה בזה מסופר: \u0003ההוא תלמידא דנפיק עליה קלא דגלי מילתא דאיתמר בי מדרשא\u0004 \u0005[תלמיד אחד שיצא עליו קול שגילה דבר\u0006 שהיה צורך להסתירו \u0005שנאמר בבית המדרש].\u0006 \u0003בתר עשרין ותרתין שנין\u0004 \u0005[אחר עשרים ושתים שנים]\u0006 מסיפור המאורע עליו סיפר התלמיד, \u0003אפקיה\u0004 \u0005[הוציאו]\u0006 \u0003רב אמי מבי מדרשא\u0004 \u0005[מבית המדרש]\u0006 כעונש. \u0003אמר: דין גלי רזיא\u0004 \u0005[זה מגלה סודות]\u0006 ואין לסמוך עליו.","\u0003כל זמן שמביא\u0004 אחד הטוענים \u0003ראיה\u0004 נוספת הריהו \u0003סותר את הדין\u0004 שדנו בהתאם לראיות הקודמות. \u0003אמר לו\u0004 צד אחד לשני: \u0003כל ראיות שיש לך הבא מיכן עד שלשים יום,\u0004 אם \u0003מצא בתוך שלשים יום\u0004 — \u0003סותר\u0004 את הדין שנפסק קודם על פי הראיות, מצא \u0003לאחר שלשים יום\u0004 — שוב \u0003אינו סותר.\u0004","\u0003אמר רבן שמעון בן גמליאל:\u0004 אין לומר כן, כי \u0003מה יעשה זה ש\u0004חיפש ו\u0003לא מצא בתוך שלשים\u0004 יום, אלא \u0003מצא לאחר שלשים\u0004 יום?!","דין אחר הוא אם \u0003אמר לו\u0004 לצד שכנגדו: \u0003הבא עדים,\u0004\u0003 ואמר\u0004: \u0003אין לי עדים. אמר\u0004 לו: \u0003הבא ראיה\u0004 אחרת, \u0003ואמר\u0004 לו: \u0003אין לי ראיה,\u0004 \u0003ולאחר זמן הביא ראיה\u0004 או ש\u0003מצא עדים\u0004 — \u0003הרי זה אינו כלום,\u0004 שמסתבר שיש בכך עדות שקר או זיוף.","\u0003אמר רבן שמעון בן גמליאל: מה יעשה זה שלא היה יודע שיש לו עדים ומצא\u0004 לבסוף \u0003עדים\u0004 המעידים לזכותו, או ש\u0003לא היה יודע שיש לו ראיה ומצא\u0004 לבסוף \u0003ראיה.\u0004","ועוד מקרה: אם בתחילת הדיון בבית הדין לא הביא עדים או ראיה אחרת כהוכחה לטענותיו, ואולם מש \u0003ראה ש\u0004הוא \u0003מתחייב בדין\u0004 שב\u0003ואמר: \"קרבו\u0004 (הביאו) \u0003פלוני ופלוני ויעידוני\u0004 שאני צודק \u0003\",\u0004 \u0003או שהוציא ראיה\u0004 שהיתה עמו \u0003מתחת פונדתו\u0004 (כעין חגורה חלולה) — \u0003הרי זה אינו כלום,\u0004 שמסתבר שאילו היה ממש בעדים אלו או בראיה זו לא היה מטמינם עד עכשיו.","ביחס לדין הראשון במשנה \u0003אמר רבה בר רב הונא: הלכה כרבן שמעון בן גמליאל. ואמר רבה בר רב הונא: אין הלכה כדברי חכמים.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003כיון\u0004 ש\u0003אמר\u0004 ש\u0003הלכה כרבן שמעון בן גמליאל, ממילא ידענא\u0004 \u0005[יודעים אנו]\u0006 ש\u0003אין הלכה כחכמים!\u0004","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003:\u0004 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003לכתחילה\u0004 שיש לפסוק כרבן שמעון בן גמליאל, \u0003אבל\u0004 ב\u0003דיעבד,\u0004 כשכבר נעשה מעשה, \u0003שפיר דמי\u0004 \u0005[יפה הדבר]\u0006 גם כחכמים, שלא נדחתה שיטה זו מכל וכל מן ההלכה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דאי עביד מהדרינן ליה\u0004 \u0005[שאם עושה\u0006 כדברי חכמים \u0005מחזירים אותו,\u0006 את דינו\u0005].\u0006","בדין השני במשנה אמרו, \u0003אמר לו: הבא עדים,\u0004 והודה שאין לו, ולאחר זמן מצא, \u0003רבן שמעון בן גמליאל\u0004 היה מכשיר עדים וראיות אלו. \u0003אמר רבה בר רב הונא אמר ר' יוחנן: \"הלכה כדברי חכמים\". ואמר רבה בר רב הונא אמר ר' יוחנן: אין הלכה כרבן שמעון בן גמליאל.\u0004","ואף כאן תוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003כיון\u0004 ש\u0003אמר הלכה כדברי חכמים, ממילא ידענא\u0004 \u0005[יודעים אנו]\u0006 ש\u0003אין הלכה כרבן שמעון בן גמליאל!\u0004","ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה\u0006 בא \u0005להשמיע לנו],\u0006 שאמנם \u0003ב\u0004הלכה \u0003ההיא\u0004 \u0003אין הלכה כרבן שמעון בן גמליאל, הא בכולהו\u0004 \u0005[הרי בכל]\u0006 שאר המקומות שאמר רבן שמעון בן גמליאל דברים במשנה — \u0003הלכה כרבן שמעון בן גמליאל.\u0004","\u0003לאפוקי מהא\u0004 \u0005[ולהוציא מ\u0006דבר \u0005זה]\u0006 ש\u0003אמר רבה בר בר חנה\u0004 בשם \u0003ר' יוחנן: כל מקום ששנה רבן שמעון בן גמליאל במשנתנו הלכה כמותו, חוץ\u0004 מדעתו בדין אחריות של \u0003ערב,\u0004 ומעשה שהיה ב\u0003צידן,\u0004 ודין ה\u0003ראיה\u0004 ה\u0003אחרונה,\u0004 שבמקרה הראשון (\"ראיה ראשונה\") אמרנו שההלכה כמותו, אבל בדין השני של ראיות — אין הלכה כמותו. ורבה בר רב הונא סבור שאף בערב וצידן הלכה כמותו.","מסופר: \u0003ההוא ינוקא דתבעוהו לדינא קמיה\u0004 \u0005[ילד אחד שתבעו אותו לדין לפני]\u0006 \u0003רב נחמן.\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך סהדי\u0004 \u0005[עדים\u0006 לטובתך\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא.\u0004 הוסיף לשאול: האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך ראיה?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא. חייביה\u0004 \u0005[חייבו]\u0006 \u0003רב נחמן\u0004 על פי טענת הצד השני.","\u0003הוה קא בכי ואזיל\u0004 \u0005[היה בוכה והולך].\u0006 \u0003שמעוהו הנך אינשי\u0004 \u0005[אנשים אחדים],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אנן ידעינן במילי דאבוך\u0004 \u0005[אנו יודעים בענייני אביך]\u0006 ויכולים להעיד לטובתך. וכשהביאם לפני רב נחמן \u0003אמר רב נחמן: בהא\u0004 \u0005[ב\u0006כגון \u0005זה]\u0006 \u0003אפילו רבנן מודו\u0004 \u0005[מודים]\u0006 ששומעים לו, \u0003דינוקא במילי דאבוה לא ידע\u0004 \u0005[שתינוק אינו יודע בענייני אביו],\u0006 וכשאמר שאין לו עדים וראיה — בטעות אמר ואין לחשוש לרמאות.","מסופר: \u0003ההיא איתתא דנפק שטרא מתותי ידה\u0004 \u0005[אשה אחת שיצא שטר מתחת ידה]\u0006 שהיא היתה ממונה על שמירתו, \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לדיין: \u0003ידענא בהאי שטרא דפריע הוה\u0004 \u0005[יודעת אני בשטר זה שפרוע הוא]\u0006 ואין לגבות בו. \u0003הימנה\u0004 \u0005[האמין לה]\u0006 \u0003רב נחמן\u0004 ולא הניח לגבות את השטר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אומר אתה הלכה זו? — \u0003כ\u0004שיטת \u0003רבי,\u0004 ש\u0003אמר: אותיות\u0004 (כלומר, שטרות, שעיקרם הדברים הכתובים בהם) — \u0003נקנות במסירה,\u0004 שאין צורך לכתוב שטר על השטר, ובעצם העובדה שמוסר אדם לחבירו את השטר נעשה כבעל שטר. ולכן, אשה זו שהשטר היה בידה דינה כבעלת השטר, ולכן יכולה היא לומר שפרוע הוא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: לאו דווקא מטעם זה, אלא \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 שמאמינים לה מפני הסברה, \u0003דאי בעיא קלתיה\u0004 \u0005[שאילו רצתה\u0006 יכלה \u0005לשרוף\u0006 אותו\u0005],\u0006 וכיון שהיה הדבר בידה, רגליים לדבר שבצדק אמרה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שלא כך היה, אלא \u0003לא הימנה\u0004 \u0005[האמין לה]\u0006 \u0003רב נחמן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: והא אי בעיא\u0004 \u0005[והרי אם היתה רוצה]\u0006"],["\u0003קלתיה\u0004 \u0005[היתה שורפת אותו]!\u0006","השיב לו רב נחמן: \u0003כיון דאיתחזק בבי דינא\u0004 \u0005[ש\u0006השטר \u0005הוחזק בבית הדין],\u0006 ויש עליו אישור, \u0003איבעיא קלתיה לא אמרינן\u0004 \u0005[\u0006ש\u0005אם היתה רוצה היתה שורפת אותו אין אנו אומרים],\u0006 ששטר זה היה עליו כבר קיום של בית דין, ואין מבטלים תוקפו של שטר מאושר מפני טענה בלי ראיות.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו: \u0003סימפון\u0004 (שובר, קבלה) \u0003שיש עליו עדים\u0004 — \u0003יתקיים בחותמיו,\u0004 שיעידו העדים שזו חתימת ידם והרי הוא אישור לסימפון. \u0003אין עליו עדים ו\u0004השובר \u0003יצא מתחת ידי שליש\u0004 שנתנו לו שישמור את השטר, \u0003או שיצא אחר חיתום שטרות,\u0004 שנמצא השובר כתוב לאחר טופס השטר ולאחר חתימת העדים — הרי זה \u0003כשר. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003שליש מהימן\u0004 \u0005[נאמן],\u0006 ויכול להעיד עליו מכח זה אף שאין עדים.","והוא איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב נחמן,\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: לעולם מביא\u0004 אדם \u0003ראיה\u0004 לטענתו בדין \u0003ו\u0004אף \u0003סותר\u0004 את הפסק הקודם \u0003עד שיסתתם טענותיו\u0004 ולא יהיו לו טענות. \u0003ויאמר: \"קרבו פלוני ופלוני והעדוני\".\u0004","ושואלים: \u0003הא גופא קשיא\u0004 \u0005[\u0006הלכה \u0005זו עצמה קשה]:\u0006 \u0003אמרת \"\u0004עד ש\u0003יסתתם טענותיו\"\u0004 — \u0003אתאן לרבנן\u0004 \u0005[באת,\u0006 פסקת \u0005כ\u0006שיטת \u0005חכמים],\u0006 \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003אמרת: \"\u0004\u0003קרבו איש פלוני ופלוני והעידוני\"\u0004 — \u0003אתאן\u0004 \u0005[\u0006הרי \u0005הגענו]\u0006 \u0003ל\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 שרק בזה מודה הוא שאין ליחס חשיבות לעדים אלה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שכל ההלכה \u0003כולה\u0004 כשיטת \u0003רבן שמעון בן גמליאל, ופרושי קא מפרש\u0004 \u0005[ו\u0006יש לראות כאילו הוא \u0005מפרש\u0006 את דבריו\u0005]\u0006 באופן זה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עד שיסתתם טענותיו\"\u0004 — \u0003עד שיאמר \"קרבו פלוני ופלוני והעידוני\", והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל מקום ששנה רבן שמעון בן גמליאל במשנתינו הלכה כמותו, חוץ מערב וצידן וראיה אחרונה,\u0004 הרי שלענין ראיה אחרונה אין הלכה כמותו אלא כחכמים!","\u0003אלא\u0004 ודאי יש כאן שיבוש, ו\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: לעולם מביא ראיה וסותר עד שיסתתם טענותיו, ויאמרו לו: הבא עדים! ואומר: אין לי עדים. הבא ראיה! ואומר: אין לי ראיה,\u0004 כדברי חכמים במשנתנו. \u0003אבל\u0004 אם \u0003באו עדים ממדינת הים, או שהיתה דיסקיא\u0004 (צרור השטרות) \u0003של אביו מופקדת ביד אחר,\u0004 שבמקרים אלה לא ידע שיש לו ראיה — \u0003הרי זה מביא ראיה\u0004 מתוך אלה \u0003וסותר\u0004 ואין לחשוש לרמאות. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: התוקף,\u0004 כלומר, מחזיק בתוקף, תובע \u0003את חבירו בדין,\u0004 ו\u0003אחד\u0004 מן המתדיינים \u0003אומר: נדון כאן\u0004 במקומנו, \u0003ואחד אומר: נלך למקום הוועד\u0004 שהוא מקום מושב הסנהדרין או מקום מושב בית הדין הגדול — \u0003כופין אותו וילך למקום הוועד,\u0004 ששם בית דין מעולה יותר. \u0003אמר לפניו ר' אלעזר: רבי,\u0004 אם כן, \u0003מי שנושה בחבירו מנה\u0004 והלווה גר בעיר אחרת, וכי \u0003יוציא מנה\u0004 הוצאות נסיעה ושהייה באותה עיר \u0003על מנה\u0004 שהוא צריך לגבות? \u0003אלא כופין אותו ודן בעירו.\u0004","","","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן\u0006 מעין זה\u0005]\u0006 \u0003אמר רב ספרא אמר ר' יוחנן: שנים שנתעצמו בדין, אחד אומר: נדון כאן, ואחד אומר: נלך למקום הוועד\u0004 — \u0003כופין אותו ודן בעירו, ואם הוצרך דבר\u0004 לדיינים \u0003לשאול\u0004 מבית דין הגדול \u0003כותבין\u0004 לוועד \u0003ושולחין.\u0004","\u0003ואם אמר\u0004 אחד הצדדים: אני איני סומך על בית דין זה, ולכן \u0003כתבו ותנו לי מאיזה טעם דנתוני,\u0004 שאין אני סומך על החלטתכם בלא נימוק וראיה — \u0003כותבין ונותנין לו.\u0004","ועוד שנינו לענין קביעת מקום הדין: \u0003והיבמה הולכת אחר היבם להתירה,\u0004 ואין כופים את היבם שילך הוא אליה.","ושואלים: \u0003עד כמה\u0004 תלך? ומשיבים, \u0003אמר ר' אמי: אפילו מטבריא לצפורי,\u0004 גם אם בית הדין בטבריא חשוב מזה של ציפורי.","\u0003אמר רב כהנא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך? — \u0003\"וקראו לו זקני עירו\u0004 ודברו אליו ועמד ואמר לא חפצתי לקחתה\u0003\"\u0004 (דברים כה, ח), זקני עירו \u0003ולא זקני עירה,\u0004 משמע שבו תלוי הדבר ולא בה.","\u0003אמר אמימר: הילכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 אם לא הסכימו המתדיינים ביחס למקום הדין, \u0003כופין אותו וילך למקום הוועד. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר: כופין אותו ודן בעירו!\u0004 והשיב: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שדן בעירו הם דווקא \u0003היכא דקאמר ליה\u0004 \u0005[במקום שאומר לו]\u0006 ה\u0003לוה למלוה:\u0004 הבה נלך למקום אחר, שאז יכול המלוה לכפות את הלווה להתדיין במקומו, \u0003אבל\u0004 אם אמר ה\u0003מלוה\u0004 ללכת למקומו שומעים לו, כאמור \u0003\"\u0004ו\u0003עבד לוה לאיש מלוה\"\u0004 (משלי כב, ז).","ובענין זה \u0003שלחו ליה\u0004 \u0005[לו]\u0006 מכתב \u0003למר עוקבא\u0004 ראש הגולה שבבבל. וכך היה כתוב בו: \u0003\"לדזיו ליה כבר בתיה, שלם\u0004 \u0005[ל\u0006זה \u0005שאור לו\u0006 כמשה המכונה \u0005בנה של בתיה, שלום]!\u0006 \u0003עוקבן הבבלי קבל קדמנא\u0004 \u0005[לפנינו]\u0006 \u0003ירמיה אחי העביר עלי את הדרך,\u0004 עשה לי עול גדול, \u0003ואמרו לו, השיאוהו\u0004 תגרמו לו \u0003ויראה פנינו בטבריא\u0004 ושם נדון בעניינו \u0003\".\u0004 ותוהים: \u0003הא גופא קשיא\u0004 \u0005[זה גופו\u0006 המכתב \u0005קשה\u0006 להבינו\u0005]:\u0006 \u0003אמרת \"אמרו לו\", אלמא\u0004 \u0005[מכאן]\u0006 שהכוונה היא: \u0003דיינוה אתון\u0004 \u0005[דונו אותו אתם]\u0006 בבבל. ונאמר אחר כך \u0003\"השיאוהו ויראה פנינו בטבריא\", אלמא\u0004 \u0005[מכאן]\u0006 שהכוונה היתה: \u0003שדרוהו הכא\u0004 \u0005[שלחו אותו לכאן]!\u0006","","\u0003אלא הכי קאמרי\u0004 \u0005[כך אמרנו]:\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003דיינו אתון\u0004 \u0005[ודונו\u0006 בו \u0005אתם],\u0006 \u0003אי ציית\u0004 \u0005[אם ישמע]\u0006 לבית דין — \u0003ציית\u0004 \u0005[ישמע],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003השיאוהו ויראה פנינו בטבריא.\u0004","\u0003רב אשי אמר:\u0004 לא כך יש להבין אלא דין זה ב\u0003דיני קנסות הוה\u0004 \u0005[היה],\u0006 \u0003ובבבל לא דיינו\u0004 \u0005[אין דנים]\u0006 \u0003דיני קנסות\u0004 שאין בה חכמים סמוכים, והם מצויים רק בארץ ישראל, ולכן צריכים לשלוח את הדין לארץ. \u0003והא\u0004 \u0005[וזה]\u0006 ש\u0003שלחו ליה הכי\u0004 \u0005[לו כך]\u0006 בלשון עצה ובקשה הרי זה \u0003כדי לחלוק כבוד למר עוקבא\u0004",""],["\u0003אחד דיני ממונות ואחד דיני נפשות בדרישה ובחקירה\u0004 של העדים, \u0003שנאמר: \"משפט אחד יהיה לכם\"\u0004 (ויקרא כד, כב), לאמור: כל הליכי המשפט צריכים להיות אחידים.","\u0003מה\u0004 ההבדל \u0003בין דיני ממונות לדיני נפשות? דיני ממונות\u0004 — דנים \u0003בשלשה\u0004 דיינים, \u0003ודיני נפשות\u0004 — \u0003בעשרים ושלשה. דיני ממונות\u0004 — \u0003פותחין\u0004 בדיון \u0003בין\u0004 בנימוק \u0003לזכות\u0004 הנאשם, \u0003בין\u0004 בטענה \u0003לחובה, ודיני נפשות\u0004 — \u0003פותחין\u0004 באלה שיש להם לומר \u0003לזכות, ואין פותחין לחובה.\u0004","ועוד, \u0003דיני ממונות\u0004 — \u0003מטין\u0004 (מכריעים, פוסקים) \u0003על פי\u0004 דיין \u0003אחד בין לזכות בין לחובה, ודיני נפשות\u0004 — \u0003מטין על פי\u0004 דיין \u0003אחד לזכות ו\u0004רק \u0003על פי שנים לחובה.\u0004","\u0003דיני ממונות\u0004 — אם סבורים הדיינים שטעו \u0003מחזירין\u0004 את הדין \u0003בין לזכות בין לחובה,\u0004 ואילו ב\u0003דיני נפשות\u0004 — \u0003מחזירין\u0004 את הדין \u0003לזכות ואין מחזירין לחובה,\u0004 גם אם סבורים הדיינים שטעו בהכרעתם הראשונה וזיכו.","\u0003דיני ממונות\u0004 — \u0003הכל,\u0004 לא רק דיינים אלא גם תלמידי חכמים אחרים המצויים במקום, \u0003מלמדין זכות וחובה, דיני נפשות\u0004 — \u0003הכל מלמדין זכות, ואין הכל מלמדין חובה,\u0004 אלא הדיינים בלבד.","ועוד, \u0003דיני ממונות\u0004 — מי שהיה \u0003מלמד חובה\u0004 בתחילת הדיון \u0003מלמד\u0004 עכשיו \u0003זכות\u0004 אם חזר בו, \u0003והמלמד זכות\u0004 מתחילה \u0003מלמד\u0004 אחר כך \u0003חובה,\u0004 ואילו ב\u0003דיני נפשות\u0004 אינו כן, אלא \u0003המלמד חובה\u0004 יכול לחזור בו ו\u0003מלמד זכות, אבל המלמד זכות אין יכול לחזור וללמד חובה.\u0004","ועוד, \u0003דיני ממונות\u0004 — \u0003דנין ב\u0004שעות ה\u0003יום, ו\u0004אולם \u0003גומרין\u0004 את פסק הדין אפילו \u0003בלילה,\u0004 וב\u0003דיני נפשות\u0004 — \u0003דנין ביום וגומרין ביום\u0004 בלבד.","\u0003דיני ממונות\u0004 — \u0003גומרין בו ביום\u0004 אם הספיקו לחקור העדים ולהגיע למסקנה, \u0003בין לזכות בין לחובה, דיני נפשות\u0004 — \u0003גומרין\u0004 את הדין \u0003בו ביום\u0004 אם פסקו \u0003לזכות,\u0004 אבל ממתינים ל\u0003יום שלאחריו\u0004 להחליט \u0003לחובה. לפיכך\u0004 משום שדיני נפשות עשויים להימשך יומיים, \u0003אין דנין\u0004 דיני נפשות \u0003לא בערב שבת ולא בערב יום טוב,\u0004 שכן אם יחליטו לחייב יצטרכו לחכות עד למחר כדי לגמור את הדין, ואסור לבצע פסק דין מוות בשבת ובחג.","ועוד הבדל, ב\u0003דיני ממונות\u0004 וכן בדיני \u0003הטמאות והטהרות\u0004 — \u0003מתחילין\u0004 במשא ומתן \u0003מן הגדול\u0004 שבדיינים. \u0003דיני נפשות\u0004 — \u0003מתחילין מן הצד,\u0004 כלומר, מן הקטן שבהם, שהוא יחווה דעתו תחילה.","\u0003הכל כשרין לדון דיני ממונות, ואין הכל כשרין לדון דיני נפשות, אלא כהנים לוים וישראלים\u0004 מיוחסים, שהם ראויים להיות \u0003משיאין\u0004 בנותיהם \u0003לכהונה.\u0004","שנינו במשנה שדיני ממונות בדרישה וחקירה. ותוהים: \u0003דיני ממונות מי בעינן\u0004 \u0005[האם צריכים אנו\u0006 בהם\u0005]\u0006 \u0003דרישה וחקירה? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בתוספתא: \u0003שטר שזמנו כתוב באחד בניסן ב\u0004שנת ה\u0003שמיטה, ובאו עדים ואמרו\u0004 לעדים החתומים על השטר: \u0003היאך אתם מעידים על שטר זה? והלא ביום פלוני\u0004 שנכתב בו השטר \u0003עמנו הייתם במקום פלוני,\u0004 וכיצד יכולתם באותו זמן לחתום על שטר זה? — הרי זה \u0003שטר כשר\u0004 וגובים בו \u0003ועדיו כשרין,\u0004 ואין חושדים שזייפו. ומסבירים: \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא איחרוהו וכתבוהו,\u0004 כלומר, ההלוואה עצמה נעשתה בזמן מוקדם יותר, ובשטר לא כתבו את תאריך ההלוואה אלא תאריך מאוחר יותר.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003דרישה וחקירה\u0004 אף בדיני ממונות, \u0003היכי חיישינן\u0004 \u0005[כיצד חוששין אנו]\u0006 \u0003שמא איחרוהו וכתבוהו?\u0004 הרי לנו מקרה שאין אנו שמים לב לדרישה ולחקירה בדיני ממונות, ומכשירים למרות שהוזמה לכאורה העדות!","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מביא ראיה מכגון זה, \u0003תיקשי\u0004 \u0005[יהיה קשה]\u0006 \u0003לך מתניתין\u0004 \u0005[\u0006מ\u0005משנה]\u0006 ולא רק מן התוספתא, שהרי משנה מפורשת היא: \u0003שטרי חוב המוקדמין\u0004 שתאריכם מוקדם מהתאריך שבו היתה ההלוואה — \u0003פסולים, והמאוחרים\u0004 — \u0003כשרין. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003דרישה וחקירה\u0004 בדיני ממונות, ואם יש סתירה מבטלים את הדין, \u0003מאוחרין אמאי\u0004 \u0005[מדוע]\u0006 \u0003כשרין?\u0004","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[\u0006שאלה \u0005זו אינה קשה],\u0006 ויש טעם מפני מה לא הקשינו מן המשנה אלא מן התוספתא, כי \u0003דעדיפא מינה קאמרינן\u0004 \u0005[\u0006דבר \u0005עדיף\u0006 וקשה \u0005ממנו אמרנו],\u0006 שכן המקור שהקשינו ממנו יש בו חידוש מיוחד, ש\u0003אפילו\u0004 שטר הכתוב ב\u0003אחד בניסן ב\u0004שנת ה\u0003שמיטה, דלא שכיחי אינשי דמוזפי\u0004 \u0005[שאין מצויים אנשים המלווים\u0006 אז\u0005],\u0006 שהרי בסוף שנת השמיטה ישמטו ויבטלו כל החובות, \u0003דליכא למימר\u0004 \u0005[שאין לומר],\u0006 כלומר, שאינו מסתבר כל כך לומר \u0003שמא איחרוהו וכתבוהו, דלא מרע לשטריה\u0004 \u0005[שאין\u0006 אדם \u0005מקלקל את שטרו]\u0006 ומאחרו לכתבו בתאריך היכול לבוא לידי שמיטה — \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003כיון\u0004 ש\u0003שביעית\u0004 רק \u0003סופה משמטת\u0004 ובתאריך זה עדיין השטר כשר, משערים אנו שהוא שטר מאוחר ו\u0003מכשרינן\u0004 \u0005[מכשירים אנו]\u0006 אותו, ואם כן יפה עשו שהקשו ממקור זה.","אבל \u0003מכל מקום\u0004 לגופה של הסתירה \u0003קשיא\u0004 \u0005[קשה].\u0006 לסתירה זו נתנו חכמים שונים תשובות אחדות (ו\u0003סימן חרפ\"ש\u0004 לשמות החכמים הדנים בדבר — ר' \u0003ח\u0004נינא, \u0003ר\u0004בא, רב \u0003פ\u0004פא, רב א\u0003ש\u0004י).","\u0003אמר ר' חנינא: דבר תורה,\u0004 מעיקר דין התורה, \u0003אחד דיני ממונות ואחד דיני נפשות\u0004 נעשים \u0003בדרישה ובחקירה, שנאמר: \"משפט אחד יהיה לכם\". ומה טעם אמרו\u0004 כי ב\u0003דיני ממונות לא בעינן\u0004 \u0005[איננו צריכים]\u0006 \u0003דרישה וחקירה?\u0004 — תקנת חכמים היא \u0003כדי שלא תנעול דלת בפני לוין,\u0004 שאם יבדקו כל עסקי ממונות בדרישה וחקירה קל יהא למצוא סתירה כלשהי בעדות, ולא יוכלו המלווים לגבות ממונם, ולכן לא ירצו להלוות.","ושואלים: אם כן, \u0003אלא מעתה\u0004 שפישטו והקלו חכמים בדיני ממונות"],["אם \u0003טעו\u0004 הדיינים \u0003לא ישלמו,\u0004 שכן לא הניחום לחקור ולדרוש היטב! ומשיבים: \u0003כל שכן שתנעול דלת בפני לווין\u0004 אם ידעו המלווים שבית הדין אינו אחראי עבור טעות שעשה בדינם.","\u0003רבא אמר: מתניתין דהכא\u0004 \u0005[משנתנו כאן]\u0006 האומרת שדיני ממונות בדרישה וחקירה, מדברת \u0003בדיני קנסות\u0004 שאינם מעסקי ממון רגילים, \u0003ואידך\u0004 \u0005[והאחרות]\u0006 שאינן מחייבות דרישה וחקירה מדברות \u0003בהודאות והלואות\u0004 בלבד, שבהן יש לדאוג להקלת סדרי הדיון.","\u0003רב פפא אמר: אידי ואידי\u0004 \u0005[זו וזו],\u0006 גם משנתנו וגם האחרות, מדברות \u0003בהודאה והלואה,\u0004 אלא יש לחלק ולומר כי \u0003כאן\u0004 ששנינו שצריך דרישה וחקירה — מדובר \u0003בדין מרומה,\u0004 כשהדיין סבור שצד מסויים מנסה לרמות ולהביא עדות שקר, \u0003כאן\u0004 ששנינו שאין צריך דרישה וחקירה — \u0003בדין שאינו מרומה, \u0004","\u0003כד\u0004ברי \u0003ריש לקיש.\u0004 ש\u0003ריש לקיש רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין שני מקראות: \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד \u0003\"בצדק תשפט עמיתך\"\u0004 (ויקרא יט, טו), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בכתוב אחר \u0003\"צדק צדק תרדף\"\u0004 (דברים טז, כ), משמע שלא די בשיפוט בצדק בלבד אלא יש צורך ברדיפה וחיפוש אחר הצדק. \u0003הא כיצד\u0004 ניישב את הדברים? — \u0003כאן בדין מרומה\u0004 צריך לחפש ולרדוף, ו\u0003כאן בדין שאין מרומה\u0004 אפשר להכריע לפי הנראה.","\u0003רב אשי אמר: מתניתין כדשנין\u0004 \u0005[משנתנו כפי שתרצנו]\u0006 את הסתירה בכמה אופנים. ואילו \u0003קראי\u0004 \u0005[הפסוקים]\u0006 לא לענין זה נאמרו, אלא \u0003אחד לדין\u0004 — צריך להיות בו \"צדק צדק תרדוף\" בחיפוש וחקירה, \u0003ואחד לפשרה\u0004 — \"בצדק תשפוט עמיתך\".","כ\u0003דתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"צדק צדק תרדף\"\u0004 — \u0003אחד לדין ואחד לפשרה. כיצד?\u0004 — \u0003שתי ספינות עוברות בנהר ופגעו\u0004 (פגשו) \u0003זה בזה, אם עוברות שתיהן\u0004 — \u0003שתיהן טובעות,\u0004 שאין הנהר רחב דיו לשתיהן, אם עוברות \u0003בזה אחר זה\u0004 — \u0003שתיהן עוברות. וכן שני גמלים שהיו עולים במעלות בית חורון,\u0004 שיש שם דרך צרה ותלולה, \u0003ופגעו זה בזה, אם עלו שניהן\u0004 יחד — \u0003שניהן נופלין,\u0004 אם עלו \u0003בזה אחר זה\u0004 — \u0003שניהן עולין.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 נעשה להכריע ביניהם? אניה \u0003טעונה ושאינה טעונה\u0004 — \u0003תידחה שאינה טעונה מפני טעונה.\u0004 אניה \u0003קרובה\u0004 (למטרתה) \u0003ושאינה קרובה\u0004 — \u0003תידחה קרובה מפני שאינה קרובה. היו שתיהן קרובות, שתיהן רחוקות\u0004 — \u0003הטל פשרה ביניהן, ומעלות שכר זו לזו,\u0004 שאם יש הפסד מסויים לאניה המאחרת יפצו בעלי האניה המקדימה את הממתינים.","פסוק זה נדרש גם באופן אחר, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הנאמר \u0003\"צדק צדק תרדף\"\u0004 — \u0003הלך אחר בית דין יפה\u0004 וחשוב שבדור, \u0003אחר ר' אליעזר ללוד, אחר רבן יוחנן בן זכאי לברור חיל.\u0004","אגב הזכרת עיר זו, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 בזמן הגזירה, כשאסרו על קיום מצוות התורה, הסכימו ביניהם על סימנים מיוחדים, על פיהם יידעו על אירועים מסויימים. וביניהם: אם שומעים \u0003קול ריחים ב\u0004מקום \u0003בורני\u0004 — הרי זה סימן שבשבוע זה יש ברית מילה וכאילו הכריזו: \u0003\"שבוע הבן\"! \"שבוע הבן\"!\u0004 אם מדליקים \u0003אור הנר בברור חיל\u0004 — הרי זה סימן לחתונה וכאילו הכריזו: \u0003\"משתה\u0004 (חתונה) \u0003שם\"! \"משתה שם\"!\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הנאמר \u0003\"צדק צדק תרדף\"\u0004 — \u0003הלך אחר חכמים לישיבה\u0004 שבה הם מצויים: \u0003אחר ר' אליעזר ללוד, אחר רבן יוחנן בן זכאי לברור חיל, אחר ר' יהושע לפקיעין, אחר רבן גמליאל ליבנא, אחר ר' עקיבא לבני ברק, אחר ר' מתיא לרומי, אחר ר' חנניה בן תרדיון לסיכני, אחר ר' יוסי לציפורי, אחר ר' יהודה בן בתירה לנציבין, אחר ר' יהושע לגולה\u0004 (בבל), \u0003אחר רבי לבית שערים, אחר חכמים\u0004 בזמן הבית \u0003ללשכת הגזית.\u0004","שנינו במשנה שב\u0003דיני ממונות פותחין\u0004 בין לזכות בין לחובה, ובדיני נפשות פותחים רק לזכות. ושואלים: \u0003היכי אמרינן\u0004 \u0005[כיצד אומרים],\u0006 כלומר, מה היא הנוסחה בה פותחים את הדיון שיהא תמיד לזכות? \u0003אמר רב יהודה, הכי אמרינן להו\u0004 \u0005[כך אומרים אנו להם,\u0006 לעדים\u0005]:\u0006 \u0003מי יימר כדקאמריתו\u0004 \u0005[מי אומר\u0006 שזה \u0005כפי שאמרתם]?\u0006 שמא טועים אתם?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003עולא: והא חסמינן להו\u0004 \u0005[והרי\u0006 גורמים \u0005אנו לחסום אותם,\u0006 את דבריהם\u0005]\u0006 על ידי שאנו אומרים שאנו חושדים אותם בשקר או טעות. השיב לו: אין חוששים לכך, \u0003וליחסמו\u0004 \u0005[ושיחסמו],\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אליעזר אומר: מסיעין את העדים\u0004 בדיני נפשות \u0003ממקום למקום כדי שתיטרף דעתן\u0004 ויתבלבלו \u0003ויחזרו בהן.\u0004","ודוחים: \u0003מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 ששנינו שמסיעים אותם הרי \u0003ממילא קא מידחו\u0004 \u0005[מעצמם הם נדחים]\u0006 שלבסוף הם עצמם מודים, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003קא דחינן להו\u0004 \u0005[דוחים אנו אותם]\u0006 \u0003בידים,\u0004 ודבר זה אין עושים.","\u0003אלא אמר עולא: הכי אמרינן\u0004 \u0005[כך אומרים אנו לו\u0006 לנאשם\u0005]:\u0006 האם \u0003יש לך עדים להזימם\u0004 לעדים שהעידו כנגדך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: וכי פותחין בזכותו של זה\u0004 (הנאשם) \u0003שהיא חובתו של זה\u0004 (העד)? שהרי על ידי כך גורמים אנו חובה לעדים, שאם יביא עדים ויזימום — ייהרגו העדים!","ותוהים: \u0003ומי הויא\u0004 \u0005[והאם היא]\u0006 \u0003חובתו\u0004 של העד בכך? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין עדים זוממין נהרגין עד שיגמר הדין\u0004 לחובה, אבל הוזמו קודם לכן — אינם נהרגים!","ומשיבים: \u0003הכי אמינא\u0004 \u0005[כך אומר אני]:\u0006 \u0003אילו שתיק האי\u0004 \u0005[אם ישתוק זה,\u0006 הנאשם\u0005]\u0006 \u0003עד דמיגמר דיניה ומייתי\u0004 \u0005[שייגמר דינו ו\u0006אז \u0005יביא]\u0006 \u0003עדים ומזים להו\u0004 \u0005[ויזים אותם]\u0006 ויחוייבו העדים שכנגדו מיתה, ואם כן \u0003הויא ליה\u0004 \u0005[תהיה זו]\u0006 ההצעה שהציע בית הדין \u0003חובתו של זה\u0004 (העד)! \u0003אלא אמר רבה, אמרינן ליה\u0004 \u0005[אומרים אנו לו\u0006 לנאשם\u0005]:\u0006 \u0003יש לך עדים להכחישן?\u0004 שעל ידי הכחשה אין מחייב את המעידים בראשונה בעונש.","\u0003רב כהנא אמר,\u0004 אומרים לעדים: \u0003מדבריכם נזדכה פלוני,\u0004 כלומר, בדבריכם אפשר למצוא צד זכות לנאשם, ואז מתחילים לדון בדבר. \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם],\u0006 \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו\u0006 לנאשם\u0005]:\u0006 \u0003אם לא קטלת\u0004 \u0005[הרגת]\u0006 \u0003לא תדחל\u0004 \u0005[תירא].\u0006 \u0003רב אשי אמר,\u0004 כך אומרים: \u0003כל מי שיודע לו זכות, יבא וילמד עליו.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתם]\u0006 של \u0003אביי ורבא. רבי אומר,\u0004 אומרים לסוטה: \u0003\"אם לא שכב איש אתך ואם לא שטית\u0004 טומאה תחת אישך הנקי ממי המרים המאררים האלה\u0003\"\u0004 (במדבר ה, יט),"],["\u0003מיכן\u0004 (מכאן) \u0003שפותחין בדיני נפשות תחלה לזכות,\u0004 ולענייננו למדנו שפתיחה לזכות פירושה שאומרים לנאשם: אם לא חטאת אין לך לחשוש.","שנינו במשנה כי ב\u0003דיני ממונות מחזירין\u0004 את הדין בין לזכות בין לחובה. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במקור אחר: \u0003דן\u0004 הדיין \u0003את הדין,\u0004 וטעה ו\u0003זיכה את החייב\u0004 או \u0003חייב את הזכאי, טימא את הטהור, טיהר את הטמא\u0004 — \u0003מה שעשה עשוי, וישלם מביתו\u0004 למי שניזוק בגלל טעות זו. משמע שאין מחזירים את הדין, ומי שזכה — זכה, אלא שהדיין חייב לפצות את זה שנתחייב שלא כדין!","\u0003אמר רב יוסף: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאמרנו שמחזירים את הדין הרי זה \u0003ב\u0004אופן שהדיין היה \u0003מומחה,\u0004 ודיין כזה יש בכוחו להחזיר את הדין, ואילו \u0003כאן\u0004 ששנינו שמה שעשה עשוי — \u0003בשאינו מומחה.\u0004 ותוהים: \u0003ובמומחה מחזירין? והקתני\u0004 \u0005[והרי שנינו]:\u0006 \u0003אם היה מומחה לבית דין\u0004 — \u0003פטור מלשלם,\u0004 משמע שאין מחזירים אם כי הדיין פטור מלשלם!","\u0003אמר רב נחמן\u0004 הסבר אחר: \u0003כאן\u0004 ששנינו שמחזירים את הדין הרי זה באופן \u0003שיש גדול הימנו\u0004 (ממנו) \u0003בחכמה ובמנין\u0004 התלמידים, \u0003כאן\u0004 ששנינו שאין מחזירים הרי זה באופן \u0003שאין גדול הימנו בחכמה ובמנין,\u0004 והרי הוא המומחה, ואם טעה אין תקנה לדבר.","\u0003רב ששת אמר,\u0004 יש להסביר בדרך אחרת: \u0003כאן\u0004 ששנינו שמחזירים, הרי זה באופן \u0003שטעה\u0004 הדיין \u0003בדבר משנה\u0004 שאז בטל הדין מעיקרו, \u0003כאן\u0004 ששנינו שאין מחזירים, הרי זה באופן \u0003שטעה\u0004 הדיין \u0003בשיקול הדעת.\u0004 ש\u0003אמר רב ששת אמר רב אסי:\u0004 דיין ש\u0003טעה בדבר משנה\u0004 שהיא טעות גמורה, שמוכח לכל שטעות היא — הרי זה \u0003חוזר, טעה בשיקול הדעת\u0004 ולא הכריע כהוגן במחלוקת חכמים — \u0003אינו חוזר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 מה פירוש \"טעה בדבר משנה\"? האם בכלל זה \u0003אפילו טעה ב\u0004דברי \u0003ר' חייא ור' אושעיא\u0004 שהיו מאחרוני התנאים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אין\u0004 \u0005[כן].\u0006 אמר לו רבינא: \u0003אפילו\u0004 טעה \u0003ב\u0004דברי האמוראים \u0003רב ושמואל? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 חזר ושאל: \u0003אפילו בדידי ודידך\u0004 \u0005[ב\u0006דברי \u0005שלי ו\u0006דבריך \u0005שלך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אטו אנן קטלי קני באגמא אנן\u0004 \u0005[וכי אנו קוצצי קנים באגם אנחנו],\u0006 כלומר, הלא גם אנחנו חכמים, וגם הכרעתנו בעלת משקל.","ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד היא בדיוק]\u0006 טעות ב\u0003שיקול הדעת? אמר רב פפא: כגון תרי תנאי\u0004 \u0005[שני תנאים]\u0006 \u0003או תרי אמוראי דפליגי אהדדי\u0004 \u0005[שני אמוראים שחלוקים זה על זה],\u0006 \u0003ולא איתמר הלכתא\u0004 \u0005[נאמרה הלכה]\u0006 \u0003לא כמר\u0004 \u0005[כ\u0006חכם \u0005זה]\u0006 \u0003ולא כמר\u0004 \u0005[כ\u0006חכם \u0005זה],\u0006 \u0003ואיקרי ועבד כחד מינייהו\u0004 \u0005[והזדמן שעשה כאחד מהם],\u0006 \u0003וסוגיא דשמעתא אזלי כאידך\u0004 \u0005[ומהלך ההלכה נוהג כאחר],\u0006 כלומר, אם מעיינים בהכרעות המקובלות על רוב הדיינים, רואים שרובם מחזיקים בשיטה אחרת — \u0003היינו\u0004 \u0005[זוהי]\u0006 טעות ב\u0003שיקול הדעת.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב המנונא לרב ששת\u0004 ממה ששנינו: \u0003מעשה בפרה של בית מנחם שניטלה האם\u0004 (בית הרחם) \u0003שלה, והאכילה ר' טרפון לכלבים\u0004 משום שפסק שהיא טריפה,","\u0003ובא מעשה\u0004 זה \u0003לפני חכמים ביבנה והתירוה. שאמר תודוס הרופא: אין פרה וחזירה יוצאת מאלכסנדריא של מצרים אלא אם כן חותכין האם שלה, כדי שלא תלד,\u0004 שהיה להם זן משובח של בעלי חיים ורצו שלא יולידו כמותם במקומות אחרים. משמע שנטילת האם אינה מסכנת את חיי הבהמה, ואינה טריפה. \u0003אמר ר' טרפון\u0004 כששמע זאת: \u0003הלכה חמורך טרפון!\u0004 כלומר, הרי הפסיד ממונו, שהרי יצטרך למכור את חמורו כדי שיוכל לשלם את דמי הפרה שהטריף. \u0003אמר לו ר' עקיבא: פטור אתה, שכל המומחה לרבים\u0004 וטעה \u0003פטור מלשלם.\u0004","\u0003ואי איתא\u0004 \u0005[אם יש\u0006 מקום\u0005]\u0006 למה שאמרת שטועה בדבר משנה פטור, \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 ר' עקיבא: \u0003טועה בדבר משנה אתה, וטועה בדבר משנה\u0004 — \u0003חוזר.\u0004","ומשיבים: נימוק \u0003חדא\u0004 \u0005[אחד]\u0006 \u0003ועוד\u0004 אחד \u0003קאמר\u0004 \u0005[אמר],\u0006 שהיו לו שתי סיבות: \u0003חדא\u0004 \u0005[אחת]\u0006 ש\u0003טועה בדבר משנה אתה, וטועה בדבר משנה\u0004 — \u0003חוזר. ועוד, אי נמי\u0004 \u0005[אם גם כן]\u0006 \u0003בשיקול הדעת טעית\u0004 — הלא \u0003מומחה לרבים אתה וכל המומחה לרבים\u0004 — \u0003פטור מלשלם.\u0004","\u0003אמר רב נחמן בר יצחק לרבא: מאי קא מותיב\u0004 \u0005[מה\u0006 בעצם \u0005מקשה]\u0006 \u0003רב המנונא לרב ששת\u0004 \u0003מ\u0004מעשה שהיה ב\u0003פרה? פרה\u0004 זו \u0003הרי\u0004 כבר \u0003האכילה לכלבים וליתא דתהדר\u0004 \u0005[ואיננה\u0006 שאפשר \u0005שתוחזר]\u0006 ומה מקום לשאלה אם הדין חוזר או לא?","הסביר לו: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי דיין ש\u0003טעה בדבר משנה אינו חוזר\u0004 — \u0003אלמא קם דינא\u0004 \u0005[מכאן שהדין\u0006 נשאר \u0005עומד]\u0006 במקומו, \u0003היינו דקא מפחיד\u0004 \u0005[זהו שפחד]\u0006 \u0003ר' טרפון\u0004 שיצטרך לשלם. \u0003וקאמר ליה איהו\u0004 \u0005[יאמר לו הוא,\u0006 ר' עקיבא\u0005]\u0006 ש\u0003מומחה לבית דין אתה ואתה פטור מלשלם. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003טעה בדבר משנה חוזר, לימא ליה\u0004 \u0005[שיאמר לו]:\u0006 \u0003כיון\u0004 ש\u0003אילו\u0004 עדיין \u0003הואי\u0004 \u0005[היתה]\u0006 ה\u0003פרה\u0004 קיימת \u0003דינך לאו דינא\u0004 \u0005[לא\u0006 היה \u0005דין]\u0006 \u0003ולא כלום עבדת\u0004 \u0005[עשית]\u0006 \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 \u0003לא כלום עבדת\u0004 \u0005[עשית]\u0006 ואין אתה צריך לשלם.","\u0003רב חסדא אמר\u0004 שיש להסביר את הסתירה בין המשניות כך: \u0003כאן שנטל\u0004 הדיין עצמו מאיש אחד \u0003ונתן ביד\u0004 השני שלא כדין — אין הדין חוזר, וישלם. \u0003כאן שלא נטל ונתן ביד,\u0004 אלא פסק הלכה והצדדים עשו מעצמם מעשה -- חוזר הדין.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 כאשר \u0003חייב את הזכאי\u0004 יש מקום לומר \u0003כגון שנטל ונתן ביד\u0004 מן הזכאי ונתן לאחר שאינו זכאי, \u0003אלא\u0004 אם \u0003זיכה את החייב היכי משכחת לה\u0004 \u0005[איך\u0006 יכול \u0005אתה למצוא\u0006 מקרה \u0005כזה]\u0006 שהרי מה עושה אז הדיין, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 לנתבע \u0003\"פטור אתה\u0004 מלשלם \u0003\",\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא נטל ונתן\u0004 \u0003ביד\u0004 כלל על ידי כך, שהרי רק פסק הלכה! ומשיבים: \u0003כיון\u0004 ש\u0003אמר \"פטור\u0004 \u0003אתה\"\u0004 — \u0003כמו שנטל ונתן ביד דמי\u0004 \u0005[נחשב],\u0006 שאין צורך בכל מעשה נוסף.","ושואלים: \u0003אלא מתניתין דקתני \u0004 \u0005[משנתנו ששנינו בה]\u0006 שב\u0003דיני ממונות מחזירין בין לזכות בין לחובה, בשלמא\u0004 \u0005[נניח]\u0006 \u0003לזכות\u0004 — \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות, כיצד? ש\u0003אמר ליה\u0004 \u0003מעיקרא\u0004 \u0005[לו מתחילה]\u0006 לצד אחד: \u0003\"חייב אתה\u0004 לשלם \u0003\"\u0004\u0003ולא נטל ולא נתן ביד,\u0004 שבמקרה זה אמר רב חסדא שמחזירים את הדין, \u0003אלא\u0004 שמחזירים \u0003לחובה\u0004 \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה\u0006 אפשרות\u0005]?\u0006 — ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 לנתבע: \"\u0003פטור אתה\"? והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 כי \u0003כיון\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"פטור אתה\"\u0004 הרי \u0003כמו שנטל ונתן ביד דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005],\u0006 ואם כן אין אפשרות שיחזירו דיני ממונות לחובה!","ומשיבים: יש להבין את המשנה באופן ש\u0003חדא קתני\u0004 \u0005[\u0006דבר \u0005אחד שנינו]\u0006 ולא שני דינים נפרדים, וכך יש להבין: כיצד \u0003דיני ממונות מחזירין לזכות\u0004 של צד אחד \u0003שהיא חובה\u0004 לצד אחר, אולם \u0003דכוותה\u0004 \u0005[בכיוצא בה]\u0006 \u0003גבי\u0004 דיני \u0003נפשות מחזירין לזכות\u0004 בלבד,"],["\u0003ואין מחזירין לחובה\u0004 — \u0003מחזירין לזכות\u0004 כוונתו: \u0003זכות גרידתא\u0004 \u0005[בלבד],\u0006 שאין בכך צד חובה לאחר, \u0003ואין מחזירין לחובה,\u0004 כלומר, אף \u0003לזכות שהיא חובה.\u0004","ותוהים: בדיני נפשות את \u0003חובתיה דמאן\u0004 \u0005[חובתו של מי]\u0006 גורמים כאשר מזכים בדיני נפשות? ומשיבים: \u0003הא לא קשיא\u0004 \u0005[\u0006דבר \u0005זה אינו קשה]\u0006 שכן בכך גורמים את \u0003חובתיה\u0004 \u0005[חובתו]\u0006 של \u0003גואל הדם,\u0004 שהרי הוא חפץ שיענישו את הרוצח. ותוהים על תירוץ זה: \u0003משום\u0004 שיש בכך \u0003חובתיה\u0004 \u0005[חובתו]\u0006 וחוסר רצונו של \u0003גואל הדם קטלינן ליה להאי\u0004 \u0005[הורגים אנו את זה]\u0006 ואין מחזירים לזכותו כשיש טעם בדבר? \u0003ועוד, מאי\u0004 \u0005[מה]\u0006 לשון \u0003\"בין\" \"בין\"\u0004 האמורה במשנה פעמיים? ומשיבים: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005]:\u0006","\u0003רבינא אמר:\u0004 אפשר ליישב את שיטת רב חסדא \u0003כגון שהיה לו בידו\u0004 לתובע \u0003משכון ו\u0004כאשר זיכה את הנתבע \u0003נטלו ממנו\u0004 הדיין למשכון, ונמצא איפוא שנטל ביד ממש.","\u0003טימא את הטהור\u0004 במעשה בידים כיצד? — \u0003דאגעי ביה\u0004 \u0005[שנגע בו]\u0006 ב\u0003שרץ\u0004 וטימאו בידים טומאה גמורה. \u0003טיהר את הטמא\u0004 כיצד הוא — \u0003שעירבן\u0004 את פירותיו הטמאים \u0003בין פירותיו\u0004 הטהורים.","שנינו במשנה שב\u0003דיני נפשות\u0004 אין מחזירים לחובה אלא לזכות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003מניין ליוצא מבית דין\u0004 כשהוא על פי פסק דינם \u0003חייב,\u0004 \u0003ואמר אחד: יש לי ללמד עליו זכות, מניין שמחזירין אותו\u0004 לבית הדין לדיון מחודש בדינו? \u0003—\u0004 \u0003תלמוד לומר: \"נקי אל תהרג\",\u0004 שהוא חלק מדברי הכתוב \"ונקי וצדיק אל תהרוג\" (שמות כג, ז), ומשם נלמד שאם יש מקום לומר שנקי הוא מעוון — אין להורגו.","\u0003ומניין ליוצא מבית דין\u0004 כשהוא על פי פסק דינם \u0003זכאי, ואמר אחד:\u0004 \u0003יש לי ללמד עליו חובה, מניין שאין מחזירין אותו\u0004 לבית הדין לדיון מחודש — \u0003תלמוד לומר: \"צדיק אל תהרג\",\u0004 כלומר, מי שיצא צדיק בדינו, אף על פי שאינו נקי — אין הורגים אותו.","\u0003אמר רב שימי בר אשי: וחילופא\u0004 \u0005[וחילוף\u0006 הדברים, ההיפך\u0005]\u0006 עושים בדיני ה\u0003מסית,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005];\u0006 \u0003\"ולא תחמל ולא תכסה עליו\"\u0004 (דברים יג, ט). \u0003רב כהנא מתני\u0004 \u0005[היה שונה]\u0006 רעיון זה בהסתמך על כתוב אחר שנאמר במסית \u0003\"כי הרג תהרגנו\"\u0004 (דברים יג, י).","\u0003בעא מניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' זירא מרב ששת: חייבי גליות מניין\u0004 שדינם לענין חזרה כחייבי מיתה? והשיב: \u0003אתיא\u0004 \u0005[בא\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה ממה שנאמר \u0003\"רצח\" \"רצח\",\u0004 גם בדיני רוצח במזיד וגם בדיני הרוצח בשגגה.","ושאל: \u0003חייבי מלקיות מניין\u0004 שאף אותם מחזירים? והשיב: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה מן המילים \u0003\"רשע\" \"רשע\"\u0004 שנאמרו גם ברוצח וגם בדיני מלקות.","\u0003תניא נמי הכי\u0004 \u0005[שנויה גם כן\u0006 ברייתא\u0005]\u0006 כעין זה: \u0003חייבי גליות מניין?\u0004 — \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 מן המילים \u0003\"רצח\" \"רצח\". חייבי מלקות מניין? אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 מ\u0003\"רשע\" \"רשע\".\u0004","שנינו במשנה ש\u0003אין מחזירין לחובה\u0004 בדיני נפשות. \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: והוא שטעה\u0004 הדיין שזיכה \u0003בדבר שאין הצדוקין מודין בו,\u0004 כלומר, טעה בדבר שאינו כתוב מפורש בתורה, ונלמד מן המסורת או מדברי חכמים (שלא קיבלו הצדוקים אלא את מה שכתוב במפורש בתורה). \u0003אבל\u0004 אם \u0003טעה\u0004 הדיין \u0003בדבר שהצדוקין מודין בו\u0004 וכתוב במפורש בתורה, \u0003\"זיל קרי בי רב\"\u0004 \u0005[\"לך קרא בבית הרב\"]\u0006 \u0003הוא,\u0004 כלומר, טעות כגון זו שמקורה בחוסר ידיעת המקרא מבטלת את הדין מעיקרו ומחזירים את הדין.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' חייא בר אבא מר' יוחנן:\u0004 מי ש\u0003טעה בנואף ונואפת,\u0004 שסבר שבדיני העריות חייב רק הגבר ולא האשה, \u0003מהו\u0004 הדין בכגון זה, האם חוזר בזה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 בפתגם עממי: \u0003\"אדמוקדך יקיד, זיל קוץ קרך וצלי\"\u0004 \u0005[\"עד שהאש בוערת לך, קצוץ\u0006 את \u0005דלעתך וצלה\"],\u0006 כלומר, השתמש בהזדמנות הבאה לידך ועשה מה שביכולתך, לאמור, יכול אתה להוסיף גם הלכה זו למה שלמדת קודם. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן],\u0006 \u0003אמר ר' אמי אמר ר' יוחנן: טעה בנואף\u0004 — \u0003חוזר.\u0004","ושואלים \u0003אלא\u0004 אם כן \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 אותו מקרה ש\u0003אין חוזרין\u0004 גם אם טעו הדיינים בהלכה? \u0003אמר ר' אבהו אמר ר' יוחנן: כגון שטעה\u0004 וזיכה בניאוף שהיה קשור גם בביאה \u0003שלא כדרכה,\u0004 שרק מן המסורת יודעים שביאה בכל אופן חייבים עליה, ואם טעו בכך וזיכו את הנאשם — שוב אין מחייבים אותו.","שנינו במשנה שב\u0003דיני ממונות הכל\u0004 מלמדים זכות וחובה, ואילו בדיני נפשות הכל מלמדים זכות ואין הכל מלמדים חובה. ושואלים: ובדיני נפשות \u0003הכל\u0004 מלמדים זכות \u0003ואפילו\u0004 ה\u0003עדים?\u0004 ותוהים: אם כן \u0003נימא מתניתין\u0004 \u0005[האם נאמר\u0006 ש\u0005משנתנו]\u0006 כשיטת \u0003ר' יוסי בר' יהודה היא ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]?\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר בכתוב: \u0003\"ועד אחד לא יענה בנפש\u0004 למות\u0003\"\u0004 (במדבר לה, ל), וכוונתו: לא יענה ולא ידון העד עצמו \u0003בין לזכות בין לחובה,\u0004 שהעד אינו רשאי להתערב במהלך הדיון. \u0003ר' יוסי בר' יהודה אומר: עונה לזכות, ואין עונה לחובה.\u0004","\u0003אמר רב פפא:\u0004 אין הכרח לומר כן, ובמשנתנו לא דובר כלל בעדים אלא \u0003באחד מן התלמידים\u0004 שהיה יושב שם, \u0003ו\u0004דבר זה כ\u0003דברי הכל\u0004 הוא"],["\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי בר יהודה?\u0004 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ו\u0003עד אחד לא יענה בנפש למות\"\u0004 (במדבר לה, ל), ונדייק: \u0003למות הוא\u0004 ש\u0003אינו עונה, אבל לזכות\u0004 — \u0003עונה.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שחולקים עליו, מה טעמם? \u0003אמר ריש לקיש: משום דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כנוגע בעדותו,\u0004 שהרי אם יתחייב הנאשם ויתברר שהעד היה עד זומם, יהא חייב מיתה, ולכן מנסה הוא לזכות את הנאשם.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"למות\" מאי דרשי ביה\u0004 \u0005[מה דורשים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003מוקמי ליה\u0004 \u0005[מעמידים,\u0006 מסבירים, \u0005אותו]\u0006 \u0003באחד מן התלמידים. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 אם \u0003אמר אחד מן העדים: יש לי ללמד עליו זכות, מניין שאין שומעין לו?\u0004 — \u0003תלמוד לומר: \"\u0004ו\u0003עד אחד לא יענה\". מניין לאחד מן התלמידים שאמר \"יש לי ללמד עליו חובה\", מניין שאין שומעין לו? תלמוד לומר: \"אחד לא יענה בנפש למות\".\u0004","שנינו במשנה כי ב\u0003דיני נפשות\u0004 אין הדיין \u0003המלמד\u0004 זכות יכול לחזור בו. \u0003אמר רב: לא שנו אלא בשעת משא ומתן,\u0004 שאם תחילה לימד זכות לנאשם ואחר כך השתכנע שהוא חייב, שוב אינו יכול להשתתף במשא ומתן ולהביא הוכחות שהנאשם חייב, \u0003אבל בשעת גמר דין\u0004 במנין הדעות, אף מי שהיה בתחילה \u0003מלמד זכות\u0004 יכול שיהא \u0003חוזר ומלמד חובה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו במשנה: \u0003למחרת,\u0004 לאחר היום שבו נשאו ונתנו בדבר \u0003משכימין\u0004 הדיינים \u0003ובאין, המזכה אומר: \"אני המזכה, ומזכה אני במקומי\",\u0004 כלומר, מחזיק אני בדעתי ומזכה. \u0003המחייב אומר: \"אני המחייב, ומחייב אני במקומי\".\u0004 ואז, \u0003המלמד חובה\u0004 בתחילה יכול שיהא חוזר בו ו\u0003מלמד זכות, אבל המלמד זכות אינו יכול לחזור וללמד חובה.\u0004","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003למחרת גמר דין הוא,\u0004 ונאמר במשנה שאינו יכול לחזור בו! ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך, לפי הבנתך\u0005],\u0006 \u0003למחרת, משא ומתן מי ליכא\u0004 \u0005[האם אין שם]?\u0006 הלא יתכן שממשיכים לשאת ולתת גם למחרת. אלא יש להבין \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 שאינו יכול לחזור בו זה רק \u0003בשעת משא ומתן.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקור אחר: היו המחייבים שלושים וששה והמזכים שלושים וחמישה, מאחר ואין מטים לרעה אלא על פי שנים לפחות, על כן \u0003דנין אלו כנגד אלו, עד שיראה אחד מן המחייבין\u0004 את \u0003דברי המזכין,\u0004 ובכך יהיו המחייבים שלושים וחמישה והמזכים שלושים וששה, ומכיון שלזכות מטים אף על פי אחד יוכרע דינו לזכות. \u0003ואם איתא\u0004 \u0005[ישנו]\u0006 מצב שיכול המזכה לחייב, \u0003ליתני נמי איפכא\u0004 \u0005[שישנה גם כן להיפך]\u0006 שיראה אחד מן המזכים את דברי המחייבים ויוכרע איפוא דינו לרעה על פי שנים! ומשיבים: ה\u0003תנא\u0004 על \u0003זכות קא מהדר\u0004 \u0005[הוא מחזר],\u0006 ואולם על ה\u0003חובה לא קא מהדר\u0004 \u0005[אינו מחזר],\u0006 ורוצה לשנות בדרך שיש בה רק זכות, אבל לענין הדין אכן יכול אף המזכה לחזור בו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקור אחר: ש\u0003אמר ר' יוסי בר חנינא: אחד מן התלמידים שזיכה ומת\u0004 — \u0003רואין אותו\u0004 בשעת מנין הדעות \u0003כאילו\u0004 הוא \u0003חי ועומד במקומו\u0004 ומזכה. \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 הלא לשיטת רב שבשעת גמר דין יכול אף המזכה לחזור וללמד חובה \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003אילו הוה\u0004 \u0005[היה]\u0006 \u0003קיים הדר ביה\u0004 \u0005[\u0006היה \u0005חוזר בו\u0006 ומחייב\u0005]!\u0006 ומשיבים: אכן אף לדברי ר' יוסי בר חנינא יכול המזכה לחזור ולחייב, וכדברי רב, אלא שבמציאות \u0003השתא מיהא\u0004 \u0005[עכשיו על כל פנים]\u0006 \u0003לא הדר ביה\u0004 \u0005[חזר בו].\u0006","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]:\u0006 \u0003לדברי ר' יוסי בר חנינא מוצא\u0004 (כלומר, חולק) \u0003מכלל רבינו\u0004 (רב)! ומשיבים: לא כן, אלא \u0003\"אין מוצא\" איתמר\u0004 \u0005[נאמר],\u0006 שרצו לומר שדברי החכמים אינם סותרים זה לזה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר, ששנינו: \u0003שני סופרי הדיינין עומדין לפניהן\u0004 (לפני הדיינים), \u0003אחד מן הימין ואחד מן השמאל, וכותבין\u0004 את \u0003דברי המזכין ו\u0004את \u0003דברי המחייבין.\u0004","\u0003בשלמא\u0004 \u0005[נניח]\u0006 שכותבים את \u0003דברי המחייבין,\u0004 משום החשש שמא \u0003למחר חזו טעמא אחרינא\u0004 \u0005[יראו טעם אחר]\u0006 לחייב, \u0003ובעו למעבד\u0004 \u0005[ויצטרכו לעשות]\u0006 \u0003הלנת דין\u0004 שוב כדי לדון בטעם הנוסף הזה. \u0003אלא\u0004 את \u0003דברי המזכין, מאי טעמא\u0004 \u0005[מה טעם]\u0006 צריכים לרשום? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאי חזו טעמא אחרינא\u0004 \u0005[ש\u0006אף \u0005אם יראו טעם אחר]\u0006 \u0003לחובה לא משגחינן בהו\u0004 \u0005[אין אנו משגיחים בהם],\u0006 ולכן רושמים שזיכו, ואין יכולים עוד לשנות את דעתם?","ומשיבים: \u0003לא, כדי שלא יאמרו שנים\u0004 מן הדיינים \u0003טעם אחד משני מקראות.\u0004 שאם אמרו טעם אחד משני מקראות, משמע שיש פגם באחד הטעמים שלא יתכן שאותו דין ילמד משני מקראות שונים, אלא ודאי לא הבינו מקרא אחד כראוי. \u0003כדבעא מיניה\u0004 \u0005[כמו ששאל ממנו]\u0006 \u0003ר' אסי מר' יוחנן: אמרו שנים טעם אחד משני מקראות מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין מונין להן אלא אחד,\u0004 כלומר, דנים אותם כאיש אחד, מפני שברור שאחד מהם טעה.","לגופו של ענין זה שואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שאין טעם אחד משני מקראות? \u0003אמר אביי:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"אחת דבר אלהים שתים זו שמעתי כי עז לאלהים\"\u0004 (תהלים סב, יב), וכוונתו: \u0003מקרא אחד\u0004 (\"אחת דבר אלהים\") \u0003יוצא\u0004 ומתפרש \u0003לכמה טעמים\u0004 (\"שתים זו שמעתי\"), \u0003ואין טעם אחד יוצא מכמה מקראות.\u0004 בדומה לכך \u0003דבי\u0004 \u0005[\u0006החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה],\u0006 על הנאמר \u0003\"\u0004הלא כה דברי כאש נאום ה' \u0003וכפטיש יפצץ סלע\"\u0004 (ירמיה כג, כט): \u0003מה פטיש זה מתחלק לכמה ניצוצות\u0004 (רסיסים), \u0003אף מקרא אחד יוצא לכמה טעמים.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003טעם אחד משני מקראות? אמר רב זביד, כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מזבח מקדש את הראוי לו,\u0004 כלומר, אם העלו על המזבח קרבן שיש בו צד פסול מסויים, אבל מעיקרו היה דבר הראוי למזבח — הריהו מקבל קדושה ושוב אין מורידים אותו משם.","\u0003ר' יהושע אומר: כל הראוי לאשים\u0004 — \u0003אם עלה\u0004 למזבח שוב \u0003לא ירד, שנאמר:\u0004 \"זאת תורת העולה היא \u0003העלה על מוקדה\u0004 על המזבח כל הלילה עד הבקר ואש המזבח תוקד בו\" (ויקרא ו, א), כלומר, \u0003מה עולה שהיא ראויה לאשים\u0004 (לעלות להישרף על המזבח) \u0003אם עלתה לא תרד, אף כל שהוא ראוי לאשים, אם עלה לא ירד.\u0004","\u0003רבן גמליאל אומר: כל הראוי למזבח\u0004 (ולא רק לאישים) — \u0003אם עלה לא ירד, שנאמר: \"היא העלה על מוקדה על המזבח\", מה עולה שהיא ראויה לגבי מזבח\u0004 — \u0003אם עלתה לא תרד, אף כל שהוא ראוי למזבח\u0004 — \u0003אם עלה לא ירד.\u0004","\u0003ותרוייהו מאי קמרבו\u0004 \u0005[ושניהם מה הם מרבים]\u0006 על ידי השוואות אלו בקרבנות \u0003פסולין\u0004 נוספים, שאם עלו לא ירדו, אלא \u0003מר מייתי לה\u0004 \u0005[חכם זה מביא\u0006 ראיה\u0005]\u0006 \u0003מ\u0004המלה \u0003\"מוקדה\", ומר מייתי לה\u0004 \u0005[וחכם זה מביא\u0006 ראיה\u0005]\u0006 \u0003מ\u0004המלה \u0003\"מזבח\",\u0004 הרי שני מקראות הבאים ללמד ענין אחד.","ודוחים: אין הדבר דומה לענייננו, \u0003והא התם מיפלג פליגי\u0004 \u0005[והרי שם חלוקים\u0006 הם\u0005]\u0006 רבן גמליאל ור' יהושע, ולא טעם אחד הוא אלא שתי שיטות נבדלות הן, \u0003דקתני סיפא\u0004 \u0005[ששנינו בסוף\u0006 אותה משנה\u0005]:\u0006 \u0003אין בין דברי רבן גמליאל לדברי ר' יהושע אלא\u0004 בענין \u0003הדם והנסכים\u0004 הפסולים, \u0003שרבן גמליאל אומר:\u0004 אם עלו \u0003לא ירדו\u0004 שהרי ראויים הם למזבח, \u0003ור' יהושע אומר: ירדו,\u0004 משום שאינם ראויים לאישים (שכן לא הדם ולא הנסכים נשרפים על המזבח אלא נשפכים עליו).","\u0003אלא אמר רב פפא:\u0004 זו היא הדוגמה, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: מתוך שנאמר:\u0004"],["\u0003\"\u0004והיה המזבח קודש קדשים \u0003כל הנגע במזבח יקדש\"\u0004 (שמות כט, לז), \u0003שומע אני\u0004 שכל דבר הנוגע בו יקדש, \u0003בין\u0004 שהוא \u0003ראוי\u0004 לקרבן \u0003בין שאינו ראוי\u0004 לקרבן, \u0003תלמוד לומר\u0004 בהמשך הכתובים: \"וזה אשר תעשה על המזבח \u0003כבשים\u0004 בני שנה שנים ליום תמיד\" (שמות כט, לח), \u0003מה כבשים ראויין\u0004 לקרבן — \u0003אף כל ראוי. ר' עקיבא אומר:\u0004 קרבנות אלה שנאמר בהם \u0003\"עולה\", מה עולה ראויה\u0004 למזבח \u0003אף כל ראוי.\u0004","\u0003ותרוייהו מאי קא ממעטו\u0004 \u0005[ושניהם מה הם ממעטים\u0006 מפסוק זה\u0005]?\u0006 — קרבנות \u0003פסולי\u0004 \u0005[פסולים],\u0006 \u0003מר מייתי לה\u0004 \u0005[חכם זה מביא\u0006 ראייה\u0005]\u0006 \u0003מ\u0004המלה \u0003\"כבשים\", ומר מייתי לה\u0004 \u0005[וחכם זה מביא\u0006 ראייה\u0005]\u0006 \u0003מ\u0004המלה \u0003\"עולה\",\u0004 הרי טעם אחד משני מקראות.","ודוחים: אין זו דוגמה ראויה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אדא בר אהבה:\u0004 שאף כאן יש מחלוקת עניינית בין התנאים לענין \u0003עולת העוף פסולה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 \u0003מאן דמייתי לה\u0004 \u0005[מי שמביא,\u0006 לומד את הדבר\u0005]\u0006 \u0003מ\u0004המלה \u0003\"כבשים\",\u0004 סבור כי: \u0003כבשים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל עולת העוף\u0004 — \u0003לא. ומאן דמייתי לה\u0004 \u0005[ומי שמביא,\u0006 לומד את הדבר\u0005]\u0006 \u0003מ\u0004המלה \u0003\"עולה\"\u0004 — \u0003אפילו עולת העוף נמי\u0004 \u0005[גם כן]\u0006 בכלל זה!","\u0003אלא אמר רב אשי:\u0004 הדוגמה היא ממקור אחר, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר במקרא שמי שמקריב קרבן \"ואל פתח אהל מועד לא הביאו להקריב קרבן לה' לפני משכן ה' \u0003דם יחשב לאיש ההוא דם שפך\u0004 ונכרת האיש ההוא מקרב עמו\" (ויקרא יז, ד), ומדברי הפסוק יש ללמוד: \u0003לרבות את הזורק\u0004 דם קדשים בחוץ, לא במקדש, אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר:\u0004 מן הכתוב \u0003\"\u0004איש איש מבית ישראל ומן הגר אשר יגור בתוכם אשר יעלה עולה \u0003או זבח\"\u0004 (ויקרא יז ח), יש ללמוד: \u0003לרבות את הזורק. ותרוייהו מאי קא מרבו\u0004 \u0005[ושניהם מה הם מרבים]?\u0006 — חיוב על \u0003זריקה\u0004 של הדם בחוץ. \u0003מר מייתי לה\u0004 \u0005[חכם זה מביא\u0006 ראייה\u0005]\u0006 \u0003מ\u0004המלה \u0003\"דם יחשב\", ומר מייתי לה\u0004 \u0005[וחכם זה מביא\u0006 ראייה\u0005]\u0006 \u0003מ\u0004המילים \u0003\"או זבח\".\u0004","ודוחים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבהו\u0004 כי לענין \u0003שחט וזרק\u0004 בחוץ בשוגג \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 ש\u0003לדברי ר' ישמעאל\u0004 — \u0003אינו חייב אלא אחת, לדברי ר' עקיבא\u0004 — \u0003חייב שתים,\u0004 שכן שני איסורים נפרדים הם אלה הנלמדים משני מקראות שונים, ואם כן אף דוגמה זו אין בה כראיה.","ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי נאמר עליה],\u0006 על הלכה זו, \u0003אמר אביי: אף לדברי ר' עקיבא נמי\u0004 \u0005[גם כן]\u0006 \u0003אינו חייב אלא אחת,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כי אם במקום אשר יבחר ה' באחד שבטיך \u0003שם תעלה עלתיך ושם תעשה\u0004 כל אשר אנכי מצוך\" (דברים יב, יד) — \u0003ערבינהו רחמנא לכולהו\u0004 \u0005[עירבה התורה את כל]\u0006 ה\u0003עשיות\u0004 לעשותן כחטא אחד, ואם כן נמצא שאינם חלוקים בהלכה אלא רק במקור הדין, ובמקרה זה מצרפים את שתי הדעות להיחשב כדעה אחת.","במשנה שנינו ש\u0003דיני ממונות דנין ביום\u0004 ובלילה \u0003(סימן\u0004 לראיות בענין זה: \u0003משפט מענה מטה).\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר ר' חייא בר פפא,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושפטו את העם בכל עת\"\u0004 (שמות יח, כב), משמע: בין ביום בין בלילה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שזהו המקור להלכה, \u0003תחלת דין נמי\u0004 \u0005[גם כן]\u0006 יתחיל אפילו בלילה! ומשיבים: יש ליישב את הדבר \u0003כ\u0004דברי \u0003רבא.\u0004 ש\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין הכתובים: \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד: \u0003\"ושפטו את העם בכל עת\",\u0004 ומשמע — אף בלילה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק אחר \u0003\"והיה ביום הנחילו את בניו\"\u0004 (דברים כא, טז), ומשמע שדיני נחלות (שהם בכלל דיני ממונות) נידונים רק ביום! \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב את הסתירה? — \u0003יום לתחלת דין,\u0004 ואף \u0003לילה לגמר דין.\u0004","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' מאיר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: מה תלמוד לומר \"על פיהם יהיה כל ריב וכל נגע\"\u0004 (דברים כא, ה), \u0003וכי מה ענין ריבים אצל נגעים,\u0004 שהלא אלה דיני ממונות ואלה דיני טהרות?","\u0003אלא מקיש\u0004 (משווה) הכתוב \u0003ריבים לנגעים,\u0004 לומר: \u0003מה נגעים\u0004 אינם נבדקים אלא \u0003ביום, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"וביום הראות בו\u0004 בשר חי יטמא\u0003\"\u0004 (ויקרא יג, יד), \u0003אף ריבים\u0004 אינם נידונים אלא \u0003ביום. ומה נגעים\u0004 נבדקים \u0003שלא בסומין, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"לכל מראה עיני הכהן\"\u0004 (ויקרא יג יב), \u0003אף ריבים\u0004 נידונים דווקא \u0003שלא בסומין. ומקיש\u0004 (משווה) \u0003נגעים לריבים\u0004 ללמוד לענין אחר: \u0003מה ריבים\u0004 נידונים \u0003שלא בקרובים, אף נגעים\u0004 נבדקים \u0003שלא בקרובים.\u0004","ומקשים: אם מקבלים השוואה זו לכל דבר, מדוע לא נאמר \u0003אי\u0004 \u0005[או]\u0006 \u0003מה ריבים\u0004 נידונים דווקא \u0003בשלשה\u0004 — \u0003אף נגעים\u0004 אינם נראים אלא על ידי \u0003שלשה\u0004 כהנים, ולא פחות. \u0003ו\u0004לכאורה אפילו \u0003דין\u0004 (קל וחומר) \u0003הוא\u0004 המסייע לסברה זו: אם \u0003ממונו\u0004 שהוא קל אינו נידון אלא \u0003בשלשה, גופו לא כל שכן! תלמוד לומר: \"והובא אל אהרן הכהן או אל אחד\u0004 מבניו הכהנים\u0003\"\u0004 (ויקרא יג ב). \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת שאפילו כהן אחד רואה את הנגעים.\u0004 ובכל אופן מכאן מובן שדיינים אינם יכולים לדון כלל בלילה, ואפילו לצורך גמר דין, ומשמע שמשנתנו אינה כשיטה זו.","מסופר: \u0003ההוא סמיא דהוה בשבבותיה\u0004 \u0005[עיוור אחד שהיה בשכנותו]\u0006 של \u0003ר' יוחנן, דהוה דאין דינא\u0004 \u0005[שהיה דן דין],\u0006 \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן ולא מידי\u0004 \u0005[דבר].\u0006 ושואלים: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה כן]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן\u0004 עצמו: \u0003הלכה כסתם משנה. ותנן\u0004 \u0005[ו\u0006הלא \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הכשר לדון כשר להעיד, ויש שכשר להעיד ואין כשר לדון. ואמר ר' יוחנן:\u0004 משנה זו באה \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003סומא באחת מעיניו\u0004 שכשר להעיד אבל פסול לדון (וכדברי ר' מאיר המשווה דינים לנגעים)!","ומשיבים: \u0003ר' יוחנן סתמא אחריתא אשכח\u0004 \u0005[סתם\u0006 משנה \u0005אחרת מצא]\u0006 ועליה סמך להכשיר את הסומא. שכן שנינו במשנה: \u0003דיני ממונות דנין ביום וגומרין בלילה\u0004 משמע שאין משווים דיני ממונות לדיני נגעים, וממילא אף הסומא כשר בדינים.","ושואלים: \u0003מאי אולמיה דהאי סתמא מהאי סתמא\u0004 \u0005[מה תוקפו של סתם זה מסתם זה],\u0006 ומדוע סמך על מקור זה ולא על האחר? ומשיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003סתמא\u0004 \u0005[סתם]\u0006 שבו פוסקים כדעת ה\u0003רבים עדיף\u0004 על סתם משנה שנפסקה כדעת יחיד, \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר: \u0003משום דקתני לה גבי הלכתא דדינא\u0004 \u0005[ששנה אותה,\u0006 את הדבר \u0005אצל,\u0006 סמוך ל\u0005הלכות דינים],\u0006 שכאן עיקר מקומו ושם מובא הענין רק בדרך אגב, וראוי לסמוך יותר על מה שנפסק בנושא העיקרי.","ושואלים: \u0003ור' מאיר, האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"ושפטו את העם בכל עת\", מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא \u0005בו]?\u0006 \u0003אמר רבא: לאיתויי\u0004 \u0005[להביא]\u0006 \u0003יום המעונן\u0004 שכשר לדין בו אף כי אין רואים בו נגעים. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין רואין את הנגעים\u0004 לא בשעות \u0003שחרית\u0004 שאין השמש בתוקפה, \u0003ו\u0004לא \u0003בין הערבים, ולא בתוך הבית, ולא ביום המעונן, מפני ש\u0004בהרת \u0003כהה נראית עזה\u0004 (לבנה מאד), ובהרת עזה — מטמאה. \u0003ולא\u0004 רואים \u0003בצהרים מפני ש\u0004בהרת \u0003עזה נראית כהה\u0004 ועשוי להתירה, אלא רואים דווקא בשעות שבהן האור ממוצע.","ושואלים: \u0003ור' מאיר, האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"ביום הנחילו את בניו\", מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 שהרי לשיטתו שוב אין צורך ללמוד הלכה מכתוב זה, שהרי כבר נלמדה ההלכה בדרך ההיקש מנגעים! ומשיבים: הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נחוץ לו]\u0006 \u0003לכדתני\u0004 \u0005[לכפי ששנה]\u0006 \u0003רבה בר חנינא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן:\u0004 מה שנאמר \u0003\"והיה ביום הנחילו את בניו\",\u0004 כוונתו: \u0003ביום אתה מפיל נחלות, ואי\u0004 (אין) \u0003אתה מפיל נחלות בלילה. אמר ליה\u0004 \u0005[לו]\u0006 ר' נחמן: תמוה הדבר, \u0003אלא מעתה מאן דשכיב ביממא ירתון ליה בניה\u0004 \u0005[מי שמת ביום ירשו אותו בניו],\u0006 \u0003ומאן דשכיב בליליא\u0004 \u0005[ומי שמת בלילה]\u0006 \u0003לא ירתון ליה בניה\u0004 \u0005[יירשו אותו בניו]?!\u0006","אין הדבר מסתבר כלל, ואולם \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003דין נחלות קאמרת\u0004 \u0005[אומר אתה].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הנאמר בסוף פרשת דיני הירושה: \u0003\"והיתה לבני ישראל לחקת משפט\"\u0004 (במדבר כז, יא), שנינו: \u0003אורעה\u0004 (זומנה, שויכה) \u0003כל הפרשה כולה להיות דין\u0004 (\"חוקת משפט\"), שיחולו בענין זה חוקים השייכים במשפט,","וכפי שאמר \u0003רב יהודה אמר\u0004 (בשם) \u0003רב,\u0004 ש\u0003אמר רב יהודה אמר רב: שלשה שנכנסו לבקר את החולה\u0004 העומד למות, וציוה להם כמה דברים לגבי ירושתו, \u0003רצו\u0004 — \u0003כותבין\u0004 כעדים ששמעו את צוואתו, \u0003רצו\u0004 — \u0003עושין דין,\u0004 שנעשים כדיינים וכותבים מעשה בית דין בענין זה. היו המבקרים רק \u0003שנים\u0004 — \u0003כותבין\u0004 כעדים, \u0003ואין עושין דין.\u0004","\u0003ואמר רב חסדא: לא שנו אלא\u0004 כשביקרוהו \u0003ב\u0004שעות ה\u0003יום, אבל\u0004 אם ביקרוהו \u0003בלילה\u0004 — \u0003כותבין ואין עושין דין\u0004 אפילו היו שלושה, \u0003משום דהוו להו\u0004 \u0005[שהריהם]\u0006 כ\u0003עדים, ואין עד נעשה דיין,\u0004 ואילו לדון אינם יכולים משום שלילה אינו זמן הראוי לדין, ולכן גם לא לחלוקת ירושה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר חנינא לרב נחמן: \u0003אין\u0004 \u0005[כן],\u0006 \u0003הכי קאמינא\u0004 \u0005[זה שאני אומר],\u0006 כלומר, כוונתי היתה שאין דנים דיני נחלות בלילה.","שנינו במשנה כי \u0003דיני נפשות דנין ביום\u0004 וגומרים דינם ביום. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שדיני נפשות אינם נידונים אלא ביום? \u0003אמר רב שימי בר חייא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והוקע אותם לה' נגד השמש\"\u0004 (במדבר כה, ד), משמע שדנים דיני נפשות ביום (\"נגד השמש\"). \u0003אמר רב חסדא: מניין ל\"הוקעה\" שהיא תלייה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שבקשו הגבעונים על בני שאול: \u0003\"והוקענום לה' בגבעת שאול בחיר ה' \"\u0004(שמואל ב' כא, ו),"],["\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ותקח רצפה בת איה את השק ותטהו לה אל הצור בתחלת קציר\u0004 עד ניתך מים עליהם מן השמים ולא נתנה עוף השמים לנוח עליהם יומם ואת חית השדה לילה\u0003\"\u0004 (שמואל ב' כא, י), משמע שאנשים אלה המוקעים — תלויים היו.","אגב הזכרת כתוב זה דנים בו, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר ה' אל משה קח את כל ראשי העם\u0004 והוקע אותם לה' נגד השמש וישוב חרון אף ה' מישראל\u0003\"\u0004 (במדבר כה, ד). ותוהים: \u0003אם העם חטאו, ראשי העם מה חטאו\u0004 שכך נענשו?","\u0003אמר רב יהודה אמר רב: אמר לו הקדוש ברוך הוא למשה:\u0004 אין הכוונה שיוקיע משה את ראשי העם, אלא שראשי העם יוקיעו את עוברי העבירה, ובדרך זו: \u0003חלק להם\u0004 לראשי העם \u0003בתי דינין\u0004 מרובים, וכל אחד ידון את אנשיו ויוקיעם לפי הצורך. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הוצרכו למנות בתי דינים רבים לצורך זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 הכלל ש\u0003אין דנין שנים\u0004 (שני אנשים) \u0003ביום אחד,\u0004 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא:\u0004 \u0003לא שנו\u0004 איסור זה \u0003אלא בשתי מיתות\u0004 שונות שיש שתי עבירות לחוד, \u0003אבל במיתה אחת\u0004 — \u0003דנין,\u0004 ואם כן יכול היה בית דין אחד לדון את כולם!","\u0003אלא\u0004 הטעם הוא משום שכשיש רשעים יש חרון אף בעולם, ו\u0003כדי שישוב חרון אף מישראל\u0004 צריך לדונם ולהמיתם, וכשהם רבים, אם יידונו כולם בבית דין אחד יימשך הדבר זמן רב ולא במהרה יתבטל חרון האף. ולכן יש למנות בתי דינים רבים ככל האפשר ובכך למהר את מיצוי דין הרשעים (רמ\"ה).","שנינו במשנה ש\u0003דיני ממונות גומרין בו ביום\u0004 ודיני נפשות ממתינים עד למחרת. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006","\u0003אמר ר' חנינא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"מלאתי משפט צדק ילין בה ועתה מרצחים\"\u0004 (ישעיה א, כא), ומכאן למדו שבדין צדק יש להלין את הדין, ולא להרוג מיד את הנידון. \u0003ורבא אמר\u0004 שהדבר נלמד \u0003מהכא\u0004 \u0005[מכאן],\u0006 מכתוב זה: \u0003\"\u0004למדו היטב דרשו משפט \u0003אשרו חמוץ\"\u0004 (ישעיה א, יז), ומתפרש: \u0003אשרו\u0004 (תנו שבח) לאותו \u0003דיין שמחמץ\u0004 (משהה) \u0003את דינו\u0004 לפני שפוסק בו.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' חנינא, שלא למד מכתוב זה, מה דורש הוא מכאן? \u0003\"אשרו חמוץ\"\u0004 (נגזל) — \u0003ולא חומץ\u0004 (גזלן), כפי שעושים דייני רשע. \u0003ואידך\u0004 \u0005[והאחר,\u0006 רבא\u0005],\u0006 \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"מלאתי משפט\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006","ומשיבים: הוא מבין אותו \u0003כ\u0004דברי \u0003ר' אלעזר\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יצחק,\u0004 ש\u0003אמר ר' אלעזר אמר ר' יצחק: כל\u0004 יום \u0003תענית שמלינין בו את הצדקה,\u0004 שלא חילקו לעניים את כספי הצדקה שהיו גובים ביום התענית, בו ביום, הרי זה \u0003כאילו שופך דמים\u0004 של העניים שנזקקים לצדקה ומצפים שיתנו להם ביום זה, וכיון שהתענו כל היום וסמכו שיתנו להם צדקה, יימצאו מתענים לילה נוסף, \u0003שנאמר: \"מלאתי משפט\",\u0004 אם ה\u0003צדק\u0004 (צדקה) ילין בה (עד למחרת) — הרי זה \"ועתה מרצחים\". ומסייגים: \u0003והני מילי\u0004 \u0005[ודברים אלו]\u0006 אמורים \u0003ב\u0004חלוקת \u0003ריפתא ותמרי\u0004 \u0005[לחם ותמרים]\u0006 אם אין נותנים בזמנם, \u0003אבל בזוזי חיטי ושערי\u0004 \u0005[בכסף חיטים ושעורים]\u0006 — \u0003לית לן בה\u0004 \u0005[אין לנו בהם\u0006 איסור הלנה\u0005],\u0006 שהרי בין כה וכה לא יוכלו העניים להשתמש בהם מיד.","שנינו במשנה כי משום שיש להלין את דינו של מי שנתחייב עוד יום לדחות, \u0003לפיכך אין דנין\u0004 לא בערב שבת ולא בערב יום טוב. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006","— \u0003משום\u0004 ש\u0003לא אפשר\u0004 לעשות אחרת. \u0003היכי ליעבד\u0004 \u0005[איך יעשה]?\u0006 אם תאמר ש\u0003לידייניה במעלי שבתא וליגמריה לדיניה במעלי שבתא\u0004 \u0005[ידונו אותו בערב שבת ושיגמרו את דינו בערב שבת]\u0006 — \u0003דילמא חזו\u0004 \u0005[שמא יראו]\u0006 \u0003טעם לחובה, ובעו למיעבד\u0004 \u0005[ויצטרכו לעשות]\u0006 \u0003הלנת דין\u0004 עד למחר. ואם תאמר: \u0003לדייניה במעלי שבתא וליגמריה בשבתא וליקטליה בשבתא\u0004 \u0005[שידונוהו בערב שבת ויגמרוהו,\u0006 את הדין \u0005בשבת, ויהרגוהו בשבת]\u0006 — הרי \u0003אין רציחה\u0004 של רוצח וכיוצא בו \u0003דוחה את\u0004 ה\u0003שבת.\u0004 ואם תאמר: \u0003וליקטליה לאורתא\u0004 \u0005[ושיהרגוהו בלילה]\u0006 במוצאי שבת — הרי \u0003\"נגד השמש\" בעינן\u0004 \u0005[צריכים אנו],\u0006 שאין הורגים אלא ביום.","ואם תאמר: \u0003וליגמריה לדיניה בשבתא, וליקטליה בחד בשבתא\u0004 \u0005[שיגמרו את דינו בשבת, ויהרגוהו באחד בשבת]\u0006 — \u0003נמצא אתה מענה את דינו,\u0004 שאותו אדם יהא חייב להמתין עד למחרת תוך ידיעה שהוא נידון למוות, ודבר זה הוא הקרוי \"עינוי הדין\". ואם תאמר: \u0003נידייניה במעלי שבתא ונגמריה בחד בשבתא\u0004 \u0005[נדונהו בערב שבת ונגמרהו באחד בשבת]\u0006 — \u0003מינשו טעמייהו\u0004 \u0005[ישכחו\u0006 הדיינים את \u0005טעמיהם]\u0006 בינתיים, ו\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003שני סופרי הדיינין עומדים לפניהם, וכותבין\u0004 את \u0003דברי המזכין ו\u0004את \u0003דברי המחייבין\u0004 — \u0003נהי דבפומא כתבין\u0004 \u0005[אמנם\u0006 דברים \u0005שבפה\u0006 הם \u0005כותבים],\u0006 אבל \u0003ליבא דאינשי\u0004 \u0005[ליבם של האנשים]\u0006 טעמיהם שהיא במחשבתם — \u0003אינשי\u0004 \u0005[נשכחים],\u0006 \u0003הלכך\u0004 \u0005[לכן]\u0006 \u0003לא אפשר.\u0004","בקשר להלכה זו שנרמז בה שאין הורגים את הנידון בשבת, לעצם הדברים \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן: ותהא קבורת מת מצוה\u0004 (מת שאין מי שיטפל בו, שמצוה רבה היא לטפל בקבורתו) \u0003דוחה שבת מקל וחומר\u0004 זה: \u0003ומה עבודה\u0004 של בית המקדש \u0003שדוחה שבת\u0004 (שהרי עובדים במקדש גם בשבת), בכל זאת \u0003קבורת מת מצוה דוחה אותה,\u0004 ולמדנו זאת \u0003מ\u0004הריבוי \u0003\"ולאחתו\",\u0004","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר בנזיר \"כל ימי הזירו לה' על נפש מת לא יבא \u0003לאביו ולאמו לאחיו ולאחתו\u0004 לא יטמא להם במותם כי נזר אלהיו על ראשו\" (במדבר ו, ו–ז), \u0003מה תלמוד לומר?\u0004 מה באה להוסיף לנו רשימת כל בני המשפחה שלו? אלא יש לומר שהיא באה ללמדנו במקרים מיוחדים, \u0003הרי שהיה\u0004 הנזיר \u0003הולך לשחוט את פסחו\u0004 או \u0003למול את בנו\u0004 שהן מצוות חשובות שחייבים כרת על ביטולן"],["\u0003ושמע שמת לו מת\u0004 אחד מקרוביו, האם \u0003יכול\u0004 הוא ש\u0003יטמא? אמרת\u0004 על פי אזהרת המקרא: \u0003\"לא יטמא\".\u0004","\u0003יכול כשם שאינו מטמא לאחותו כך אינו מטמא למת מצוה\u0004 שהוא מוצא בדרך? \u0003תלמוד לומר\u0004 ההדגשה: \u0003\"ולאחתו\",\u0004 וכוונתו: \u0003לאחותו הוא\u0004 ש\u0003אינו מטמא\u0004 שהרי יש מי שיטפל בה, \u0003אבל מטמא\u0004 הוא \u0003למת מצוה,\u0004 הרי שעבודת הקרבנות (הקרבת קרבן פסח) נדחית מפני מת מצוה.","ומעתה \u0003שבת שנידחת\u0004 אף \u0003מפני עבודה, אינו דין שתהא קבורת מת מצוה דוחה אותה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: מכאן אין להוכיח, כי עונש על \u0003רציחה תוכיח, ש\u0004אמנם \u0003דוחה את העבודה,\u0004 שאף אם יש רק כהן יחיד במקדש ונידון למוות — מורידים אותו מעל המזבח ומבטלים אותו מהעבודה, \u0003ו\u0004בכל זאת \u0003אינה דוחה את השבת.\u0004","הקשה לו ריש לקיש, אם כן נאמר להיפך: \u0003רציחה גופה תדחה את השבת מקל וחומר\u0004 זה: \u0003מה עבודה שדוחה את השבת\u0004 — \u0003רציחה דוחה אותה,\u0004 ומנין יודעים שעונש רציחה דוחה את העבודה? — \u0003שנאמר:\u0004 \u0003\"\u0004וכי יזיד איש על רעהו להרגו בערמה \u0003מעם מזבחי תקחנו למות\"\u0004 (שמות כא, יד), אם כן, \u0003שבת שנידחת מפני עבודה, אינו דין שתהא רציחה דוחה אותה?\u0004","\u0003אמר רבא: כבר פסקה,\u0004 כבר הוכיח את הדבר ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 מה שנאמר \u0003\"לא תבערו אש\u0004 בכל מושבותיכם ביום השבת\u0003\"\u0004 (שמות לה, ג) \u0003מה תלמוד לומר?\u0004 מה בא פסוק זה ללמדנו? הלא כל המלאכות אסורות בשבת, והבערה בכללן!","ותוהים: \u0003מה תלמוד לומר?!\u0004 והלא הרבה לימודים יש בדבר, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003ר' יוסי\u0004 — שלדעתו עבירה זו \u0003ל\u0004איסור \u0003לאו\u0004 (מצות \"לא תעשה\") \u0003יצאת\u0004 (יצאה) ללמד, שלשיטתו מוכיח הכתוב שהבערת אש איננה מכלל המלאכות האסורות בשבת בעונש כרת, אלא חייבים עליה רק בלאו בלבד. \u0003אי\u0004 \u0005[או]\u0006 \u0003ל\u0004דעת \u0003ר' נתן\u0004 — \u0003לחלק יצאת. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הבערה\u0004 זו שכתובה בתורה \u0003ללאו יצאת,\u0004 כלומר, ללמד שיש רק איסור לאו בדבר, אלו \u0003דברי ר' יוסי. ר' נתן אומר: לחלק יצאת,\u0004 ללמד שעל כל אב מלאכה ומלאכה שעושים בשבת חייבים לחוד, ואין כל המלאכות נחשבות כאחת. ועל כל פנים לימוד גדול יש מכאן.","\u0003אלא אמר רבא:\u0004 אותו ה\u0003תנא\u0004 הלומד מכתוב זה, לא מ\"לא תבערו אש\" למד, אלא המלה \u0003\"משבות\"\u0004 שבכתוב זה \u0003קשיא ליה\u0004 \u0005[היתה קשה לו].\u0006 וכך יש להבין את דבריו: נאמר שם \"בכל מושבותיכם\", \u0003\"מושבות\" מה תלמוד לומר? מכדי\u0004 \u0005[הרי]\u0006 \u0003שבת חובת הגוף היא,\u0004 שהיא חלה על האדם ולא על מקום מסויים, \u0003וחובת הגוף\u0004 הלא \u0003נוהגת בין בארץ בין בחוץ לארץ,\u0004 ואם כן ההדגשה \u0003\"מושבות\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004","— \u0003משום\u0004 (בשם) \u0003ר' ישמעאל אמר תלמיד אחד, לפי שנאמר: \"כי יהיה באיש חטא משפט מות והומת\"\u0004 (דברים כא, כב), ומדברי הכתוב הזה \u0003שומע אני\u0004 (כיון שלא נאמר אחרת) שדין זה של הריגת החייב על ידי בית דין קיים \u0003בין בחול בין בשבת, והא\u0004 \u0005[והרי]\u0006 \u0003מה אני מקיים\u0004 מה שנאמר \u0003\"\u0004ושמרתם את השבת כי קודש היא לכם \u0003מחלליה מות יומת\"\u0004 (שמות לא, יד) — \u0003בשאר מלאכות, חוץ ממיתת בית דין\u0004 המותרת אפילו בשבת, \u0003או\u0004 אפשר להבין באופן אחר, ש\u0003אינו אלא\u0004 שאיסור חילול שבת כולל \u0003אפילו מיתת בית דין, ומה אני מקיים\u0004 את הכתוב \u0003\"והומת\"\u0004 — \u0003בחול אבל לא בשבת, או אינו אלא אפילו בשבת?\u0004","והרי ספק שקול, \u0003תלמוד לומר: \"לא תבערו אש בכל משבתיכם\"\u0004 שנאמר כאן, \u0003ולהלן הוא אומר\u0004 בדיני רוצח: \u0003\"והיו אלה לכם לחקת משפט לדרתיכם בכל מושבתיכם\"\u0004 (במדבר לה, כט), \u0003מה\u0004 לשון \u0003\"מושבות\" האמור להלן\u0004 (בענין רוצח) — הכוונה ל\u0003בית דין, אף \"מושבות\" האמור כאן\u0004 (לענין שבת) — \u0003בית דין\u0004 הוא. \u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003\"לא תבערו אש בכל משבתיכם\",\u0004 שגם במושב בית הדין שדן דיני נפשות כגון שריפה באש — אין עושים אותם. ולענייננו למדים אנו איפוא ראיה מן התורה שאין רציחה דוחה את השבת.","\u0003אמר אביי: השתא דאמרת\u0004 \u0005[עכשיו שאומר אתה]\u0006 על סמך הכתובים ש\u0003אין רציחה\u0004 של החייב על ידי בית הדין \u0003דוחה את השבת,\u0004 לכאורה אפשר לומר ש\u0003אין רציחה דוחה את העבודה מקל וחומר\u0004 זה: \u0003ומה שבת שנידחית מפני העבודה\u0004 — \u0003אין רציחה דוחה אותה, עבודה שהיא\u0004 חמורה ו\u0003דוחה את השבת\u0004 — \u0003אינו דין שלא תהא רציחה דוחה אותה?\u0004","ומקשים: \u0003אלא הא דכתיב\u0004 \u0005[זה שנאמר]\u0006 ברוצח \u0003\"מעם מזבחי תקחנו למות\"\u0004 (שמות כא, יד), הרי שרציחה דוחה את העבודה! ומתרצים: הפסוק \u0003ההוא\u0004 \u0003לקרבן יחיד\u0004 בא ללמד, שהוא כידוע \u0003לא דחי\u0004 \u0005[דוחה]\u0006 את ה\u0003שבת,\u0004 שאין הכהן מקריב קרבן יחיד בשבת, ורק קרבנות ציבור דוחים את השבת. וכוונת הכתוב לפירוש זה היא כך: כהן שרצח ועומד להקריב קרבן יחיד, אינו מקריב אלא לוקחים אותו למות.","\u0003אמר רבא: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מבין, נמשיך איפוא בדרך זו ונאמר ש\u0003לא תהא רציחה דוחה\u0004 אף \u0003קרבן יחיד מקל וחומר\u0004 זה:"],["\u0003מה יום טוב שנדחה מפני קרבן יחיד,\u0004 שהרי מקריבים ביום טוב אף נדרי יחידים ונדבותיהם, בכל זאת \u0003אין רציחה דוחה אותו,\u0004 שלענין עצם איסורי מלאכה אין הבדל בין יום טוב ושבת (חוץ ממלאכות הצריכות כ\"אוכל נפש\"), \u0003קרבן יחיד שהוא דוחה את יום טוב, אינו דין שלא תהא רציחה דוחה אותו\u0004 וכהן שרצח ורוצה להקריב קרבן יחיד, מניחים לו להקריב,","ונמצאים דברי אביי נסתרים. וממשיכים: \u0003הניחא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003אין נדרים ונדבות\u0004 של יחידים \u0003קריבין ביום טוב,\u0004 וכיון שאין קרבן יחיד דוחה את יום טוב אין מקום לקל וחומר זה, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003נדרים ונדבות\u0004 של יחידים \u0003קריבין ביום טוב,\u0004 ונמצא איפוא שקרבן יחיד חמור דוחה יום טוב, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא אמר רבא\u0004 יש לדחות את מה שאמרנו, ולומר ש\u0003לא מיבעיא למאן דאמר\u0004 \u0005[נצרכה\u0006 לומר \u0005ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003נדרים ונדבות קריבין ביום טוב\u0004 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא מתקיים\u0004 לפי זה \u0003\"מעם מזבחי\" כלל,\u0004 שהרי אז אין הדבר מתקיים לא בציבור ולא ביחיד, ואין לומר שהפסוק אין לו כל תוכן.","\u0003אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003נדרים ונדבות אין קריבין ביום טוב,\u0004 אין לקבל את דעת אביי שמדובר בכתוב רק בקרבן יחיד, כי \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"מעם מזבחי\",\u0004 וכוונתו: \u0003מזבחי המיוחד לי. ומאי נינהו\u0004 \u0005[ומה הוא]?\u0006 — קרבן ה\u0003תמיד,\u0004 שהוא זבח המיוחד לה'. \u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003\"מעם מזבחי תקחנו למות\".\u0004","שנינו במשנה ש\u0003דיני ממונות\u0004 וכן \u0003הטמאות והטהרות\u0004 מתחילים מן הגדול, שבכל הדינים חוץ מדיני נפשות מתחילים מן הגדול שבחבורה. \u0003אמר רב: אנא הואי במנינא דבי\u0004 \u0005[אני הייתי במנין\u0006 הדיינים \u0005שבבית]\u0006 \u0003רבי\u0004 יהודה הנשיא, \u0003ומינאי דידי הוו מתחלי ברישא\u0004 \u0005[וממני היו מתחילים בראש]\u0006 לשאול מה דעתי, ורב הצעיר שבהם היה. ומקשים: \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"מתחילין מן הגדול\"\u0004 בשאר דינים \u0003תנן\u0004 \u0005[שנינו],\u0006 ובימי רבי לא דנו דיני נפשות!","\u0003אמר רבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' הלל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' וולס, שאני מניינא דבי\u0004 \u0005[שונה מניינו של בית]\u0006 \u0003רבי, דכולהו מנינייהו\u0004 \u0005[ש\u0006את \u0005כל מניינם]\u0006 \u0003מן הצד הוו מתחלי\u0004 \u0005[היו מתחילים],\u0006 משום שהיה רבי גדול מאוד בחכמה ובגדולה ולא היו מעיזים להמרות את פיו, ולכן אמרו שבבית דין יתחילו מן הקטן כדי שדעת רבי תישמע באחרונה ולא תשפיע על האחרים.","\u0003ואמר רבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' הלל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' וולס: מימות משה ועד רבי לא מצינו תורה\u0004 (גדול הדור בתורה) \u0003וגדולה\u0004 (שנתברך בשלטון ועושר) \u0003במקום אחד,\u0004 שיהיו שתי מידות אלה באדם אחד שהוא יחיד בכך.","ומקשים: \u0003ו\u0004כי \u0003לא\u0004 היה כדבר הזה? \u0003הא הוה\u0004 \u0005[הרי היה]\u0006 \u0003יהושע\u0004 בן נון! ומשיבים: אכן היו בו שניהם, אלא שלא היה גדול הדור בכל, שכן בזמנו \u0003הוה\u0004 \u0005[היה]\u0006 \u0003אלעזר\u0004 שהיה גדול בתורה כמותו. ומקשים: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003פנחס!\u0004 ומשיבים: \u0003הוו\u0004 \u0005[היו]\u0006 \u0003זקנים\u0004 שהאריכו ימים אחרי יהושע שהיו גדולים בתורה.","ומקשים: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003שאול\u0004 המלך! ומשיבים: \u0003הוה\u0004 \u0005[היה]\u0006 \u0003שמואל\u0004 בדורו שהיה גדול הדור בתורה. ושואלים: \u0003והא נח נפשיה\u0004 \u0005[והרי מת]\u0006 שמואל בחיי שאול! ומשיבים: \u0003כולהו שניה קאמרינן\u0004 \u0005[כל שנותיו אמרנו],\u0006 שלא היה אדם שבכל שנות מנהיגותו היה גדול מכל בני דורו בתורה ובממשלה.","ומוסיפים להקשות: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003דוד!\u0004 ודוחים: \u0003הוה\u0004 \u0005[היה]\u0006 \u0003עירא היאירי\u0004 שהיה רבו בתורה. ושואלים: \u0003והא נח נפשיה\u0004 \u0005[והרי מת]\u0006 בחיי דוד! ומשיבים: \u0003כולהו שניה קאמרינן\u0004 \u0005[כל שנותיו אמרנו].\u0006","ועוד שואלים: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003שלמה!\u0004 ודוחים: \u0003הוה\u0004 \u0005[היה]\u0006 \u0003שמעי בן גרא\u0004 שהיה רבו של שלמה בתורה. ומקשים: \u0003והא קטליה\u0004 \u0005[והרי הרגו\u0006 שלמה\u0005]!\u0006 ומשיבים: הלא גדול הדור \u0003כוליה שניה קאמרינן\u0004 \u0005[כל שנותיו אמרנו].\u0006","ומקשים: \u0003הא הוה\u0004 \u0005[הרי היה]\u0006 \u0003חזקיה\u0004 המלך, שלא היה בדורו כמותו! ומשיבים: \u0003הוה\u0004 \u0005[היה]\u0006 \u0003שבנא\u0004 הסופר מפי המסורת שהיה גדול בתורה. ושואלים: \u0003והא איקטיל\u0004 \u0005[והרי נהרג\u0006 שבנא\u0005]!\u0006 ומשיבים: \u0003כולהו שניה קאמרינן\u0004 \u0005[כל שנותיו אמרנו].\u0006 \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003עזרא!\u0004 ומשיבים: \u0003הוה\u0004 \u0005[היה]\u0006 בזמנו \u0003נחמיה בן חכליה\u0004 שהיה כמותו בגדולה. ואם כן, עד רבי לא היה אדם שיהיה גדול הדור בתורה ובגדולה כאחד.","\u0003אמר רב אדא בר אהבה: אף אני אומר\u0004 מעין זה: \u0003מימות רבי עד רב אשי לא מצינו תורה וגדולה במקום אחד.\u0004 ותוהים: \u0003ו\u0004כי \u0003לא\u0004 היה כדבר הזה? \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003הונא בר נתן!\u0004 ומשיבים: \u0003הונא בר נתן\u0004 עצמו \u0003מיכף הוה כייף ליה\u0004 \u0005[כפוף היה לו]\u0006 \u0003לרב אשי,\u0004 ואף שגם הוא גדול בתורה ובגדולה, מכל מקום רב אשי גדול היה ממנו.","שנינו במשנה ש\u0003דיני נפשות מתחילין\u0004 להתברר בבית הדין \u0003מן הצד.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר ר' אחא בר פפא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא תענה על רב\"\u0004 (שמות כג, ב), ונדרש כפי הכתוב — \u0003לא תענה על רב,\u0004 כלומר, אל תתווכח עם הרב, הגדול שבדיינים. וכיון שכך, אם יפתח הגדול לחובת הנאשם שוב לא ירצו האחרים לומר דבר לזכותו.","\u0003רבה בר בר חנה אמר\u0004 בשם \u0003ר' יוחנן: מהכא\u0004 \u0005[מ\u0006כתוב \u0005זה]\u0006 נלמד הדבר, שנאמר לפני שרצה דוד להחליט להעניש את נבל הכרמלי: \u0003\"ויאמר דוד לאנשיו חגרו איש את חרבו, ויחגרו איש את חרבו ויחגר גם דוד את חרבו\"\u0004 (שמואל א' כה, יג), ושם דין נפשות היה, ודוד, הגדול שבהם, היה האחרון. משמע שבדיני נפשות גדול שבכולם מדבר אחרון.","\u0003אמר רב: שונה אדם לתלמידו\u0004 ואומר לו את מסורת ההלכה שבאותו ענין, \u0003ודן עמו בדיני נפשות\u0004 שיכול אף תלמיד זה להצטרף ולהיות כאחד הדיינים. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על הדבר ממה ששנינו במקום אחר בתוספתא: בדיני \u0003הטהרות והטמאות, האב ובנו, הרב ותלמידו\u0004 — \u0003מונין להם שנים\u0004 כשתי דעות. ואילו ב\u0003דיני ממונות ודיני נפשות ודיני מכות,\u0004 וכן בדיני \u0003קידוש החדש ועיבור שנה\u0004 — במקרים אלה \u0003אב ובנו, הרב ותלמידו אין מונין להן אלא אחד,\u0004 שהרי הבן נגרר אחר דעת אביו והתלמיד אחר דעת רבו."],["ומסבירים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב\u0004 את דבריו לא בכל תלמיד אמר, אלא \u0003כגון\u0004 תלמידיו \u0003רב כהנא ורב אסי, דלגמריה\u0004 \u0005[שלמסורותיו]\u0006 של \u0003רב הוו צריכי\u0004 \u0005[היו צריכים],\u0006 \u0003ולסבריה\u0004 \u0005[ו\u0006אולם \u0005לסברותיו]\u0006 של \u0003רב לא הוו צריכי\u0004 \u0005[היו צריכים],\u0006 שהוא קיבל מרבותיו דברים שלא היו ידועים להם, אבל אחר שמסר להם מסורת שהיתה בידו מרבותיו, יכולים היו לדון באופן עצמאי, ולא היו כפופים לו.","\u0003אמר ר' אבהו: עשרה דברים יש בין דיני ממונות לדיני נפשות\u0004 ששנינו בראשית הפרק, \u0003וכולן,\u0004 כל אותם דברים שמחמירים בדיני נפשות, \u0003אין נוהגין בשור הנסקל,\u0004 אלא נוהגים בו כבדיני ממונות, \u0003חוץ מ\u0004זה שדנים אותו ב\u0003עשרים ושלשה\u0004 כבדיני נפשות.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלו]\u0006 שאין צריך לדקדק על כך בדין שור הנסקל? \u0003אמר רב אחא בר פפא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא תטה משפט אבינך בריבו\"\u0004 (שמות כג, ו), ומכאן למדים כי \u0003משפט אביונך אי\u0004 (אין) \u0003אתה מטה,\u0004 שאתה דואג לאדם שילמדו כל זכות שאפשר ללמד עליו, \u0003אבל אתה מטה משפט של שור הנסקל,\u0004 כלומר, אין צורך להפוך בזכותו של השור ולחפש צד זכות לו.","ושואלים: כיצד אומר אתה שיש הבדל של \u0003\"עשרה\u0004 דברים \u0003\"?\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003תשעה הוו\u0004 \u0005[הם]\u0006 המנויים במשנה. ותוהים על השאלה: הא כיצד? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003עשרה\u0004 דברים \u0003קתני\u0004 \u0005[שנינו]!\u0006 ומסבירים: \u0003משום\u0004 ש\u0003אין הכל כשרין\u0004 לדון בדיני נפשות, \u0003ו\u0004ענין הדין ב\u0003עשרים ושלשה חדא\u0004 \u0005[אחת]\u0006 \u0003היא.\u0004","ומשיבים: \u0003הא איכא אחריתי\u0004 \u0005[הרי יש\u0006 עוד הבדל \u0005אחר],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מושיבין בסנהדרין זקן\u0004 מופלג \u0003וסריס ומי שאין לו בנים,\u0004 משום שכיון שאין להם בנים ואינם יודעים (או שכחו) צער גידול בנים, הרי הם מחמירים ביותר. \u0003ר' יהודה מוסיף: אף\u0004 אדם שידוע שהוא \u0003אכזרי\u0004 אין מושיבים אותו לדון בדיני נפשות. ומעירים: \u0003וחילופיהן במסית,\u0004 שמשתדלים להושיב בבית הדין הדן אותו אנשים קשים, \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]:\u0006 \u0003\"לא תחמל ולא תכסה עליו\"\u0004 (דברים יג, ט), שיש לדאוג שלא יחמלו וירחמו עליו.","שנינו במשנה ש\u0003הכל כשרין לדון דיני ממונות.\u0004 ושואלים: \u0003\"הכל\" לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]?\u0006 \u0003אמר רב יהודה: לאתויי\u0004 \u0005[להביא]\u0006 \u0003ממזר,\u0004 שאף הוא כשר לדיני ממונות.","ומקשים: \u0003הא תנינא חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005שנינו\u0006 דבר זה \u0005פעם אחת],\u0006 ששנינו: \u0003כל הראוי לדון דיני נפשות\u0004 — \u0003ראוי לדון דיני ממונות, ויש ראוי לדון דיני ממונות ואין ראוי לדון דיני נפשות. והוינן\u0004 \u0005[ועסקנו]\u0006 \u0003בה,\u0004 באותה משנה: זה ששנינו שיש ראוי לדיני ממונות ואינו ראוי לדיני נפשות \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 \u0003ואמר רב יהודה: לאתויי\u0004 \u0005[להביא]\u0006 \u0003ממזר!\u0004 ומשיבים: משנה \u0003חדא\u0004 \u0005[אחת]\u0006 באה לא לממזר אלא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003גר\u0004 שכשר לדיני ממונות, \u0003וחדא לאתויי\u0004 \u0005[ואחת להביא]\u0006 \u0003ממזר.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכו\u0006 שתיהן\u0005],\u0006 ואין ללמוד זה מזה. \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 בענין \u0003גר,\u0004 היינו אומרים שגר כישראל הוא לכל דבר, כיון ש\u0003ראוי\u0004 הוא \u0003לבא בקהל, אבל ממזר\u0004 שאינו רשאי לבוא בקהל \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא.\u0004 ולהיפך: \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק \u0003ממזר,\u0004 היינו אומרים שממזר כשר לדיני ממונות כיון ש\u0003בא מטיפה כשרה\u0004 (של זרע) שהרי הוא מזרע ישראל, \u0003אבל גר\u0004 ש\u0003לא בא מטיפה כשרה\u0004 אלא מזרע גוי \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהא כשר אף לממונות, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר בשניהם.","עוד שנינו במשנה: ש\u0003אין הכל כשרין לדון דיני נפשות.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומשיבים: \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף: כשם שבית דין\u0004 צריכים להיות \u0003מנוקים בצדק\u0004 שלא יהא פגם בצדקתם ותורתם, \u0003כך\u0004 צריכים הם להיות \u0003מנוקין מכל מום\u0004 שביוחסין. \u0003אמר אמימר: מאי קרא\u0004 \u0005[מה הכתוב]\u0006 המרמז על כך? שנאמר: \u0003\"כלך יפה רעיתי ומום אין בך\"\u0004 (שיר השירים ד, ד).","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 הכוונה ל\u0003מום\u0004 גופני \u0003ממש? אמר רב אחא בר יעקב: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004אספה לי שבעים איש מזקני ישראל... \u0003והתיצבו שם עמך\"\u0004 (במדבר יא, טז), וכוונתו: \u0003\"עמך\"\u0004 — \u0003בדומין לך\u0004 שאף הם ממשפחות מיוחסות שבישראל.","ומקשים: \u0003ודילמא התם\u0004 \u0005[ושמא שם]\u0006 \u0003משום שכינה?\u0004 שהרי אותם שבעים זקנים לא שופטים בלבד נעשו אלא אף נביאים, ולהשראת השכינה צריך שיהיה אדם ראוי ומיוחס אבל אין הדבר הכרחי בשעת הדין! ומשיבים: \u0003אלא אמר רב נחמן בר יצחק,\u0004 הראיה היא ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במינוי שופטים לישראל: \u0003\"ונשאו אתך\"\u0004 (שמות יח, כב), ולמדים: \u0003\"אתך\"\u0004 — \u0003בדומין לך ליהוי\u0004 \u0005[שיהיו].\u0006","\u0003סנהדרין\u0004 של עשרים ושלושה \u0003היתה\u0004 יושבת \u0003כחצי גורן עגולה, כדי שיהו\u0004 כל הדיינים \u0003רואין זה את זה\u0004 ואת העדים. \u0003ושני סופרי הדיינין עומדים לפניהם, אחד מימין ואחד משמאל, וכותבין\u0004 את \u0003דברי\u0004 ה\u0003מחייבין ו\u0004את \u0003דברי\u0004 ה\u0003מזכין. ר' יהודה אומר: שלשה\u0004 סופרים היו, \u0003אחד כותב\u0004 את \u0003דברי המזכין\u0004 בלבד, \u0003ואחד כותב\u0004 את \u0003דברי המחייבין\u0004 בלבד, \u0003והשלישי כותב\u0004 גם את \u0003דברי המזכין ו\u0004גם את \u0003דברי המחייבין,\u0004 שאם יהא ערעור על דיוק הדברים שכתב אחד הסופרים, ישוו עם דברי הסופר השלישי."],["\u0003ושלש שורות של תלמידי חכמים יושבין לפניהן, כל אחד ואחד\u0004 מן היושבים \u0003מכיר את מקומו,\u0004 שיש לו מקום קבוע בשורה לפי מעלתו בתורה. \u0003הוצרכו לסמוך\u0004 דיין נוסף וכגון שמת אחד מהם, או שנחלקו הסנהדרין באופן שהוצרכו הסנהדרין לסמוך עוד דיין למניינם — \u0003סומכין\u0004 את הגדול ש\u0003מן\u0004 השורה \u0003הראשונה,\u0004 ומכיון שנתפנה מקום בשורה הראשונה יש להושיב שם אחר, ואז \u0003אחד מן\u0004 השורה \u0003השניה בא לו ל\u0004שורה ה\u0003ראשונה,\u0004 ו\u0003אחד מן\u0004 השורה \u0003השלישית בא לו ל\u0004שורה ה\u0003שניה,\u0004 ו\u0003בוררים להן עוד אחד\u0004 הראוי לכך \u0003מן הקהל ומושיבין אותו ב\u0004שורה ה\u0003שלישית.\u0004 \u0003ולא היה יושב\u0004 זה שעבר מהשורה השניה \u0003במקומו של\u0004 ה\u0003ראשון\u0004 שנתפנה עקב עלייתו לסנהדרין, \u0003אלא יושב במקום הראוי לו\u0004 לפי מעלתו בסוף השורה.","שנינו במשנה שהיו הסנהדרין יושבים בחצי גורן עגולה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר ר' אחא בר חנינא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"שררך אגן הסהר אל יחסר המזג\u0004 בטנך ערמת חיטים סוגה בשושנים","\u0003\"\u0004(שיר השירים ז, ג), \u0003\"שררך\"\u0004 — \u0003זו סנהדרין,\u0004 ו\u0003למה נקרא שמה\u0004 ברמז \u0003\"שררך\"?\u0004 — \u0003שהיא יושבת בטיבורו\u0004 (שרר) \u0003של עולם,\u0004 בבית המקדש. \u0003\"אגן\"\u0004 — \u0003שהיא מגינה\u0004 בזכותה \u0003על כל העולם כולו. \"הסהר\"\u0004 — \u0003שהיא דומה לסהר\u0004 (ירח) וכך יושבים בחצי עיגול, כסהר.","\u0003\"אל יחסר המזג\"\u0004 — שיהיו כמזג של יין במים, שיש בו שליש אחד יין, כך \u0003שאם הוצרך אחד מהם\u0004 מחברי סנהדרין גדולה \u0003לצאת, רואין אם יש עשרים ושלשה\u0004 מן הדיינים, \u0003כנגד סנהדרי קטנה\u0004 שהם שליש ממנין החברים חוץ ממנו — הריהו \u0003יוצא, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינו יוצא,\u0004 אלא ממתין עד שיחזור אחד מחבריו.","\u0003\"בטנך ערמת חטים\"\u0004 — לימד: \u0003מה ערימת חטים הכל נהנין ממנה, אף סנהדרין הכל נהנין מטעמיהן\u0004 שהם נותנים לדברי תורה. \u0003\"סוגה בשושנים\"\u0004 — הוא בשבח ישראל: \u0003שאפילו כסוגה\u0004 (גדר) \u0003של שושנים\u0004 בכל זאת \u0003לא יפרצו בהן פרצות,\u0004 משום שישראל שומרים את התורה ומכבדים את תקנות חכמיהם.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 כעין המעשה ש\u0003אמר ליה ההוא מינא\u0004 \u0005[לו מין אחד]\u0006 \u0003לרב כהנא: אמריתו נדה שרי לייחודי בהדי גברא\u0004 \u0005[אומרים אתם\u0006 כי \u0005נדה מותרת בייחוד עם בעלה],\u0006 \u0003אפשר אש\u0004 נמצאת \u0003ב\u0004תוך \u0003נעורת\u0004 (פשתן מנופץ) \u0003ואינה מהבהבת\u0004 וחורכת משהו? היתכן שלא יחטאו בנדה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התורה העידה עלינו \"סוגה בשושנים\", שאפילו כסוגה בשושנים לא יפרצו בהן פרצות.\u0004","\u0003ריש לקיש אמר: מהכא\u0004 \u0005[מכאן]\u0006 יש ללמוד רעיון דומה, שנאמר: \u0003\"כפלח הרמון רקתך\"\u0004 (שיר השירים ד, ג), והוא דורשו: \u0003אפילו ריקנין שבך מלאין\u0004 \u0003מצות כרמון\u0004 ונזהרים מן העבירה. \u0003ר' זירא אמר: מהכא\u0004 \u0005[מכאן],\u0006 יש ללמוד דבר זה, שנאמר: \u0003\"וירח את ריח בגדיו\u0004 ויברכהו ויאמר ראה ריח בני כריח שדה אשר ברכו ה'\u0003\"\u0004 (בראשית כז, כז), \u0003אל תיקרי \"בגדיו\" אלא \"בוגדיו\",\u0004 שאפילו בוגדים ופושעים שבישראל יש בהם מידות נעלות \"כריח השדה אשר ברכו ה' \".","וכן מסופר כי \u0003הנהו בריוני דהוה בשיבבותיה\u0004 \u0005[אותם בריונים שהיו בשכנותו]\u0006 של \u0003ר' זירא, דהוה מקרב להו כי היכי דניהדרו להו בתיובתא\u0004 \u0005[שהיה מקרבם\u0006 כדי \u0005שיחזרו בתשובה],\u0006 \u0003והוו קפדי רבנן\u0004 \u0005[והיו מקפידים חכמים]\u0006 עליו, על שהוא מקרב אותם. \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' זירא, אמרי\u0004 \u0005[אמרו]\u0006 אותם בריונים: \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003הוה חריכא קטין שקיה דהוה בעי עלן רחמי\u0004 \u0005[היה החרוך קטן השוקיים,\u0006 שהוא כינוי לר' זירא, \u0005שהיה מבקש עלינו רחמים]\u0006 שלא נענש על חטאינו המרובים, \u0003השתא מאן בעי עלן רחמי\u0004 \u0005[עכשיו מי יבקש עלינו רחמים]?\u0006 \u0003הרהרו בלבייהו\u0004 \u0005[בליבם],\u0006 \u0003ועבדו\u0004 \u0005[ועשו]\u0006 \u0003תשובה,\u0004 הרי יפה עשה שקרבם שלבסוף אף הם חזרו בתשובה.","שנינו במשנה כי \u0003שלש שורות\u0004 היו שם והעולה מראש שורה אחורית יושב בסוף שורה שלפניה. \u0003אמר אביי: שמע מינה כי ניידי\u0004 \u0005[כאשר זזים]\u0006 הם ממקום אחד — \u0003כולהו ניידי\u0004 \u0005[כולם\u0006 כאחד \u0005זזים].\u0006 ואומרים: \u0003ולימא להו\u0004 \u0005[ושיאמר להם]\u0006 זה שעלה משורה שניה לשורה ראשונה: \u0003עד האידנא הוה יתיבנא ברישא\u0004 \u0005[עד עכשיו הייתי יושב בראש\u0006 השורה\u0005],\u0006 \u0003השתא מותביתו לי בדנבי\u0004 \u0005[עכשיו מושיבים אתם אותי בזנבות,\u0006 בסוף\u0005]!\u0006 \u0003אמר אביי: דאמרי ליה הכי\u0004 \u0005[שאומרים לו כך]\u0006 כמאמר החכם: \u0003הוי זנב לאריות ואל תהי ראש לשועלים,\u0004 שראוי לאדם להיות אחרון בין הגדולים מאשר ראשון לקטנים.","\u0003כיצד מאיימין את העדים\u0004 שלא ישקרו? — \u0003על עידי נפשות\u0004 היו מאיימים כך: \u0003היו מכניסין אותן ומאיימין עליהן,\u0004 ואומרים להם: \u0003שמא תאמרו מאומד\u0004 (מן ההשערה) שלכם כיצד היה המאורע, או שאתם יודעים זאת לא ממה שראיתם אתם אלא \u0003משמועה,\u0004 או \u0003עד מפי עד,\u0004 או \u0003מפי אדם נאמן\u0004 ולא ראיתם ממש? \u0003שמא אי\u0004 (אין) \u0003אתם יודעין שסופנו לבדוק אתכם בדרישה ובחקירה,\u0004 ואם לא ראיתם ממש יתגלה השקר.","ועוד: \u0003הוו יודעין שלא כדיני ממונות דיני נפשות. דיני ממונות\u0004 — \u0003אדם נותן ממון\u0004 שלקח שלא כדין \u0003ומתכפר לו, דיני נפשות\u0004 — \u0003דמו\u0004 של הנרצח \u0003ודם זרעותיו\u0004 שלא זכה להוליד \u0003תלויין בו\u0004 בגורם למותו \u0003עד סוף העולם,\u0004","\u0003שכן מצינו בקין שהרג את אחיו, שנאמר\u0004 בו: \u0003\"\u0004קול \u0003דמי אחיך צעקים\"\u0004 (בראשית ד, י), ש\u0003אינו אומר \"דם אחיך\" אלא \"דמי אחיך\"\u0004 ללמד שגם \u0003דמו ו\u0004גם \u0003דם זרעותיו.\u0004 אגב הזכרת פסוק זה מביאים במשנה \u0003דבר אחר\u0004 שיש לפרש באותו פסוק: \u0003\"דמי אחיך\"\u0004 — \u0003שהיה דמו\u0004 לא במקום אחד אלא \u0003מושלך על העצים ועל האבנים.\u0004","ועוד אומרים להם לעדים: \u0003לפיכך נברא אדם יחידי, ללמדך שכל המאבד נפש אחת מישראל, מעלה עליו\u0004 (מחשיב לו) \u0003הכתוב כאילו איבד עולם מלא,\u0004 שהרי אדם הראשון רק נפש אחת היה והוא כל קיום העולם, האנושות. \u0003ו\u0004כן, \u0003כל המקיים נפש אחת מישראל, מעלה עליו הכתוב כאילו קיים עולם מלא.\u0004","\u0003ו\u0004עוד מביאים במשנה טעם למה נברא האדם יחידי: \u0003מפני שלום הבריות. ש\u0004אילו \u0003לא\u0004 נבראו כולם מאב אחד \u0003יאמר אדם לחבירו \"אבא\u0004 שלי הראשון במשפחתנו \u0003גדול מאביך\",\u0004 אלא כל בני האדם בני אב אחד הם. \u0003ו\u0004עוד טעם: \u0003שלא יהו המינים\u0004 המאמינים בשתי רשויות \u0003אומרים: הרבה רשויות בשמים,\u0004 את אלה ברא ה' ואלה ברא אל זר, ולכן נברא אדם יחידי, שידעו שה' בראו.","\u0003ו\u0004עוד טעם: \u0003להגיד גדולתו של הקדוש ברוך הוא, שאדם\u0004 אם \u0003טובע כמה מטבעות בחותם אחד\u0004 — \u0003כולן דומין זה לזה, ו\u0004אילו \u0003מלך מלכי המלכים הקדוש ברוך הוא טבע כל אדם בחותמו של אדם הראשון,\u0004 שכולם צאצאיו, \u0003ואין אחד מהן דומה לחבירו, לפיכך\u0004 כיון שכל העולם נברא מאדם אחד \u0003כל אחד ואחד חייב לומר: בשבילי נברא העולם\u0004 וחשוב אני, ומעשה טוב שלי — הוא תכלית גדולה בעולם, מעשה רע שלי — שובר את כל העולם.","ועוד אומרים לעדים: \u0003ושמא תאמרו\u0004"],["\u0003מה לנו ולצרה הזאת\u0004 להכנס בענין חמור כל כך ומוטב שלא נעיד כלל — על כך יש לכם לדעת: \u0003והלא כבר נאמר \"והוא עד או ראה או ידע אם לוא יגיד\u0004 ונשא עוונו\u0003\"\u0004 (ויקרא ה, א). \u0003ושמא תאמרו: מה לנו לחוב בדמו של זה\u0004 ואפילו אם אסור הדבר מוטב שלא נהא אחראים להריגת אדם — על כך יש לכם לדעת: \u0003והלא כבר נאמר \"\u0004ו\u0003באבד רשעים רנה\"\u0004 (משלי יא, י).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003כיצד\u0004 היא עדות \u0003מאומד\u0004 שיש להזהיר את העדים שלא יעידו? — \u0003אומר להן\u0004 הדיין לעדים: \u0003שמא כך ראיתם שרץ\u0004 אותו אדם שאתם מאשימים ברצח \u0003אחר חבירו לחורבה, ורצתם אחריו ומצאתם סייף\u0004 (חרב) \u0003בידו, ודמו\u0004 של הסייף \u0003מטפטף והרוג\u0004 \u0003מפרפר, אם כך\u0004 בלבד \u0003ראיתם\u0004 — \u0003לא ראיתם כלום,\u0004 ואינכם יכולים להעיד על הרצח, שלא ראיתם את המעשה בעיניכם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן שטח\u0004 בלשון שבועה: \u0003אראה בנחמה\u0004 שתבוא באחרית הימים לעם ישראל, \u0003אם לא ראיתי\u0004 מעשה כגון זה, שאדם \u0003אחד רץ אחר חבירו לחורבה ורצתי אחריו וראיתי סייף בידו, ודמו\u0004 של הסייף \u0003מטפטף והרוג\u0004 \u0003מפרפר, ואמרתי לו\u0004 לאותו אדם: \u0003רשע, מי הרגו לזה? או אני או אתה. אבל מה אעשה שאין דמך מסור בידי, שהרי אמרה תורה \"על פי שנים עדים... יומת המת\"\u0004 (דברים יז, ו) ואין אני יכול להעיד עליך. אלא ה' \u0003היודע מחשבות יפרע מאותו האיש שהרג את חבירו. אמרו: לא זזו משם עד שבא נחש והכישו\u0004 (נשכו) \u0003ומת.\u0004","על סיפור זה תוהים: \u0003והאי\u0004 \u0005[וזה,\u0006 הרוצח\u0005]\u0006 \u0003בר נחש הוא\u0004 (ראוי הוא למות במיתה קשה זו על ידי נחש)? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף, וכן תני\u0004 \u0005[שנה]\u0006 חכם \u0003דבי\u0004 \u0005[מבית מדרשו של]\u0006 \u0003חזקיה: מיום שחרב בית\u0004 \u0003המקדש אף על פי שבטלה סנהדרי,\u0004 מכל מקום \u0003ארבע מיתות לא בטלו.\u0004 ותוהים: \u0003לא בטלו?\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בטלו! אלא\u0004 הכוונה היא ש\u0003דין ארבע מיתות לא בטלו,\u0004 והן מתקיימות בידי שמים בפושעים. כיצד?","\u0003מי\u0004 \u0003שנתחייב סקילה\u0004 — \u0003או\u0004 שהוא \u0003נופל מן הגג, או\u0004 ש\u0003חיה דורסתו,\u0004 והרי זה כעין עונש סקילה שהיה בבית דין. \u0003מי\u0004 \u0003שנתחייב שריפה\u0004 — \u0003או\u0004 שהוא \u0003נופל בדליקה\u0004 ונשרף, \u0003או נחש מכישו\u0004 שארס הנחש מכאיב כשריפה. \u0003מי שנתחייב הריגה\u0004 בסייף — \u0003או\u0004 שהוא \u0003נמסר למלכות\u0004 ונידון על ידה בדיני הגויים בסייף, \u0003או\u0004 ש\u0003ליסטין\u0004 (שודדים, גנבים) \u0003באין עליו\u0004 והורגים אותו. \u0003מי שנתחייב חנק\u0004 — \u0003או\u0004 שהוא \u0003טובע בנהר\u0004 ונחנק במים, \u0003או\u0004 ש\u0003מת בסרונכי\u0004 (אסכרה) ואף היא מיתת חניקה. ולפי זה הרוצח שדינו בסנהדרין הריגה, אינו ראוי שימיתנו נחש, שהוא עונש קשה שרק החייבים שריפה נדונים בו.","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 האדם \u0003ההוא חטא אחריתי הוה ביה\u0004 \u0005[אחר היה בו]\u0006 שבגללו היה ראוי לשריפה, ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003מי שנתחייב שתי מיתות בית דין\u0004 הריהו \u0003נידון בחמורה\u0004 שבהן, ואף אותו אדם נידון במיתה החמורה.","שנינו במשנה שמזהירים את העדים שלא יעידו \u0003מאומד.\u0004 ומעירים: \u0003בדיני נפשות הוא דלא אמדינן\u0004 \u0005[שאין אנו אומדים]\u0006 אלא מעידים רק מה שראו עינינו ממש. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בדיני\u0004 \u0003ממונות אמדינן\u0004 \u0005[אומדים אנו].\u0006 \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 תהא איפוא משנתנו? — \u0003כ\u0004שיטת \u0003ר' אחא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אחא אומר: גמל האוחר\u0004 (גמל מיוחם, המזיק את חבריו) \u0003בין הגמלים, ונמצא גמל הרוג בצידו\u0004 — \u0003בידוע שזה הרגו\u0004 אף שלא ראינו זאת, ובעל הגמל יצטרך לשלם.","את הטענה הזו דוחים: דיוק זה איננו מחוייב, \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שמה שאמרו כאן הוא בדיני נפשות בלבד, \u0003\"עד מפי עד\" דקתני\u0004 \u0005[ששנינו],\u0006 וכי \u0003בדיני נפשות הוא דלא אמרינן\u0004 \u0005[שאין אנו אומרים]\u0006 ומקבלים עדות כזו, \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003בדיני ממונות אמרינן\u0004 \u0005[אומרים אנו]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אם אמר\u0004 העד: \u0003\"הוא,\u0004 הנתבע, \u0003אמר לי שאני חייב לו,\u0004 לתובע \u0003\",\u0004 ולא אמר כן בפני התובע, או שאמר \u0003\"איש פלוני אמר לי שהוא חייב לו\"\u0004 — \u0003לא אמר כלום, עד שיאמר: \"בפנינו הודה לו\u0004 הנתבע לתובע \u0003שהוא חייב לו מאתים זוז\".\u0004","\u0003אלמא\u0004 \u0005[מכאן]:\u0006 \u0003אף על גב דפסילי\u0004 \u0005[אף על פי שפסולים\u0006 דברים אלה\u0005]\u0006 גם \u0003בדיני ממונות,\u0004 מכל מקום \u0003אמרינן להו\u0004 \u0005[אומרים אנו אותם]\u0006 \u0003בדיני נפשות,\u0004 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין עדות מאומד אפשר לומר ש\u0003אף על גב דפסילי\u0004 \u0005[אף על פי שפסולות]\u0006 עדויות כאלה, \u0003בדיני ממונות אמרינן להו\u0004 \u0005[אומרים אנו אותן]\u0006 ומזהירים גם \u0003בדיני נפשות.\u0004","שנינו במשנה שהיו מספרים לעדים בענין קין שהרג את הבל, והיו אומרים להם: \u0003הוו יודעים וכו'.\u0004 \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: מלמד שעשה קין בהבל אחיו חבורות חבורות, פציעות פציעות,\u0004 משום \u0003שלא היה יודע מהיכן נשמה יוצאה,\u0004 והתכוון להרגו ולא ידע כיצד, \u0003עד שהגיע לצוארו\u0004 ולכן נאמר \"דמי\" — ששפך דמו במקומות רבים.","\u0003ואמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: מיום שפתחה הארץ את פיה וקיבלתו לדמו של הבל, שוב לא פתחה, שנאמר: \"מכנף הארץ זמרת שמענו צבי לצדיק\"\u0004 (ישעיה כד, טז), \u0003\"מכנף הארץ\"\u0004 — \u0003ולא \"מפי הארץ\",\u0004 שלא פתחה עוד את פיה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003חזקיה אחיו:\u0004 והרי נאמר בקורח ועדתו: \u0003\"ותפתח הארץ את פיה\u0004 ותבלע אותם ואת בתיהם ואת כל האדם אשר לקורח ואת כל הרכוש\u0003\"\u0004 (במדבר טז, לב), \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לרעה פתחה\u0004 הארץ את פיה, אבל \u0003לטובה\u0004 שוב \u0003לא פתחה. ו\u0004עוד","\u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: גלות מכפרת עון מחצה,\u0004 שמחצית העוון נמחלת על ידי גלות. ומהיכן נלמד הדבר — \u0003מעיקרא כתיב\u0004 \u0005[מתחילה נאמר]\u0006 בקין: \u0003\"והייתי נע ונד\"\u0004 (בראשית ד, יד), \u0003ולבסוף כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וישב בארץ נוד\"\u0004 (בראשית ד, טז), שאמנם נד אך לא היה צריך לנוע, משמע שמחצית עונשו נתכפרה לו.","אגב אימרה זו מביאים את מה ש\u0003אמר רב יהודה: גלות מכפרת\u0004 על \u0003שלשה דברים, שנאמר: \"כה אמר ה'... הישב בעיר הזאת ימות בחרב\u0004 ו\u0003ברעב ובדבר והיוצא ונפל על הכשדים הצרים עליכם (יחיה) [וחיה] והיתה לו נפשו לשלל\"\u0004 (ירמיה כא, ח–ט), משמע שהגולה מירושלים ינצל משלוש מיתות אלה.","\u0003ר' יוחנן אמר: גלות מכפרת על הכל,\u0004 והריהו כאדם חדש, \u0003שנאמר: \"כה אמר ה' כתבו את האיש הזה ערירי גבר לא יצלח בימיו כי לא יצלח מזרעו איש ישב על כסא דוד ומשל עוד ביהודה\"\u0004 (ירמיה כב, ל), \u0003ובתר\u0004 \u0005[ואחר]\u0006 ש\u0003גלה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ובני יכניה אסר שאלתיאל בנו\"\u0004 (דברי הימים א' ג, טז), כיון שנאמר \"ובני\" בבנו האחד, דורשים שני שמות אלה ככינויים, הבן נקרא \u0003\"אסר\"\u0004 — \u0003שעיברתו אמו בבית האסורין, \"שלתיאל\"\u0004 — מלמד \u0003ששתלו\u0004 (הולידו) \u0003אל שלא כדרך הנשתלין. גמירי\u0004 \u0005[למודים אנו מסורת]\u0006 \u0003שאין האשה מתעברת\u0004 כשהיתה הביאה \u0003מעומד\u0004 (בעמידה)"]]};
